  CONSTRAINT `fk_project_assessment_objective` FOREIGN KEY (`objective_id`) REFERENCES `project_objective` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_project_assessment_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 9044 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目评价任务表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_assessment
-- ----------------------------

-- ----------------------------
-- Table structure for project_objective
-- ----------------------------
DROP TABLE IF EXISTS `project_objective`;
CREATE TABLE `project_objective`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '目标ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '学习目标',
  `sequence_no` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '排序',
  `standard_refs_json` json NULL COMMENT '对应课程标准ID',
  `literacy_refs_json` json NULL COMMENT 'AI素养ID',
  `rationale` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '推荐理由',
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'AI' COMMENT 'AI/TEACHER',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ACCEPT/REVISE/REJECT',
  `confirmed` tinyint NOT NULL DEFAULT 0 COMMENT '是否确认',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_objective_project`(`project_id` ASC, `sequence_no` ASC) USING BTREE,
  INDEX `idx_project_objective_confirmed`(`project_id` ASC, `confirmed` ASC) USING BTREE,
  CONSTRAINT `fk_project_objective_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 6020 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目学习目标表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_objective
-- ----------------------------

-- ----------------------------
-- Table structure for project_pedagogy
-- ----------------------------
DROP TABLE IF EXISTS `project_pedagogy`;
CREATE TABLE `project_pedagogy`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `primary_method_id` bigint UNSIGNED NULL DEFAULT NULL,
  `secondary_method_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '辅助教学法',
  `rationale` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '推荐理由',
  `suitable_for_json` json NULL COMMENT '适用目标',
  `risk_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '风险',
  `alternative_json` json NULL COMMENT '备选方案',
  `teacher_action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ACCEPT/REVISE',
  `confirmed` tinyint NOT NULL DEFAULT 0 COMMENT '是否确认',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '版本',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `custom_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `custom_description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `source_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_pedagogy_project`(`project_id` ASC, `confirmed` ASC) USING BTREE,
  INDEX `idx_project_pedagogy_primary_method`(`primary_method_id` ASC) USING BTREE,
  INDEX `idx_project_pedagogy_secondary_method`(`secondary_method_id` ASC) USING BTREE,
  CONSTRAINT `fk_project_pedagogy_primary_method` FOREIGN KEY (`primary_method_id`) REFERENCES `pedagogy_method` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_project_pedagogy_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_project_pedagogy_secondary_method` FOREIGN KEY (`secondary_method_id`) REFERENCES `pedagogy_method` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 7009 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目教学法决策表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of project_pedagogy
-- ----------------------------

-- ----------------------------
-- Table structure for quality_check
-- ----------------------------
DROP TABLE IF EXISTS `quality_check`;
CREATE TABLE `quality_check`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '项目',
  `check_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '检查类型',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PASS/ATTENTION/REVISION_REQUIRED',
  `issue` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '问题',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原因',
  `suggestion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '修改建议',
  `evidence_json` json NULL COMMENT '判断证据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_quality_check_project_status`(`project_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_quality_check_type`(`project_id` ASC, `check_type` ASC) USING BTREE,
  CONSTRAINT `fk_quality_check_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 12061 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '教学智检结果表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of quality_check
-- ----------------------------

-- ----------------------------
-- Table structure for research_analysis
-- ----------------------------
DROP TABLE IF EXISTS `research_analysis`;
CREATE TABLE `research_analysis`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '研究分析ID',
  `resource_id` bigint UNSIGNED NULL DEFAULT NULL,
  `project_id` bigint UNSIGNED NOT NULL COMMENT '所属课程设计项目ID',
  `participants_json` json NULL COMMENT '研究对象：学段、年级、样本量、描述等',
  `research_topic` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '研究主题',
  `ai_literacy_json` json NULL COMMENT 'AI素养维度',
  `teaching_strategies_json` json NULL COMMENT '研究中采用的教学策略',
  `intervention_json` json NULL COMMENT '干预时间、课时、周期等',
  `assessment_tools_json` json NULL COMMENT '研究中使用的评价工具',
  `main_findings_json` json NULL COMMENT '主要研究结果',
  `limitations_json` json NULL COMMENT '研究局限',
  `agent_summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '系统/AI形成的研究综合说明，当前Mock阶段可为空',
  `agent_raw_json` json NULL COMMENT '模型原始结构化输出，当前Mock阶段可为空',
  `field_sources_json` json NULL COMMENT '字段来源，例如TEACHER/MOCK/AI，用于保护教师人工修改',
  `readiness_score` tinyint UNSIGNED NOT NULL DEFAULT 0 COMMENT '证据卡信息完整度，0-100，仅用于展示',
  `readiness_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INCOMPLETE' COMMENT '证据卡准备状态：INCOMPLETE/READY',
  `teacher_confirmed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '教师是否确认当前结构化研究解析：0否，1是',
  `version` int UNSIGNED NOT NULL DEFAULT 1 COMMENT '分析版本号',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `structured_data_json` json NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'VALIDATED',
  `teacher_confirmed_at` datetime NULL DEFAULT NULL,
  `session_id` bigint UNSIGNED NULL DEFAULT NULL,
  `generation_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'READY',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_research_analysis_session_version`(`session_id` ASC, `version` ASC) USING BTREE,
  INDEX `idx_research_analysis_resource`(`resource_id` ASC) USING BTREE,
  INDEX `idx_research_analysis_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_research_analysis_readiness`(`project_id` ASC, `readiness_status` ASC) USING BTREE,
  INDEX `idx_research_analysis_confirmed`(`resource_id` ASC, `teacher_confirmed` ASC) USING BTREE,
  INDEX `idx_research_analysis_session_status`(`session_id` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_research_analysis_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_analysis_resource` FOREIGN KEY (`resource_id`) REFERENCES `research_resource` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_analysis_session` FOREIGN KEY (`session_id`) REFERENCES `research_chat_session` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_research_analysis_generation_status` CHECK (`generation_status` in (_utf8mb4'PENDING',_utf8mb4'READY',_utf8mb4'FAILED'))
) ENGINE = InnoDB AUTO_INCREMENT = 77 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联研究资源结构化解析表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of research_analysis
-- ----------------------------

-- ----------------------------
-- Table structure for research_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `research_chat_message`;
CREATE TABLE `research_chat_message`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `session_id` bigint UNSIGNED NOT NULL COMMENT '所属会话ID',
  `role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息角色：USER/ASSISTANT/SYSTEM',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息正文',
  `message_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'TEXT' COMMENT '消息类型：TEXT/FILE/PROCESS/ANALYSIS_UPDATE/EVIDENCE_DRAFT',
  `metadata_json` json NULL COMMENT '扩展信息，如附件ID、resourceId、分析更新、来源引用等',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `sequence_no` int NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_research_chat_message_session`(`session_id` ASC) USING BTREE,
  INDEX `idx_research_chat_message_session_time`(`session_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_research_chat_message_role`(`session_id` ASC, `role` ASC) USING BTREE,
  INDEX `idx_research_chat_message_type`(`session_id` ASC, `message_type` ASC) USING BTREE,
  CONSTRAINT `fk_research_chat_message_session` FOREIGN KEY (`session_id`) REFERENCES `research_chat_session` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 207 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联多轮研究对话消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of research_chat_message
-- ----------------------------

-- ----------------------------
-- Table structure for research_chat_session
-- ----------------------------
DROP TABLE IF EXISTS `research_chat_session`;
CREATE TABLE `research_chat_session`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '对话会话ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '当前教师用户ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '所属课程设计项目ID',
  `resource_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '当前会话主要关联的研究资源ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '会话标题',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '会话状态：ACTIVE/COMPLETED/ARCHIVED',
  `evidence_card_id` bigint UNSIGNED NULL DEFAULT NULL COMMENT '本次会话最终生成的Evidence Card ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `conversation_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `conversation_summary_through_sequence_no` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_research_chat_session_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_research_chat_session_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_research_chat_session_resource`(`resource_id` ASC) USING BTREE,
  INDEX `idx_research_chat_session_project_status`(`project_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_research_chat_session_evidence`(`evidence_card_id` ASC) USING BTREE,
  CONSTRAINT `fk_research_chat_session_evidence` FOREIGN KEY (`evidence_card_id`) REFERENCES `evidence_card` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_research_chat_session_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_chat_session_resource` FOREIGN KEY (`resource_id`) REFERENCES `research_resource` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_research_chat_session_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 54 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联多轮研究对话会话表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of research_chat_session
-- ----------------------------

-- ----------------------------
-- Table structure for research_resource
-- ----------------------------
DROP TABLE IF EXISTS `research_resource`;
CREATE TABLE `research_resource`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '研究资源ID',
  `user_id` bigint UNSIGNED NOT NULL COMMENT '资源所属用户ID',
  `project_id` bigint UNSIGNED NOT NULL COMMENT '所属课程设计项目ID',
  `resource_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPLOAD' COMMENT '资源来源：UPLOAD/SEARCH_RESULT',
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '论文或研究报告标题',
  `authors` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '作者',
  `year` smallint UNSIGNED NULL DEFAULT NULL COMMENT '发表年份',
  `file_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '用户上传时的原始文件名',
  `file_path` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '服务器实际文件保存路径',
  `mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件MIME类型',
  `file_size` bigint UNSIGNED NULL DEFAULT NULL COMMENT '文件大小，单位Byte',
  `source_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '外部文献来源URL',
  `doi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'DOI',
  `processing_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'UPLOADED' COMMENT '处理状态：UPLOADED/TEXT_EXTRACTING/TEXT_EXTRACTED/ANALYZING/ANALYZED/REVIEWED/CARD_READY/FAILED',
  `extracted_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '从PDF/DOCX提取的完整研究文本',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文件解析或处理失败信息',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `original_filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `storage_key` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `media_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `size_bytes` bigint UNSIGNED NULL DEFAULT NULL,
  `sha256` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `parsed_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `index_status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `parse_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_research_resource_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_research_resource_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_research_resource_project_status`(`project_id` ASC, `processing_status` ASC) USING BTREE,
  INDEX `idx_research_resource_type`(`resource_type` ASC) USING BTREE,
  INDEX `idx_research_resource_doi`(`doi` ASC) USING BTREE,
  INDEX `idx_research_resource_project_sha256`(`project_id` ASC, `sha256` ASC) USING BTREE,
  INDEX `idx_research_resource_project_index_status`(`project_id` ASC, `index_status` ASC) USING BTREE,
  CONSTRAINT `fk_research_resource_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_research_resource_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_research_resource_index_status` CHECK (`index_status` in (_utf8mb4'pending',_utf8mb4'parsing',_utf8mb4'indexing',_utf8mb4'ready',_utf8mb4'error'))
) ENGINE = InnoDB AUTO_INCREMENT = 36 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '研教智联原始研究资源表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of research_resource
-- ----------------------------

-- ----------------------------
-- Table structure for resource_ai_suggestion
-- ----------------------------
DROP TABLE IF EXISTS `resource_ai_suggestion`;
CREATE TABLE `resource_ai_suggestion`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `resource_id` bigint UNSIGNED NOT NULL,
  `base_version_id` bigint UNSIGNED NOT NULL,
  `target_block_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `suggestion_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `issue` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `suggested_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `teacher_revision` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `decided_at` datetime NULL DEFAULT NULL,
  `user_request` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `metadata_json` json NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_resource_ai_suggestion_resource`(`resource_id` ASC) USING BTREE,
  INDEX `idx_resource_ai_suggestion_base_version`(`base_version_id` ASC) USING BTREE,
  INDEX `idx_resource_ai_suggestion_resource_status`(`resource_id` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_resource_ai_suggestion_resource` FOREIGN KEY (`resource_id`) REFERENCES `teaching_resource` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_resource_ai_suggestion_version` FOREIGN KEY (`base_version_id`) REFERENCES `teaching_resource_version` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `ck_resource_ai_suggestion_status` CHECK (`status` in (_utf8mb4'PENDING',_utf8mb4'ACCEPTED',_utf8mb4'REVISED',_utf8mb4'REJECTED'))
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of resource_ai_suggestion
-- ----------------------------

-- ----------------------------
-- Table structure for resource_creation_job
-- ----------------------------
DROP TABLE IF EXISTS `resource_creation_job`;
CREATE TABLE `resource_creation_job`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `project_id` bigint UNSIGNED NOT NULL,
  `user_id` bigint UNSIGNED NOT NULL,
  `mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'COURSE_GENERATE',
  `selected_types_json` json NULL,
  `common_settings_json` json NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `current_step` tinyint UNSIGNED NOT NULL DEFAULT 1,
  `resource_settings_json` json NULL,
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_resource_creation_job_project`(`project_id` ASC) USING BTREE,
  INDEX `idx_resource_creation_job_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_resource_creation_job_project_status`(`project_id` ASC, `status` ASC) USING BTREE,
  CONSTRAINT `fk_resource_creation_job_project` FOREIGN KEY (`project_id`) REFERENCES `course_project` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_resource_creation_job_user` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_resource_creation_job_mode` CHECK (`mode` in (_utf8mb4'COURSE_GENERATE',_utf8mb4'RESOURCE_ADAPT'))
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of resource_creation_job
-- ----------------------------

-- ----------------------------
-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录账号',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码Hash',
  `display_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '显示名称',
  `role` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'TEACHER/STUDENT/ADMIN',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1正常，0禁用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sys_user_username`(`username` ASC) USING BTREE,
  INDEX `idx_sys_user_role_status`(`role` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户表' ROW_FORMAT = Dynamic;

