INSERT INTO `course_project` VALUES (1022, 1, '智慧农业', '教学智能体', 'NEW_TOPIC', 6, 4, 'ADVANCED', 'INDIVIDUAL', '[\"COMPUTER\"]', '[\"LIMITED_TIME\"]', '无', 'QUALITY_CHECKED', '[\"PEDAGOGY\", \"ARTIFACT\"]', '2026-09-10 16:26:15', '2026-09-10 23:06:35', NULL, NULL, NULL, 40, NULL, 0);
INSERT INTO `course_project` VALUES (1023, 3, '智慧交通', '智慧驾驶', 'NEW_TOPIC', 4, 2, 'GENERAL', 'GROUP', '[\"COMPUTER\"]', '[\"LIMITED_DEVICES\"]', '学生基础较弱', 'QUALITY_CHECKED', '[\"OBJECTIVE\", \"PEDAGOGY\", \"ARTIFACT\"]', '2026-09-11 11:10:00', '2026-09-11 12:06:37', NULL, '能够基本掌握AI的交互使用', 42, 40, '{\"constraints\": [\"学生基础较弱导致学习节奏需放缓\", \"需依赖计算机设备开展教学\", \"课堂时间仅40分钟，需控制教学内容容量\"], \"coreProblem\": \"学生对智慧驾驶的核心概念与系统逻辑缺乏系统认知，难以在40分钟内建立完整的知识框架\", \"existingFoundation\": \"学生能基本掌握AI的交互使用，具备初步的技术操作能力\", \"learningDifficulties\": [\"智慧驾驶涉及的多系统协同原理理解难度大\", \"对智能决策算法与传感数据的关联缺乏深度认知\", \"在模拟场景中难以提取关键信息并作出合理判断\"]}', 0);
INSERT INTO `course_project` VALUES (1024, 3, '智慧农业', '采摘机器人', 'NEW_TOPIC', 5, 6, 'GENERAL', 'GROUP', '[\"COMPUTER\"]', '[\"LIMITED_TIME\"]', '学生基础较薄弱', 'QUALITY_CHECKED', '[\"OBJECTIVE\", \"PEDAGOGY\", \"ARTIFACT\"]', '2026-09-12 14:03:32', '2026-09-12 14:30:07', NULL, '学生掌握计算机基本操作', 38, 40, '{\"constraints\": [\"课堂时间仅40分钟，时间有限，需紧凑安排任务与讲解，避免因基础薄弱而拖慢进度。\", \"班级人数为38人，规模较大，需兼顾基础薄弱学生的适应需求，控制课堂互动与操作负担。\", \"教学设备仅提供计算机，需以计算机为主要操作平台，对设备条件存在依赖。\"], \"coreProblem\": \"五年级学生在“采摘机器人”主题教学中，虽具备计算机基本操作能力，但对该主题的工作原理、操作流程与实际应用的理解仍较薄弱，难以在40分钟课堂中有效完成与计算机操作结合的学习任务。\", \"existingFoundation\": \"学生已掌握计算机基本操作，具备基础计算机操作能力，但在此主题学习中基础相对薄弱，需要在现有基础上进一步提升。\", \"learningDifficulties\": [\"对采摘机器人的工作原理、任务流程以及计算机操作与机器人任务结合的实际应用理解不足。\", \"在计算机基本操作基础上完成采摘机器人相关任务时，因基础薄弱出现操作与认知衔接困难。\", \"将计算机基本操作迁移到采摘机器人具体场景时，抽象概念迁移能力不足，难以有效应用。\", \"面对课堂综合应用任务时，理解与操作结合困难，影响学习效果。\"]}', 0);
