INSERT INTO `design_evidence_link` VALUES (10001, 1001, 'OBJECTIVE', 6002, 5002, '评价信息可信度需要学生实际执行多来源核验。', '目标2要求学生使用至少两个来源核验AI生成内容。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10002, 1001, 'ACTIVITY', 8001, 5001, '学生在咨询AI前先形成自己的初步判断。', '活动1先要求学生独立判断，再进入AI互动。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10003, 1001, 'ACTIVITY', 8003, 5002, '多来源信息核验需要保留来源和证据记录。', '活动3要求学生填写“主张—来源—证据—判断”记录。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10004, 1001, 'ACTIVITY', 8004, 5003, '协作比较应围绕证据和理由展开。', '活动4中教师使用“你的证据是什么？”进行追问。', 'PARTIAL', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10005, 1001, 'ASSESSMENT', 9002, 5002, '评价任务应要求学生展示实际核验过程。', '评价2要求提交来源、关键证据和最终可信度判断。', 'SUPPORTED', '2026-08-25 15:00:35');
INSERT INTO `design_evidence_link` VALUES (10006, 1023, 'OBJECTIVE', 6016, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '在40分钟内，借助计算机模拟场景梳理智慧驾驶的传感、决策与执行三个核心环节，独立画出系统协同示意图', 'SUPPORTED', '2026-09-11 12:01:41');
INSERT INTO `design_evidence_link` VALUES (10007, 1023, 'OBJECTIVE', 6017, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '在使用数字工具分析智慧驾驶的模拟数据时，至少使用两个不同信息来源核验AI生成结果，并列出仍需人工检查的两处内容', 'SUPPORTED', '2026-09-11 12:01:41');
INSERT INTO `design_evidence_link` VALUES (10008, 1023, 'OBJECTIVE', 6018, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '在模拟智慧驾驶场景中，针对具体传感数据（如障碍物距离），判断AI输出的决策建议是否可靠，并说明至少一个判断依据', 'SUPPORTED', '2026-09-11 12:01:41');
INSERT INTO `design_evidence_link` VALUES (10009, 1023, 'PEDAGOGY', 7007, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '紧扣目标1梳理传感-决策-执行三环节，目标2以两个来源核验AI结果，目标3从具体传感数据判断AI输出，符合问题导向、证据驱动的探究流程。', 'SUPPORTED', '2026-09-11 12:02:10');
INSERT INTO `design_evidence_link` VALUES (10010, 1023, 'ACTIVITY', 8022, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '借助计算机模拟场景认识智慧驾驶中的传感、决策与执行核心环节，初步感知三环节协同关系', 'SUPPORTED', '2026-09-11 12:05:04');
INSERT INTO `design_evidence_link` VALUES (10011, 1023, 'ACTIVITY', 8023, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '独立梳理传感、决策、执行三环节的逻辑关系与协同路径，画出系统协同示意图', 'SUPPORTED', '2026-09-11 12:05:04');
INSERT INTO `design_evidence_link` VALUES (10012, 1023, 'ACTIVITY', 8024, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '使用数字工具分析智慧驾驶模拟数据，调用至少两个不同信息来源核验AI生成的分析结果，列出仍需人工检查的两处内容', 'SUPPORTED', '2026-09-11 12:05:04');
INSERT INTO `design_evidence_link` VALUES (10013, 1023, 'ACTIVITY', 8025, 5019, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', '基于具体传感数据（如障碍物距离）判断AI输出的驾驶决策建议是否可靠，说明至少一个判断依据', 'SUPPORTED', '2026-09-11 12:05:04');
INSERT INTO `evidence_card` VALUES (5001, 'DEMO Evidence A: Prior thinking before AI consultation', 'DEMO AUTHORS', 2026, 'AI信息核验与学生先行思考', 'PRIMARY', 'DEMO小学生样本', 'DEMO_QUASI_EXPERIMENT', 'N=60 (DEMO)', 'DEMO：在咨询AI前先形成初步观点的学生，更容易在后续讨论中比较AI建议与原有判断。', 'POSITIVE', '仅用于当前Demo逻辑验证。', '非真实研究，不可用于正式教学或论文引用。', 'PRELIMINARY', 'DEMO：让学生先表达自己的判断，再查看AI回答。', 'DEMO_SOURCE_NOT_REAL', 'N/A', 'DEMO SOURCE TEXT：学生先形成自己的判断，再接触AI建议，有助于后续比较与修正。', '学生 先形成观点 AI 信息核验 比较 修正 DEMO', 'evi_demo_5001', 'REVIEWED', '2026-08-25 15:00:35', NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5002, 'DEMO Evidence B: Multiple-source verification', 'DEMO AUTHORS', 2026, '多来源信息核验', 'PRIMARY', 'DEMO小学生样本', 'DEMO_CLASSROOM_STUDY', 'N=48 (DEMO)', 'DEMO：要求学生使用两个以上来源进行核验，可以增加对信息依据的关注。', 'POSITIVE', '需要教师提供可访问的信息来源。', '非真实研究，不可作为正式研究证据。', 'PRELIMINARY', 'DEMO：评价任务应要求学生展示核验来源和判断理由。', 'DEMO_SOURCE_NOT_REAL', 'N/A', 'DEMO SOURCE TEXT：多来源核验任务要求学生记录来源并说明不同来源是否一致。', '多来源 核验 证据 来源 判断 DEMO', 'evi_demo_5002', 'REVIEWED', '2026-08-25 15:00:35', NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5003, 'DEMO Evidence C: Collaborative comparison of AI outputs', 'DEMO AUTHORS', 2026, '协作比较AI输出', 'PRIMARY', 'DEMO小组学习样本', 'DEMO_MIXED_METHODS', 'N=54 (DEMO)', 'DEMO：同伴之间比较不同AI回答时，教师追问证据可帮助学生避免仅凭表面流畅度判断。', 'MIXED', '需要明确的比较标准和教师追问。', '非真实研究，不可作为正式研究证据。', 'PRELIMINARY', 'DEMO：在小组讨论中加入“你的证据是什么”的追问。', 'DEMO_SOURCE_NOT_REAL', 'N/A', 'DEMO SOURCE TEXT：协作比较需要围绕证据展开，而不是只比较AI回答是否听起来更完整。', '协作 AI回答 比较 证据 教师追问 DEMO', 'evi_demo_5003', 'REVIEWED', '2026-08-25 15:00:35', NULL, NULL, NULL, 'DRAFT', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5005, 'DEMO研究：小学高年级学生AI信息核验能力培养——多来源比较与证据判断', 'DEMO研究团队', 2026, '生成式AI信息核验与证据判断', 'PRIMARY', '小学五、六年级学生，DEMO样本84人', 'DEMO_QUASI_EXPERIMENT', 'N=84 (DEMO)', 'DEMO结果显示：多来源核验、同伴证据比较以及基于证据修订判断，有助于学生更关注AI回答的信息依据；其中“先形成个人判断，再咨询AI”的安排有助于学生识别AI建议与已有证据之间的不一致。', 'POSITIVE', '适用于能够访问多个信息来源、教师能够提供证据记录支架，并预留同伴讨论时间的小学高年级课堂。', 'DEMO研究来自单一学校且干预仅4周，不可据此推断长期迁移或普遍效果；该记录仅供平台演示。', 'MODERATE', '可将课程设计为“初步判断 → 比较AI回答 → 多来源核验 → 小组说明证据 → 修订最终判断”。评价时要求学生同时提交信息来源、关键证据和接受/修改/拒绝AI建议的理由。', 'DEMO研究资源（非真实文献）', 'DEMO p.5–12', 'DEMO来源文本：学生先形成初步判断，再通过至少两个信息来源核验AI回答，并在小组中依据证据修订结论。', '小学 五年级 生成式AI 信息核验 多来源核验 证据判断 同伴讨论 修订 AI回答 DEMO', NULL, 'REVIEWED', '2026-09-03 19:26:37', '[\"先判断后咨询AI\", \"多来源信息核验\", \"同伴证据比较\", \"基于证据修订判断\"]', '[\"提供至少两个可访问的信息来源\", \"提供“主张—来源—证据—判断”记录支架\", \"预留小组讨论和观点修订时间\"]', '{\"note\": \"Synthetic demo evidence; not for academic citation.\", \"demoOnly\": true, \"mediaType\": \"application/pdf\", \"projectId\": 1001, \"resourceId\": 2, \"originalFilename\": \"DEMO_小学AI信息核验研究.pdf\"}', 'CONFIRMED', 2, 1, '2026-09-03 19:32:00', 1001, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5006, 'University students\' use of generative AI (GAI)', NULL, NULL, 'University students\' use of generative AI (GAI)', NULL, 'undergraduate and graduate students in the United States', NULL, NULL, 'Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\nNon-native English speakers use and adopt GAI more readily than native speakers.\nCompared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\nBlack students report a more positive impact of GAI on their academic performance.\nStudents with higher conscientiousness use GAI less.\nStudents who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\nStudents with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\nStudents with higher extraversion show a stronger preference for GAI over traditional resources.\nStudents with higher intellect/imagination tend to prefer traditional resources.', NULL, NULL, 'The study is limited to one-time cross-sectional survey data.', NULL, NULL, '2026-会议-Understanding University Students’ Use of Generative AI—The Roles of Demographics and Personality Traits.pdf', NULL, 'Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.', NULL, NULL, 'DRAFT', '2026-09-08 18:55:42', '[\"探究式学习\"]', '[\"30分钟\"]', '{\"sha256\": \"d9d8f68b29f0343ab2021fc49cc9b352dabf7ed25bb47e26943a261aa5dcc65a\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1012, \"size_bytes\": 382337, \"resource_id\": 7, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"2026-会议-Understanding University Students’ Use of Generative AI—The Roles of Demographics and Personality Traits.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"2026-会议-Understanding University Students’ Use of Generative AI—The Roles of Demographics and Personality Traits.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'CONFIRMED', 13, 1, '2026-09-08 18:55:51', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5007, 'Generative AI agents', NULL, NULL, 'Generative AI agents', NULL, 'higher education students', NULL, NULL, 'Passive GenAI agents yielded comparable improvements to standalone scaffolding (data storytelling) both during and after the intervention.\nProactive GenAI agents significantly enhanced students\' VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.\nAll three interventions (data storytelling, passive GenAI, proactive GenAI) significantly improved the effectiveness and efficiency of extracting insights from VLA.\nThe proactive GenAI agent condition showed a significant improvement from the intervention phase to the post-intervention phase, unlike the other conditions.\nNo significant interaction effects were found between visualisation literacy and intervention conditions, suggesting the interventions were beneficial across literacy levels.', NULL, NULL, 'The controlled lab environment may not fully mirror the complexities of real-world educational settings where multiple visualisations are viewed simultaneously.\nThe one-hour intervention period limits the ability to assess long-term learning gains.\nThe participant pool was predominantly from North America and Europe, limiting the generalisability of the findings.\nThe study did not thoroughly investigate the specific design features of the proactive GenAI agents contributing to their effectiveness.\nThe evaluation focused on lower levels of Bloom\'s taxonomy (knowledge and comprehension) and did not assess higher-order thinking skills.', NULL, NULL, '2025-Yan-C&E-The effects of generative AI agents and scaffolding on enhancing.pdf', NULL, 'The results show that passive agents yield comparable improvements to standalone scaffolding both during and after the intervention. Notably, proactive GenAI agents significantly enhance students’ VLA comprehension compared to both passive agents and standalone scaffolding, with these benefits persisting beyond the intervention.', NULL, NULL, 'DRAFT', '2026-09-08 19:53:44', '[\"Data storytelling\", \"Passive GenAI agents (reactive support)\", \"Proactive GenAI agents (scaffolding questions and feedback)\"]', '[]', '{\"sha256\": \"fc78e9ad69c979f45396a071ea6d3e92b7d4d1efcedbc847bb3a33b754c7ae54\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1018, \"size_bytes\": 4677684, \"resource_id\": 10, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"2025-Yan-C&E-The effects of generative AI agents and scaffolding on enhancing.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"2025-Yan-C&E-The effects of generative AI agents and scaffolding on enhancing.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'CONFIRMED', 16, 1, '2026-09-08 19:54:19', NULL, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5008, 'Effects of an LLM-based Socratic Intelligent Conversational Agent (S-ICA) on students\' academic performance and reflective thinking in higher education', NULL, NULL, 'Effects of an LLM-based Socratic Intelligent Conversational Agent (S-ICA) on students\' academic performance and reflective thinking in higher education', NULL, '94 second-year undergraduates majoring in Educational Technology from a teacher training university in central China (mean age 19)', NULL, NULL, 'The S-ICA group showed marginal improvement in conceptual knowledge gains compared to the nS-ICA group (Time × Condition interaction ̂𝛽 = 0.821, 𝑝 = 0.056)\nThe S-ICA group produced significantly higher-quality experimental research proposals (Hedges’ 𝑔 = 1.69, 95% CI [0.57, 2.80]; CLES = 0.88)\nS-ICA students reported significantly higher overall reflective thinking, with particularly pronounced differences in Reflection (𝐹 = 11.438, 𝑝 = .001) and Critical Reflection (𝐹 = 13.712, 𝑝 < 0.001)\nEpistemic Network Analysis revealed that S-ICA students activated more advanced reflective pathways, showing stronger connections between Understanding–Reflection (U–R, 0.53), Reflection–Critical Reflection (R–CR, 0.43), and Understanding–Critical Reflection (U–CR, 0.32)\nNo significant difference was found in learning motivation between the groups (𝐹 = 1.749, 𝑝 = 0.190)\nInterviews indicated that S-ICA facilitated deep thinking, effective learning, questioning and reflection, knowledge acquisition, and prevention of cognitive dependence, while nS-ICA users reported superficial learning and reliance on ready-made answers', NULL, NULL, 'The sample was primarily composed of educational technology majors with uneven gender distribution, limiting generalizability to other disciplines and populations\nThe instructional tasks focused on research design activities, leaving uncertainty about effectiveness in other learning domains\nThe six-week intervention duration was relatively short, limiting the ability to examine long-term effects on reflective practices and sustained behavioral change\nThe number of group-level submissions was small (eight proposals per condition), constraining statistical power and precision of effect estimates\nEthical considerations regarding LLM-based learning processes, including data privacy, content originality, and intellectual property rights, were not comprehensively addressed', NULL, NULL, 'Investigating the effects of an LLM-based Socratic conversational agent on students’ academic performance and reflective thinking in higher education.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-08 21:18:00', '[\"Inquiry-based learning (IBL) framework with Orientation, Conceptualization, Investigation, and Discussion phases\", \"Socratic questioning integrated into LLM-based conversational agents (S-ICA) to promote reflective thinking\", \"Collaborative group work with structured worksheets and turn-taking scaffolds\", \"Scaffolded feedback through adaptive prompt engineering and dynamic dialogue adjustment\", \"Iterative revision cycles guided by AI agents for experimental research proposal development\"]', '[\"6 weeks\"]', '{\"sha256\": \"9c807925df209cb7ee6e46c149936522cbe0f3b202c8911dde7e00ac6bb2e235\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1018, \"size_bytes\": 3257049, \"resource_id\": 11, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"Investigating the effects of an LLM-based Socratic conversational agent on students’ academic performance and reflective thinking in higher education.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"Investigating the effects of an LLM-based Socratic conversational agent on students’ academic performance and reflective thinking in higher education.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'CONFIRMED', 20, 1, '2026-09-08 21:18:33', 1018, 11, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5009, 'Effects of an LLM-based Socratic conversational agent (S-ICA) on students’ academic performance and reflective thinking in higher education', NULL, NULL, 'Effects of an LLM-based Socratic conversational agent (S-ICA) on students’ academic performance and reflective thinking in higher education', NULL, 'second-year undergraduates majoring in Educational Technology', NULL, NULL, 'S-ICA (Socratic agent) produced substantially higher quality experimental research proposals than nS-ICA (non-Socratic agent), with a large effect size (Hedges’ g = 1.69) and significantly better team-level scores.\nS-ICA significantly improved self-reported reflective thinking overall, with the strongest effects in the higher-order dimensions of Reflection and Critical Reflection.\nENA showed S-ICA strengthened mid- to higher-order reflective pathways (e.g., Understanding–Reflection, Reflection–Critical Reflection, Understanding–Critical Reflection), while the control condition showed stronger connections in lower-order pathways (e.g., Habitual Action–Understanding).\nConceptual knowledge gains were substantial in both groups, but the incremental advantage of S-ICA over nS-ICA was small to moderate and at most marginally significant.\nNo statistically significant difference was found between S-ICA and nS-ICA on learning motivation.', NULL, NULL, 'Sample drawn primarily from Educational Technology undergraduates; limited generalizability to other disciplines and populations.\nTask focused on research design; it is unclear whether benefits would transfer to other learning domains.\nShort six-week intervention; long-term effects on reflective practice and sustained behavior change were not examined.\nSmall number of group-level proposals (8 per condition) reduced statistical power and precision for team-level outcomes.\nEthical issues of LLM use (privacy, originality, intellectual property) were not comprehensively addressed in the study design.', NULL, NULL, 'Investigating the effects of an LLM-based Socratic conversational agent on students’ academic performance and reflective thinking in higher education.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-08 21:22:16', '[\"Socratic questioning strategy embedded in an LLM-driven conversational agent (S-ICA)\"]', '[\"six-week intervention period\"]', '{\"sha256\": \"9c807925df209cb7ee6e46c149936522cbe0f3b202c8911dde7e00ac6bb2e235\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1019, \"size_bytes\": 3257049, \"resource_id\": 12, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"Investigating the effects of an LLM-based Socratic conversational agent on students’ academic performance and reflective thinking in higher education.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"Investigating the effects of an LLM-based Socratic conversational agent on students’ academic performance and reflective thinking in higher education.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 22, NULL, NULL, 1019, 12, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5010, '多智能体支持论证式协作知识建构', NULL, NULL, '多智能体支持论证式协作知识建构', NULL, '62名大学生（涵盖本科、硕士和博士不同学历层次，学科背景包括自然科学、人文学科、工学、社会科学）', NULL, NULL, 'ABCKC-AI支持能够显著提高个人论证水平，实验组前后测得分提升显著高于对照组\nABCKC-AI支持的小组协作文档得分显著高于对照组，整体论证质量更佳\n实验组在与论证相关的实质性互动上产出更多，包括提出更多主张、更倾向于通过逻辑推理和事实证据增强观点的说服力、更积极主动地回应他人观点；对照组在社会情感互动上更为频繁\n实验组的平均论证层级高于对照组，具体层级分布上，实验组1级结构最多（46.13%），对照组0级结构最多（48.60%），实验组在1~3级结构上的比例均高于对照组，说明实验组出现了更多相对复杂的论证结构\n实验组的知识建构深度显著高于对照组，实验组更多进入阐释和修正阶段，对照组主要停留在分享和回应观点阶段\n学习者对ABCKC-AI支持的论证式协作知识建构整体持满意态度，认同其提示能帮助专注讨论并补充解释和证据，认同其主动插入的观点能启发思路、拓展讨论方向并生成有用的总结，认同其对话支持能帮助完善观点及整合讨论内容', NULL, NULL, '样本量较小且集中于社科背景的研究生群体，可能影响结果的代表性与普适性\n实验干预时长有限，系统支持的长期影响仍有待探索\nABCKC-AI虽对低结构观点的支持有效，但对高阶论证结构（如多源证据整合、复杂观点的综合）的促进作用有限\n当前学习者—智能体的互动机制相对单一，主要局限于单向提示和对话窗口互动', NULL, NULL, '多智能体支持论证式协作知识建构：ABCKC-AI系统设计与准实验评估_欧阳璠.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-09 10:19:27', '[\"通过开放性提示进行干预，避免过度脚本化\", \"对学习者在不同维度的实时表现进行个性化评估\", \"在小组的论证水平达到一定程度后，逐渐淡化并撤出干预\", \"提供外部观点刺激，促进讨论的深度和广度\"]', '[\"70分钟\"]', '{\"sha256\": \"cb316c9ae4ed53b982ad45bb8ae0f5824317d1b3a268b3f202deb4bb68faddcb\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1011, \"size_bytes\": 2831081, \"resource_id\": 13, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"多智能体支持论证式协作知识建构：ABCKC-AI系统设计与准实验评估_欧阳璠.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"多智能体支持论证式协作知识建构：ABCKC-AI系统设计与准实验评估_欧阳璠.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 24, NULL, NULL, 1011, 13, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5011, '基于多模态大模型的协作论证支架对知识建构的影响', NULL, NULL, '基于多模态大模型的协作论证支架对知识建构的影响', NULL, '68名大学二年级学生（男生30人，女生38人）', NULL, NULL, '基于多模态大模型的协作论证支架引发了丰富的协作论证话语转移行为和高阶知识建构观点\n总结升华话语转移行为与关键观点密切相关，关键观点是促进知识建构由低阶至高阶跃迁的主导因素\n基于多模态大模型的协作论证支架有助于提升知识建构水平，尤其是在意义协商、检验修改与创新应用方面', NULL, NULL, '当前研究资源中尚未找到足够证据支持这一判断', NULL, NULL, '基于多模态大模型的协作论证支架对知识建构的影响研究_朱珂.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-09 11:38:37', '[\"多模态开放系统\", \"差异化支持策略\", \"协同共生机理\"]', '[\"5周\"]', '{\"sha256\": \"a7c36627a46b41a85dd9622e66b7ae573e169207718b765e2c44345f8b28c2c4\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1002, \"size_bytes\": 2416317, \"resource_id\": 14, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"基于多模态大模型的协作论证支架对知识建构的影响研究_朱珂.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"基于多模态大模型的协作论证支架对知识建构的影响研究_朱珂.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 25, NULL, NULL, 1002, 14, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5012, '人机协同教育场景中的智能化学习支架', NULL, NULL, '人机协同教育场景中的智能化学习支架', NULL, '学生', NULL, NULL, '本研究提出了学习支架的三种演化形态及典型特征：传统学习支架、技术支持型学习支架以及智能化学习支架\n本研究将智能化学习支架划分为动机性、概念性、策略性和元认知四种表征类型\n本研究提出了智能技术支持学习支架创变的“辅助—优化—重塑”三层次内涵\n本研究从支架表征、支架设计、支架内嵌和支架优化四方面提出智能化学习支架设计的基本原则\n本研究构建了包含“需求分析层—AI赋能层—框架设计层—学习环节层”四个层级的智能化学习支架设计流程', NULL, NULL, '本文尚未回应在具体教学智能体或其他人工智能教育产品中内嵌智能化学习支架的具体做法', NULL, NULL, '人机协同教育场景中的智能化学习支架：内涵、设计方略与发展路向_单俊豪.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-09 12:24:00', '[\"支架表征流程化、可视化\", \"支架设计个性化、定制化\", \"支架内嵌常态化、循证化\", \"支架优化证据化、智适应化\"]', '[]', '{\"sha256\": \"a57098454301c24629829459ea7cc90dff394b748b5bd6ddf3c92da7f4ca8f02\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1002, \"size_bytes\": 1346679, \"resource_id\": 15, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"人机协同教育场景中的智能化学习支架：内涵、设计方略与发展路向_单俊豪.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"人机协同教育场景中的智能化学习支架：内涵、设计方略与发展路向_单俊豪.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 26, NULL, NULL, 1002, 15, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5013, 'productive disciplinary engagement (PDE)', NULL, NULL, 'productive disciplinary engagement (PDE)', NULL, '六年级学生', NULL, NULL, 'Reflective assessment-augmented knowledge-building inquiry is effective in supporting low-achieving students\' PDE.\nThe experimental class exhibited higher cognitive, emotional and epistemic engagement compared with the comparison class.\nReflective assessment facilitated low-achieving students\' collective reflection, monitoring and regulation, as shown by their metacognitive discourse moves.\nMetacognitive processes further helped low-achieving students achieve higher levels of cognitive, emotional and epistemic engagement.', NULL, NULL, '提前了解学生状态与基础能力', NULL, '将KB融入到AI学习探究中', '2022 - Yang - Fostering low‐achieving students  productive disciplinary engagement through knowledge-building inquiry and reflective assessment.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-10 22:09:57', '[\"knowledge-building inquiry\", \"portfolio-supported reflective assessment\"]', '[\"4 months\"]', '{\"sha256\": \"9cd24710eda7a7c086ef45f0352075c02ef4ca3c3c6d0143c618f599dde13980\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1022, \"size_bytes\": 5678679, \"resource_id\": 22, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"2022 - Yang - Fostering low‐achieving students  productive disciplinary engagement through knowledge-building inquiry and reflective assessment.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"2022 - Yang - Fostering low‐achieving students  productive disciplinary engagement through knowledge-building inquiry and reflective assessment.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 39, NULL, NULL, 1022, 22, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5014, 'productive disciplinary engagement', NULL, NULL, 'productive disciplinary engagement', NULL, 'low-achieving students', NULL, NULL, 'reflective assessment-augmented knowledge-building inquiry has positive effects on low-achieving students\' PDE\nthe experimental class displayed more productive sequential transition patterns of discourse moves in cognitive engagement than the comparison class', NULL, NULL, 'The data of this study cannot be made openly available due to confidentiality agreements and ethical concerns', NULL, 'It is crucial to create a collaborative and reflective community culture to help low-achieving students gradually gain agency; it is critical to help low-achieving students develop a productive belief that idea improvement and reflection is a continuous and iterative process; the effectiveness of reflective assessment requires face-to-face knowledge-building discussion and collaborative reflection opportunities scaffolded by assessment tools and analytics that encourage low-achieving students to engage in meta-level discussion.', '2022 - Yang - Fostering low‐achieving students  productive disciplinary engagement through knowledge-building inquiry and reflective assessment.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-11 01:06:19', '[\"knowledge-building inquiry\", \"portfolio-supported reflective assessment\"]', '[\"approximately 4 months\"]', '{\"sha256\": \"9cd24710eda7a7c086ef45f0352075c02ef4ca3c3c6d0143c618f599dde13980\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1021, \"size_bytes\": 5678679, \"resource_id\": 24, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"2022 - Yang - Fostering low‐achieving students  productive disciplinary engagement through knowledge-building inquiry and reflective assessment.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"2022 - Yang - Fostering low‐achieving students  productive disciplinary engagement through knowledge-building inquiry and reflective assessment.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 44, NULL, NULL, 1021, 24, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5015, '知识建构能力', NULL, NULL, '知识建构能力', NULL, '本科学生', NULL, NULL, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', NULL, NULL, NULL, NULL, NULL, '讯飞研教智联知识库', NULL, '', NULL, NULL, 'DRAFT', '2026-09-11 11:30:09', '[\"反思性评估\", \"可视化分析工具（如KBDeX）\"]', '[]', '{\"sha256\": null, \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": null, \"project_id\": 1023, \"size_bytes\": null, \"resource_id\": null, \"source_type\": \"KNOWLEDGE_BASE\", \"source_label\": \"讯飞研教智联知识库\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": null, \"source_message_id\": null, \"verification_note\": \"知识库来源，具体文献依据待教师核查\"}', 'DRAFT', 46, NULL, NULL, 1023, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5016, '项目资料证据：2024-Reflective assessment using analytics and artifacts for scaffolding knowledge building competencies among undergraduate students.pdf', NULL, NULL, '知识建构能力', NULL, NULL, NULL, NULL, '研究指出，为了支持学生参与有效的协作探究，学生需要发展知识建构能力（KB competencies），这些能力涵盖认知-概念、元认知、社会-情感和认识论维度，且当前的额外教学支架是必要的。', NULL, NULL, NULL, NULL, '直接回答了研究中关注的“学习问题”，即学生在协作中发展核心素养面临的挑战。', '2024-Reflective assessment using analytics and artifacts for scaffolding knowledge building competencies among undergraduate students.pdf', NULL, 'Students conduct collective inquiry intentionally, taking charge in working on</u> unresolved problems. Epistemic competencies are connected to epistemic agency, a key principle of KB that involves students taking collective cognitive responsibility, identifying promising areas of inquiry, using knowledge sources constructively for evidence, engaging in problem-centered inquiry, negotiating the fit between their model with scientific model, creating and revising joint theory toward theory building, and working toward rise above to achieve parsimonious explanation and theories (Scardamalia, 2002; Yang, Feng, et al., 2023). Previous coding schemes in knowledge building have examined how students continue to pursue for deepening and sustained inquiry, and working with diverse views creating rise-above conceptualization (Chuy et al., 2011). These kinds of engagement suggest students’ different epistemic stances and goals in viewing and tackling knowledge. While both epistemic agency and collective agency are integral to the KB process, they differ in their focus. Collective agency emphasizes the social and collaborative aspects of learning, underscoring the importance of group dynamics and emotional intelligence in the learning process. In contrast, epistemic agency focuses more on the cognitive responsibilities of students in the knowledge-building process, particularly how they engage with and contribute to the collective understanding and advancement of knowledge within their learning community. \n\nTo summarize, KB competencies can be seen as the basis and underlying framework that supports productive discourse and creative knowledge work. KB competencies encompass different dimensions including the cognitive–conceptual, metacognitive, <u>socio-emotional, and epistemic knowledge–skills–dispositions for students to engage in</u> meaningful and productive discourse. These competencies are not mutually exclusive and often overlap across dimensions. We consider discourse moves as observable manifestations of KB competencies—discourse moves reflect how individuals apply their competencies in practice as they engage in specific communicative actions to contribute to collective KB efforts. While there may be connections between the two, KB competencies provide a comprehensive and integrated framework for KB, where discourse moves to offer a more specific lens for examining the communicative actions within the KB process. \n\n1 3 \n\nY. Yang et al. \n\n238 \n\nProductive discourse is an important medium for undergraduates to develop these KB competencies. Competencies and discourse moves are reciprocally related as competencies <u>make it possible for students to engage in productive discourse moves, and engagement in multiple rich discourse moves support further development of competencies. Research</u> on discourse, a key research theme in CSCL and the education community, has examined how productive learning can be developed through productive discourse with the affordances of technologies (Chen et al., 2015; Zhang et al., 2020). Nevertheless, numerous students, including those enrolled in undergraduate programs, encounter challenges when it comes to effectively engaging in productive discourse for developing KB competencies. Therefore, additional scaffoldings and tools are needed to help them engage in productive discourse and develop KB competencies regarding the four dimensions described above. \n\n### **Reflective assessment** \n\nReflective assessment is a scaffolding strategy in which the learners assume responsibility for reflecting on and regulating their inquiries and learning against precise evidence/ criteria of their inquiries and learning, and figure out methods to regulate their inquiries and learning for continuous advancement (Yang et al., 2016, 2020a). Within reflective assessment, metacognitive processes such as planning, monitoring, reflection, and regulation propel learners to manifest their metacognitive acumen and proficiencies. This, in turn, guides their endeavors in maintaining the momentum of their inquiries and learning. Active engagement with these metacognitive processes stands as a pivotal factor in fostering meaningful discourse within computer-supported collaborative inquiries (Borge et al., 2018; De Backer et al., 2021; Yang, 2019; Yang et al., 2016, 2020a). In the KB community model, reflection assumes a collaborative nature, permitting learners to scaffold each other’s enhancement of metacognitive awareness and skills through emulation. Importantly, not every learner needs to have high-level metacognitive awareness and skills to participate actively. \n\nPrevious research on portfolios-supported reflective assessment in KB classrooms has demonstrated that such reflective assessment can effectively help learners improve domain understanding and KB discourse (Chan & van Aalst, 2018; Lee et al., 2006; van Aalst & Chan, 2007) and metadiscourse (Lei & Chan, 2018). Nonetheless, we posit that reflective assessment shares epistemological similarities with other domain-specific inquiries, as it is a problem-solving process informed by exact data and evidence of the inquiry process and outcomes.', '该证据揭示了研究关注的核心学习问题：在协作学习环境中，学生如何通过特定技能和支架来有效参与并深化集体知识。', NULL, 'DRAFT', '2026-09-11 11:30:09', NULL, NULL, '{\"fileId\": 25, \"chunkId\": \"e39ecaf542f8aa0eeafc70c890df8e9fc12d1b600b101e17317514ab6eb4e076\", \"filename\": \"2024-Reflective assessment using analytics and artifacts for scaffolding knowledge building competencies among undergraduate students.pdf\", \"projectId\": 1023, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.016129032258064516, \"sourceMessageId\": 151}', 'DRAFT', 46, NULL, NULL, 1023, 25, 'e39ecaf542f8aa0eeafc70c890df8e9fc12d1b600b101e17317514ab6eb4e076', 0.016129, 151);
INSERT INTO `evidence_card` VALUES (5017, '项目资料证据：2024-Reflective assessment using analytics and artifacts for scaffolding knowledge building competencies among undergraduate students.pdf', NULL, NULL, '知识建构能力', NULL, NULL, NULL, NULL, '研究结果表明，通过使用KBDeX可视化工具，学生能够识别探究中的问题、反思讨论质量，并通过元话语规划未来的探究方向，从而提高概念、认识论和元认知能力。', NULL, NULL, NULL, NULL, '反映了研究关注的“教学问题”，即如何利用教学支架促进学生的深度学习和知识共建。', '2024-Reflective assessment using analytics and artifacts for scaffolding knowledge building competencies among undergraduate students.pdf', NULL, '**Fig. 9** A concept map of one group’s analysis of KBDeX idea network \n\nthe importance of synthesizing the community’s ideas and identifying new problems for ongoing discussion. This process was considered essential for developing theories and deepening inquiry, and reflected students’ KB competencies in the conceptual, epistemic, and metacognitive dimensions. \n\nWith the help of the group-level KBDeX diagram, the undergraduates identified the following issues: “Our discussion on collaboration seemingly lacks innovative ideas” and “We have not inquired about theories on group dynamics...” Based on their task analysis, the undergraduates reflected on the quality of and gaps in their inquiry threads, and identified further inquiry directions with the help of a community-level KBDeX diagram, as indicated by the following statement: “We can deepen our further inquiry through discussion of theories on maintaining team dynamics… team performance…” They then generated an action plan to regulate their theory building and inquiry. The undergraduates contributed metadiscourse in which they synthesized the group’s past and present inquiries, tracked problems, and identified promising directions to progressively building theories with KBDeX idea diagrams. \n\nThis process indicated students’ demonstration of metacognitive competencies. By reflecting on the quality of their discussions and planning for future inquiry, the students demonstrated their ability to regulate their learning process and engage in metadiscourse, tracking the progress of their collective ideas and charting new directions for knowledge advancement. This process also reflected their epistemic competencies, showcasing their ability to engage in deeper inquiry and theory building. Their plan to discuss theories on maintaining team dynamics and assessing team performance indicated a productive approach to KB and problem solving. Additionally, this process demonstrated conceptual competencies, where students sought to understand various aspects of collaboration (e.g., the nature and significance of collaboration and \n\n1 3 \n\nY. Yang et al. \n\n262 \n\nfactors influencing group productivity) and identified gaps in their discussions, such as the lack of innovative ideas or inquiries into group dynamics. lective assessment using KBDeX visualizations \n\n<u>Overall, these results suggested that reflective assessment using KBDeX visualizations and accompanying prompts facilitated the undergraduates to deepen their understanding of collaboration (conceptual competency), engage more meaningfully in knowledge creation (epistemic competency), and effectively plan and regulate their future inquiries (metacognitive competency).</u> \n\n## **Discussion and conclusions** \n\n### **Characterization and demonstration of undergraduates’ KB competencies** \n\nHelping undergraduates develop 21st-century competencies is widely advocated (NRC, 2012; Hilton & Pellegrino, 2012; OECD, 2023) to equip them to face the complex and rapidly changing world. Investigation of competencies is aligned with learning sciences and CSCL as designing deep learning is essential for developing 21st-century competence, and the application of competencies, in turn, supports the process of deep learning for knowledge transfer (NRC, 2012; Hilton & Pellegrino, 2012). While there are many lists of 21st-century competencies (Voogt & Roblin, 2012), few specific references have been made to developing KB competencies that refer to knowledge, skills, and dispositions needed for students to generate and advance knowledge and engage in creative knowledge work. KB competencies is an important theme in CSCL and learning-sciences research. The KB research community has made major research progress. Still, a synthesis of KB competence as a framework for what we hope students to develop and how to scaffold and assess such competencies has not been systematically developed and examined (see review, Chen & Hong, 2016). \n\nWith the major recognition in developing core competencies in the education arena (Chalkiadaki, 2018; Gonzalez-Salamanca et al., 2020; NRC, 2012), major challenges exist regarding how to measure and nurture these competencies (Voogt & Rublin, 2012). The CSCL environments supporting students’ collaborative discourse not only nurture students’ core competencies; students can also demonstrate their competencies in different dimensions as they engage in collaborative inquiry. This study has systematically linked key competencies with discourse moves for evidence and outcomes. When students reflect, monitor, and regulate their discourse, they are deploying and developing metacognitive competence. When they encourage peers to participate and persevere when facing challenges, they demonstrate social-emotional competence. Additionally, a sustained pursuit of inquiry to deepen and rise above reflects students’ epistemic commitments. Competencies could be challenging to measure, but discourse moves can provide pointers as manifestations of these developing competencies.', '该证据补充了研究对教学干预手段的关注，说明研究重点在于如何通过技术增强的反思性评估解决学生的协作探究不足问题。', NULL, 'DRAFT', '2026-09-11 11:30:09', NULL, NULL, '{\"fileId\": 25, \"chunkId\": \"5e7b2006c87cd9085717afda4cd765bf74797dc61288d540c76fbdf516b74ca1\", \"filename\": \"2024-Reflective assessment using analytics and artifacts for scaffolding knowledge building competencies among undergraduate students.pdf\", \"projectId\": 1023, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015873015873015872, \"sourceMessageId\": 151}', 'DRAFT', 46, NULL, NULL, 1023, 25, '5e7b2006c87cd9085717afda4cd765bf74797dc61288d540c76fbdf516b74ca1', 0.015873, 151);
INSERT INTO `evidence_card` VALUES (5018, '知识建构能力', NULL, NULL, '知识建构能力', NULL, '本科学生', NULL, NULL, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', NULL, NULL, NULL, NULL, NULL, '讯飞研教智联知识库', NULL, '', NULL, NULL, 'DRAFT', '2026-09-11 11:38:21', '[\"反思性评估\", \"可视化分析工具（如KBDeX）\"]', '[\"计算机支持的协作探究（CSCL）环境和专门的知识建构平台\"]', '{\"sha256\": null, \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": null, \"project_id\": 1023, \"size_bytes\": null, \"resource_id\": null, \"source_type\": \"KNOWLEDGE_BASE\", \"source_label\": \"讯飞研教智联知识库\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": null, \"source_message_id\": null, \"verification_note\": \"知识库来源，具体文献依据待教师核查\"}', 'DRAFT', 47, NULL, NULL, 1023, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5019, '知识建构能力', NULL, NULL, '知识建构能力', NULL, '本科学生', NULL, NULL, '反思性评估结合KBDeX可视化有助于增强学生协作探究中的概念理解与元认知调节。', NULL, NULL, '该研究基于本科生样本，对当前小学四年级情境仅可作为设计参考（如协作讨论的思路），但不能视为小学生直接适用的证据。四年级学生的认知与元认知能力与本科生差异显著，不能直接照搬。', NULL, NULL, '讯飞研教智联知识库', NULL, '', NULL, NULL, 'DRAFT', '2026-09-11 12:00:44', '[\"反思性评估\", \"可视化分析工具（如KBDeX）\"]', '[\"计算机支持的协作探究（CSCL）环境和专门的知识建构平台\"]', '{\"sha256\": null, \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": null, \"project_id\": 1023, \"size_bytes\": null, \"resource_id\": null, \"source_type\": \"KNOWLEDGE_BASE\", \"source_label\": \"讯飞研教智联知识库\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": null, \"source_message_id\": null, \"verification_note\": \"知识库来源，具体文献依据待教师核查\"}', 'CONFIRMED', 48, 3, '2026-09-11 12:00:55', 1023, NULL, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5020, 'how GenAI tools influence students’ engagement and motivation towards reflective writing, as well as the depth and quality of the writing itself', NULL, NULL, 'how GenAI tools influence students’ engagement and motivation towards reflective writing, as well as the depth and quality of the writing itself', NULL, 'five secondary school students from an English-medium local secondary school in Hong Kong, aged between 14 and 17, who participated in a three-week summer internship programme related to GenAI in education', NULL, NULL, 'GenAI tools, such as ChatGPT and Bing, have emerged as innovative supports for enhancing students’ reflective capabilities.\nThese tools can stimulate critical thinking, creativity, and problem-solving skills in educational contexts.\nCognitive or metacognitive prompts while journaling led to improved learning outcomes.\nWriting alone may not yield significant learning benefits unless coupled with metacognitive prompts that encourage students to reflect on their knowledge and learning processes.\nResearch on GenAI’s impact on students’ writing remains limited because the tool has been released relatively recently to the wider public.', NULL, NULL, 'Without teacher guidance and proper training, the integration of GenAI in reflective writing may deter rather than promote higher order thinking.\nEffective reflection often requires a higher level of metacognitive knowledge that many secondary students may not fully develop.\nStudents may experience AI guilt due to concerns about authenticity, perceived laziness, and over-reliance on AI.\nEducators need to help students strike a balance between using AI as a writing support and engaging in authentic, independent reflection.\nEducators should create assignments or prompts that encourage deeper reflection beyond surface-level improvements.\nEducators must emphasise that reflective writing should remain a deeply personal process.\nRubrics should be adjusted to reward depth, originality, and personal insight in reflective writing.', NULL, NULL, '1-s2.0-S0360131525001678-main.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-12 16:59:24', '[]', '[\"three-week\"]', '{\"sha256\": \"1671bbfde02299d25f037693a3ec89cc68d72366591a83110bb478ff299faa77\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1027, \"size_bytes\": 662510, \"resource_id\": 32, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"1-s2.0-S0360131525001678-main.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"1-s2.0-S0360131525001678-main.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 59, NULL, NULL, 1027, 32, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5021, '项目资料证据：1-s2.0-S0360131525001678-main.pdf', NULL, NULL, 'how GenAI tools influence students’ engagement and motivation towards reflective writing, as well as the depth and quality of the writing itself', NULL, NULL, NULL, NULL, '该段落说明研究关注点是中学生在反思写作中与生成式AI的互动过程及其反思深度与质量，并提到反思写作对认知发展的要求以及在中学阶段促进反思能力与生成式AI素养的重要性。', NULL, NULL, NULL, NULL, '直接说明研究关注学生在反思写作和AI辅助情境中的发展，涉及反思能力及相关认知与AI素养的发展空间。', '1-s2.0-S0360131525001678-main.pdf', NULL, 'These tools can offer support in idea generation, grammar correction, and even full-text generation, potentially easing the burden of reflective tasks. However, the use of GenAI in academic writing, particularly in reflective practices, raises important questions about its impact on student learning, motivation, and the authenticity of the reflective process. \n\nAt the secondary school level, reflective writing is particularly challenging due to two reasons. First, teachers tend to focus on content coverage and passive learning (Denton, 2011), depriving students of the opportunities to reflect. Second, reflective writing requires complex reasoning, which is usually developed in late adolescence and adulthood (King & Kitchener, 2004). AI poses similar challenges to secondary school students. AI mastery is developmental, meaning advanced concepts and skills are often too difficult for junior secondary school students (Ng et al., 2024). Lee et al.’s (2021, pp. 191–197) study found that GenAI activities are in general cognitively demanding for middle secondary school students. Nevertheless, it is important to promote reflective writing and GenAI competencies in secondary schools to lay the foundation for more advanced learning at the postsecondary level. In view of these, the current study focused on secondary school students’ use of GenAI in reflective writing. \n\nThis study sought to answer the question: “How does GenAI support or hinder the development of deeper reflection in secondary school students’ reflective writing?” by exploring the ways in which secondary school students used and interacted with GenAI tools during a reflective writing task following a three-week internship programme. It looked at both the process of how students engaged with AI as well as the outcomes in terms of the depth and quality of their reflection. By investigating these processes during the task, focusing on students’ rationales and decisions to use or not to use GenAI, this paper looks at the implications of AI-assisted reflection on student learning. The findings will be particularly relevant in light of existing literature on the challenges that students face in reflective practices, as well as the increasing integration of GenAI into education. \n\n### **2. Literature review** \n\nIn their systematic literature review on the challenges of reflection in education, Chan and Lee (2021) propose a framework outlining student-learning, teacher-pedagogical, institutional, and sociocultural factors that can impede efforts to promote student reflection. Central to this framework is the student-learning level, which describes the challenges that students face in developing their capacity for meaningful reflection. Focused on the reflective practice of individual students, this study explored their perceptions and experiences of AI-assisted reflective writing at the student-learning level. In this section, common challenges students face in reflective writing and the impact of GenAI on reflective writing will be discussed. \n\n### _2.1. Challenges for student engagement in reflective writing_ \n\n### _2.1.1. Cognitive demands and processes_ \n\nAs mentioned, engaging in reflection requires complex cognitive processes that may be time-consuming and cognitively demanding. Studies have shown that time is a critical factor influencing student motivation and engagement in reflective activities (Ahmed, 2020; Fakazli and Gonen, 2017¨ ; Mahlanze & Sibiya, 2017; O’Connell & Dyment, 2011), where the need for substantial time commitment often leads to students’ perceptions that reflective tasks are burdensome, resulting in reduced engagement levels and potentially shallow reflections (Jindal-Snape & Holmes, 2009; Power, 2012). As Chan and Lee (2021) stress in their reflection literacy framework, time constraint, lack of motivation, as well as challenges in comprehending the significance and purpose of reflection are barriers to student engagement with reflection tasks. \n\nThis is further compounded by the cognitive demands of reflection. Students may struggle to elaborate their responses, especially if they are accustomed to providing brief answers (Ahmed, 2020). Students may also prioritise quantity over quality in their writing (McGarr & Moody, 2010), particularly when looking to satisfy formal assessment requirements and when their reflections will be graded.', '研究明确聚焦于中学生的反思写作能力、批判性思维和问题解决等能力的发展，并强调在中学阶段为后续学习奠定反思与AI素养基础。', NULL, 'DRAFT', '2026-09-12 17:01:02', NULL, NULL, '{\"fileId\": 32, \"chunkId\": \"8483032509704a31319e0ea100d7a752fe671c4a56b1d2d3dc6252357ae36632\", \"filename\": \"1-s2.0-S0360131525001678-main.pdf\", \"projectId\": 1027, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015384615384615384, \"sourceMessageId\": 184}', 'DRAFT', 59, NULL, NULL, 1027, 32, '8483032509704a31319e0ea100d7a752fe671c4a56b1d2d3dc6252357ae36632', 0.0153846, 184);
INSERT INTO `evidence_card` VALUES (5022, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '该文献明确了研究被试为缺乏教学设计经验与课堂实战经验的职前教师，并阐述了其核心干预在于通过KB、GenAI和ASRA的整合，开展基于设计思维的教学设计，以促进学生的迭代反思与深度参与。', NULL, NULL, NULL, NULL, '直接回答了研究关注的对象（职前教师）和核心教学问题（如何利用智能技术与协作培养教学设计思维）。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, 'The participants were between 20 and 22 years old and had completed foundational coursework in pedagogy and subject content but had limited prior experience with instructional design and no formal classroom teaching experience. Importantly, none of the participants had prior experience with human–AI co-design for instructional design purposes, although they were familiar with common digital tools for learning. The study was situated in a 17-week compulsory course that incorporated both face-to-face sessions and online collaborative inquiry activities. Rather than focusing on the general aims of the course, the present study used this course as an authentic context to implement and examine a design-oriented learning environment that integrated KB, GenAI and ASRA. Compared with previous iterations of the course, the instructional design in this study was substantially enhanced by the systematic integration of GenAI and KBDeX-supported reflective assessment, allowing PSTs to engage more deeply in iterative instructional design and reflection. Students worked in self-selected groups of five (22 groups in total) and were encouraged to engage in cross-group idea sharing through the KB platform. To mitigate potential grade-related bias associated with conducting research in a required course, we adopted the following measures: (1) participation in the study was voluntary and had no impact on course grades; (2) alternative learning activities were made available for students who chose not to participate, ensuring that no academic disadvantage resulted from non-participation; (3) all data used for research purposes were anonymized and analyzed only after course grading was completed. Prior to data collection, all participants signed informed consent forms and were explicitly informed of their right to withdraw from the study at any time without penalty. Ethical approval for the study was obtained from the university’s institutional review board, and all procedures complied with relevant ethical guidelines for educational research. The course was taught by an experienced instructor with nearly ten years of experience designing and facilitating KB collaborative inquiry supported courses and implementing ASRA in teacher education contexts. This instructional expertise ensured the enactment of KB principles and reflective assessment practices, providing a stable pedagogical foundation for examining how GenAI and ASRA jointly supported PSTs’ DT. \n\n## _3.2 KB Design-oriented Collaborative Inquiry Design Augmented by GenAI and ASRA_ \n\nGuided by the four theoretically grounded principles—epistemic agency, collective responsibility for idea improvement, human–AI co-agency and co-design, and embedded and transformative assessment—and informed by the conceptual design framework (Figure 4), we developed an integrated pedagogical design that coordinated KB inquiry, GenAI-supported codesign, and ASRA. To maintain conceptual continuity and avoid introducing new terminology late in the manuscript, we adopt the term GenAI-Reflective Knowledge Building Co-Design (GenAI-RKBCoD) from this section onward as a concise working label for the integrated design rather than a separate theoretical model.The model comprises a set of principle-based activities designed to foster PSTs’ DT through instructional design, with lesson plans treated as \n\n14 \n\nevolving design artifacts rather than final products (see details in Table 1). Table 1 summarizes each activity, its instructional purpose, and the intended DT dimensions. \n\nGrounded in our previous KB design that incorporates ASRA, the present design extends this work by integrating GenAI as a cognitive and design partner within KB inquiry (Authors, 2024a, 2024b). As illustrate in Figure 5, integrated design (hereafter referred to as GenAIRKBCoD for brevity) comprises three interrelated perspectives: (1) a design-oriented collaborative inquiry cycle structured around the DDIPT model (Discover–Define–Ideate– Prototype–Test); (2) GenAI-supported co-design to expand, critique, and refine instructional ideas; and (3) ASRA, including KBDeX-based discourse visualizations and metacognitive scaffolds to guide monitoring and regulation. Throughout the manuscript, this label functions only as shorthand for the coordinated pedagogical approach already introduced, rather than as a newly proposed framework. This study treated the design as a theory-informed intervention whose effectiveness was empirically examined through our research questions and analyses. Importantly, the three “components” shown in Figure 5 do not represent discrete instructional stages. Instead, they reflect overlapping and sustained strands of pedagogical support that were intentionally interwoven across the semester. For example, the overlap between Component 1 (Weeks 1–5) and Component 2 (Weeks 3–10) reflects the continued cultivation of collaborative norms and reflective routines while PSTs entered more intensive instructional design work. **Component 1 (Weeks 1-5): Developing a collaborative and design culture for DT.** The course began by creating a supportive learning environment to foster collaborative norms, inquiry dispositions, and design-oriented reflection on instructional design.', '研究聚焦于职前教师群体，探讨了如何利用生成式AI与知识建构等技术支持，来解决职前教师在教学设计实践中经验不足、缺乏迭代反思机制的教学与学习问题。', NULL, 'DRAFT', '2026-09-12 17:32:28', NULL, NULL, '{\"fileId\": 33, \"chunkId\": \"5e6d432a390dab25ec6c1b02d98512c4fc62449598857c43482d02568dde4215\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1028, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.01639344262295082, \"sourceMessageId\": 186}', 'DRAFT', 61, NULL, NULL, 1028, 33, '5e6d432a390dab25ec6c1b02d98512c4fc62449598857c43482d02568dde4215', 0.0163934, 186);
INSERT INTO `evidence_card` VALUES (5023, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '该部分提供了用于评估职前教师在教学设计中设计思维的评价量规，具体涵盖了发现（Discover，如分析知识点、学习者特征）、定义（Define，如设定教学目标）和构思（Ideate，如探索多样教学方法）等维度的操作性描述。', NULL, NULL, NULL, NULL, '直接揭示了教学实践中重点关注的学习与教学能力维度，回答了“关注哪些教学问题”这一问题。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '41 \n\nAppendix C. The assessment rubric for grading PSTs’ DT in instructional design of lesson plans. \n\n|**Dimension**<br>**s**|**Operational**<br>**Description**|**Not Met**|**Needs**<br>**Improvement**|**Partially**<br>**Met**|**Satisfactory**|**Excellent**|\n|---|---|---|---|---|---|---|\n|**Discover**|Accurate<br>description of<br>the<br>relationships,<br>status and<br>roles of<br>knowledge<br>points in<br>teaching<br>content, with<br>clear analysis<br>of key and<br>difficult<br>points.|• Topic positioning is unclear or<br>inaccurate; no curriculum-theme<br>alignment.<br>• No meaningful account of<br>inter-unit relations or the unit’s<br>instructional role.<br>|<br>• Partially aligns the<br>unit within the<br>curriculum sequence,<br>but the rationale is<br>fragmented or<br>generic.<br>• Mentions adjacent<br>units with unclear<br>skill/knowledge<br>carryover.<br>al P|<br>• Describes the topic<br>only; provides weak or<br>fragmented<br>justification of<br>status/function.<br>• Connections to<br>adjacent units are<br>vague, partial, or<br>partially misaligned.<br>• Lists information<br>without a coherent<br>explanatory chain.<br>re-proof|<br>• States the topic and<br>practical value; overall<br>sequencing is largely<br>accurate.<br>• Mentions links to adjacent<br>units but with limited<br>specificity (e.g., lacks<br>explicit language/skill<br>carryover).<br>• Mostly accurate but<br>somewhat verbose or<br>unfocused.|• Aligns the unit topic with the<br>curriculum theme cluster and<br>articulates authentic<br>communicative value.<br>• Explicitly maps prerequisite<br>and subsequent units (e.g., Unit<br>7/Unit 9) to show progression<br>of language knowledge and<br>skills, and justifies this unit’s<br>role in the scope-and-sequence.<br>• Concise yet complete<br>rationale (“what/why/how<br>used”), avoiding generic<br>claims.|\n||Learner<br>analysis (e.g.,<br>interests,<br>needs, group<br>characteristics<br>) can be<br>conducted via<br>technical<br>means.|• No learner analysis or<br>evidence; purely anecdotal<br>assumptions.<br>|• Uses a tool but<br>evidence is<br>incomplete (e.g., no<br>raw outputs);<br>findings remain<br>surface-level.<br>• Limited linkage<br>from learner analysis<br>to design decisions.<br>Journ|• Claims tool use but<br>provides no<br>interpretable results;<br>relies mainly on<br>impressions.<br>• Weak linkage from<br>analysis to goals, tasks,<br>or resources.<br>|<br>• Uses one tool (e.g., survey<br>or quiz) with basic evidence<br>recorded.<br>• Produces 1–2 plausible<br>findings and makes some<br>adjustments; limited depth<br>(e.g., no variability<br>analysis).|<br> <br>• Collects evidence with ≥2<br>tools (e.g., online<br>quiz/survey/LMS analytics)<br>and archives raw outputs<br>(screenshots/tables).<br>• Derives a data-based learner<br>profile (≥3 actionable findings:<br>interests, misconceptions,<br>variability) and links each to<br>design decisions (scaffolds,<br>differentiation, pacing).|\n|**Define**|Clear, specific<br>teaching<br>objectives that<br>are easy to|• Objectives are absent or<br>seriously non-standard; cannot<br>guide instruction or assessment.|• Objectives are<br>stated but only partly<br>measurable;|• Vague verbs (e.g.,<br>understand/know)<br>dominate; objectives<br>are hard to assess.|• Objectives are generally<br>clear and observable; some<br>are broad or missing success<br>criteria.|42<br> <br>•Objectives are measurable and<br>performance-based (action verb +<br>condition + product), e.g., role-play|', '已有研究关注的核心教学问题集中在职前教师是否具备规范的教学设计能力，具体表现为是否能准确分析教学内容与学习者特征，以及是否能科学设定目标与选择多样化的教学方法。', NULL, 'DRAFT', '2026-09-12 17:32:28', NULL, NULL, '{\"fileId\": 33, \"chunkId\": \"0a37ea887cea479f038339c16d999c03a90cc239584219045a9ac40f20245e40\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1028, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015873015873015872, \"sourceMessageId\": 186}', 'DRAFT', 61, NULL, NULL, 1028, 33, '0a37ea887cea479f038339c16d999c03a90cc239584219045a9ac40f20245e40', 0.015873, 186);
INSERT INTO `evidence_card` VALUES (5024, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '该部分详细解释了在教学设计中关于“构思”维度的要求，包括设计和整合多样化的教学资源（如任务单、教育游戏）以增强学习体验，并提供了从基础到优秀的具体评价标准。', NULL, NULL, NULL, NULL, '进一步细化了研究中所关注的“教学资源开发与整合”这一具体教学问题。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '43 \n\n|**Dimension**<br>**s**|**Operational**<br>**Description**||**Not Met**|**Needs**<br>**Improvement**|**Partially**<br>**Met**|**Satisfactory**|**Excellent**|\n|---|---|---|---|---|---|---|---|\n||grasped<br>difficulties;<br>properly<br>handled to<br>make hard<br>points easy.||||||feedback) tied to diagnosed<br>problems.<br>• Key/difficult points are<br>visibly embedded across<br>activities with clear expected<br>products.|\n||Explore<br>diverse<br>teaching<br>methods,<br>integrating<br>case teaching,<br>inquiry-based<br>learning,<br>flipped<br>classroom and<br>other<br>innovative<br>models.|• No meani<br>or clear mi<br>approach a|ngful diversification<br>smatch between<br>nd content.<br>|• Attempts to use<br>diversified<br>approaches, but<br>mainly lists labels<br>without clear<br>operational steps.<br>•<br>Integration/transition<br>is weak; participation<br>structures are limited.<br>urnal P|<br> <br>• Lists approach labels<br>without operational<br>steps.<br>• Participation<br>structures are<br>superficial; learning<br>experience remains<br>monotonous.<br>re-proof|• Implements 1–2<br>approaches (e.g., group<br>work + task-based activity)<br>with basic feasibility.<br>• Student participation is<br>present but<br>integration/transition is<br>moderate; lecture segments<br>remain dominant in places.|•Selects an approach suitable to<br>content and learners (e.g., task-<br>based/PWP), with explicit phase-<br>by-phase enactment.<br>• Integrates ≥2 approaches<br>purposefully (activation →<br>inquiry/task → transfer output)<br>without method stacking.<br>• Ensures student agency via<br>concrete mechanisms (roles,<br>collaboration protocol, peer<br>feedback).|\n|**Ideate**|Able to design<br>or integrate<br>various<br>teaching<br>resources<br>(e.g., task<br>sheets,<br>educational<br>games) to<br>enhance<br>learning<br>experience.|• Essential<br>or clearly<br>objectives.|resources are missing<br>misaligned with<br> <br>|<br>• Provides basic<br>resources but with<br>limited variety or<br>alignment to<br>tasks/objectives.<br>•<br>Instructions/example<br>s are incomplete;<br>differentiation is<br>minimal.<br>Jo|• Resources are<br>fragmented or weakly<br>connected to tasks;<br>usability is mediocre.<br>• Instructions/examples<br>are insufficient,<br>hindering independent<br>work.<br>|<br>• Provides at least one key<br>resource (e.g., task sheet)<br>that supports core activity<br>completion.<br>• Usability is acceptable;<br>limited differentiation or<br>exemplars.|• Provides ≥2 resource types<br>aligned to objectives (task<br>sheet, map pack, language<br>frames, game/interactive tool)<br>with stated timing and purpose.<br>• Supports differentiation<br>(tiered tasks/optional<br>challenges).<br>• Resources are classroom-<br>ready: clear layout,<br>instructions, examples, and<br>criteria.|', '研究不仅关注宏观的教学设计流程，也深入探讨了如何提升职前教师针对具体教学活动开发与整合丰富教学资源的能力。', NULL, 'DRAFT', '2026-09-12 17:32:28', NULL, NULL, '{\"fileId\": 33, \"chunkId\": \"9f5a955430ad8664edf444d04b3887053f0b9cc915be5ee7cdda761137e84bfb\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1028, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.016129032258064516, \"sourceMessageId\": 186}', 'DRAFT', 61, NULL, NULL, 1028, 33, '9f5a955430ad8664edf444d04b3887053f0b9cc915be5ee7cdda761137e84bfb', 0.016129, 186);
INSERT INTO `evidence_card` VALUES (5025, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '研究聚焦于将GenAI作为认知和设计伙伴整合到KB探究中，以培养职前教师（PSTs）的DT，强调通过DDIPT模型（发现、定义、构思、原型、测试）和评估支持迭代设计。', NULL, NULL, NULL, NULL, '直接揭示了该研究关注的核心问题，即如何通过技术整合与设计环境促进职前教师的教学设计思维发展。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, 'The participants were between 20 and 22 years old and had completed foundational coursework in pedagogy and subject content but had limited prior experience with instructional design and no formal classroom teaching experience. Importantly, none of the participants had prior experience with human–AI co-design for instructional design purposes, although they were familiar with common digital tools for learning. The study was situated in a 17-week compulsory course that incorporated both face-to-face sessions and online collaborative inquiry activities. Rather than focusing on the general aims of the course, the present study used this course as an authentic context to implement and examine a design-oriented learning environment that integrated KB, GenAI and ASRA. Compared with previous iterations of the course, the instructional design in this study was substantially enhanced by the systematic integration of GenAI and KBDeX-supported reflective assessment, allowing PSTs to engage more deeply in iterative instructional design and reflection. Students worked in self-selected groups of five (22 groups in total) and were encouraged to engage in cross-group idea sharing through the KB platform. To mitigate potential grade-related bias associated with conducting research in a required course, we adopted the following measures: (1) participation in the study was voluntary and had no impact on course grades; (2) alternative learning activities were made available for students who chose not to participate, ensuring that no academic disadvantage resulted from non-participation; (3) all data used for research purposes were anonymized and analyzed only after course grading was completed. Prior to data collection, all participants signed informed consent forms and were explicitly informed of their right to withdraw from the study at any time without penalty. Ethical approval for the study was obtained from the university’s institutional review board, and all procedures complied with relevant ethical guidelines for educational research. The course was taught by an experienced instructor with nearly ten years of experience designing and facilitating KB collaborative inquiry supported courses and implementing ASRA in teacher education contexts. This instructional expertise ensured the enactment of KB principles and reflective assessment practices, providing a stable pedagogical foundation for examining how GenAI and ASRA jointly supported PSTs’ DT. \n\n## _3.2 KB Design-oriented Collaborative Inquiry Design Augmented by GenAI and ASRA_ \n\nGuided by the four theoretically grounded principles—epistemic agency, collective responsibility for idea improvement, human–AI co-agency and co-design, and embedded and transformative assessment—and informed by the conceptual design framework (Figure 4), we developed an integrated pedagogical design that coordinated KB inquiry, GenAI-supported codesign, and ASRA. To maintain conceptual continuity and avoid introducing new terminology late in the manuscript, we adopt the term GenAI-Reflective Knowledge Building Co-Design (GenAI-RKBCoD) from this section onward as a concise working label for the integrated design rather than a separate theoretical model.The model comprises a set of principle-based activities designed to foster PSTs’ DT through instructional design, with lesson plans treated as \n\n14 \n\nevolving design artifacts rather than final products (see details in Table 1). Table 1 summarizes each activity, its instructional purpose, and the intended DT dimensions. \n\nGrounded in our previous KB design that incorporates ASRA, the present design extends this work by integrating GenAI as a cognitive and design partner within KB inquiry (Authors, 2024a, 2024b). As illustrate in Figure 5, integrated design (hereafter referred to as GenAIRKBCoD for brevity) comprises three interrelated perspectives: (1) a design-oriented collaborative inquiry cycle structured around the DDIPT model (Discover–Define–Ideate– Prototype–Test); (2) GenAI-supported co-design to expand, critique, and refine instructional ideas; and (3) ASRA, including KBDeX-based discourse visualizations and metacognitive scaffolds to guide monitoring and regulation. Throughout the manuscript, this label functions only as shorthand for the coordinated pedagogical approach already introduced, rather than as a newly proposed framework. This study treated the design as a theory-informed intervention whose effectiveness was empirically examined through our research questions and analyses. Importantly, the three “components” shown in Figure 5 do not represent discrete instructional stages. Instead, they reflect overlapping and sustained strands of pedagogical support that were intentionally interwoven across the semester. For example, the overlap between Component 1 (Weeks 1–5) and Component 2 (Weeks 3–10) reflects the continued cultivation of collaborative norms and reflective routines while PSTs entered more intensive instructional design work. **Component 1 (Weeks 1-5): Developing a collaborative and design culture for DT.** The course began by creating a supportive learning environment to foster collaborative norms, inquiry dispositions, and design-oriented reflection on instructional design.', '研究针对职前教师缺乏教学设计与协作经验的问题，提出利用GenAI和知识建构平台支持其教学设计的迭代过程。', NULL, 'DRAFT', '2026-09-12 19:56:24', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"e57c780ca2cda372f389e7099469d9e1a39bbd3162be1cb08b935b240e6cdc81\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.01639344262295082, \"sourceMessageId\": 190}', 'DRAFT', 65, NULL, NULL, 1029, 34, 'e57c780ca2cda372f389e7099469d9e1a39bbd3162be1cb08b935b240e6cdc81', 0.0163934, 190);
INSERT INTO `evidence_card` VALUES (5026, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '提供了针对教学设计中探索多样化教学方法、整合教学内容及构思教学资源的维度描述，指出了教学设计中的操作化标准。', NULL, NULL, NULL, NULL, '展示了该研究如何将教学设计问题具体化为可评估的维度，如方法整合、资源设计等。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '43 \n\n|**Dimension**<br>**s**|**Operational**<br>**Description**||**Not Met**|**Needs**<br>**Improvement**|**Partially**<br>**Met**|**Satisfactory**|**Excellent**|\n|---|---|---|---|---|---|---|---|\n||grasped<br>difficulties;<br>properly<br>handled to<br>make hard<br>points easy.||||||feedback) tied to diagnosed<br>problems.<br>• Key/difficult points are<br>visibly embedded across<br>activities with clear expected<br>products.|\n||Explore<br>diverse<br>teaching<br>methods,<br>integrating<br>case teaching,<br>inquiry-based<br>learning,<br>flipped<br>classroom and<br>other<br>innovative<br>models.|• No meani<br>or clear mi<br>approach a|ngful diversification<br>smatch between<br>nd content.<br>|• Attempts to use<br>diversified<br>approaches, but<br>mainly lists labels<br>without clear<br>operational steps.<br>•<br>Integration/transition<br>is weak; participation<br>structures are limited.<br>urnal P|<br> <br>• Lists approach labels<br>without operational<br>steps.<br>• Participation<br>structures are<br>superficial; learning<br>experience remains<br>monotonous.<br>re-proof|• Implements 1–2<br>approaches (e.g., group<br>work + task-based activity)<br>with basic feasibility.<br>• Student participation is<br>present but<br>integration/transition is<br>moderate; lecture segments<br>remain dominant in places.|•Selects an approach suitable to<br>content and learners (e.g., task-<br>based/PWP), with explicit phase-<br>by-phase enactment.<br>• Integrates ≥2 approaches<br>purposefully (activation →<br>inquiry/task → transfer output)<br>without method stacking.<br>• Ensures student agency via<br>concrete mechanisms (roles,<br>collaboration protocol, peer<br>feedback).|\n|**Ideate**|Able to design<br>or integrate<br>various<br>teaching<br>resources<br>(e.g., task<br>sheets,<br>educational<br>games) to<br>enhance<br>learning<br>experience.|• Essential<br>or clearly<br>objectives.|resources are missing<br>misaligned with<br> <br>|<br>• Provides basic<br>resources but with<br>limited variety or<br>alignment to<br>tasks/objectives.<br>•<br>Instructions/example<br>s are incomplete;<br>differentiation is<br>minimal.<br>Jo|• Resources are<br>fragmented or weakly<br>connected to tasks;<br>usability is mediocre.<br>• Instructions/examples<br>are insufficient,<br>hindering independent<br>work.<br>|<br>• Provides at least one key<br>resource (e.g., task sheet)<br>that supports core activity<br>completion.<br>• Usability is acceptable;<br>limited differentiation or<br>exemplars.|• Provides ≥2 resource types<br>aligned to objectives (task<br>sheet, map pack, language<br>frames, game/interactive tool)<br>with stated timing and purpose.<br>• Supports differentiation<br>(tiered tasks/optional<br>challenges).<br>• Resources are classroom-<br>ready: clear layout,<br>instructions, examples, and<br>criteria.|', '研究细化了设计思维在教学设计中的具体表现，包括教学方法的多样性、资源的选择以及重难点的处理。', NULL, 'DRAFT', '2026-09-12 19:56:24', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"81fcad194c7576eb90f4f61af04db358118d80b8d095f10b2a9dc6d12a3d6203\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.016129032258064516, \"sourceMessageId\": 190}', 'DRAFT', 65, NULL, NULL, 1029, 34, '81fcad194c7576eb90f4f61af04db358118d80b8d095f10b2a9dc6d12a3d6203', 0.016129, 190);
INSERT INTO `evidence_card` VALUES (5027, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '列出了教学设计的评估量规，明确包含对学习者进行分析、明确教学目标以及确定重难点等教学设计关键环节的描述。', NULL, NULL, NULL, NULL, '界定了研究中关注的教学设计要素，即前期分析（Discover）、目标设定（Define）等。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '397–417). Cambridge University Press. \n\n- Scardamalia, M., & Bereiter, C. (2022). Knowledge building and Knowledge creation. In R. K. Sawyer (Ed.), _The Cambridge Handbook of the Learning Sciences_ (pp. 385–405). Cambridge University Press. \n\n- Shively, K., & Palilonis, J. (2018). Curriculum development: Preservice teachers’ perceptions of design thinking for understanding digital literacy as a curricular framework. _Journal of Education_ , _198_ (3), 202-214. https://doi.org/10.1177/0022057418811128 \n\n- Siemens, G., & Gasevic, D. (2012). Guest editorial-learning and knowledge analytics. _Journal of Educational Technology & Society, 15_ (3), 1-2. \n\n- Tao, D., & Zhang, J. (2021). Agency to transform: how did a grade 5 community co-configure dynamic knowledge building practices in a yearlong science inquiry? _International_ \n\n51 \n\n_Journal of Computer-Supported Collaborative Learning_ , 16, 403-404. https://doi.org/10.1007/s11412-021-09353-7 \n\n- Thuan, N. H., & Antunes, P. (2024). A conceptual model for educating design thinking dispositions. _International Journal of Technology and Design Education_ , _34_ (5), 1879– 1902. https://doi.org/10.1007/s10798-024-09881-x \n\n- Tong, Y., Yang, C., & Chen, G. (2024). A visual learning analytics approach for knowledge building: Impact on students\' epistemic understanding of discourse, productive inquiry and domain knowledge. _British Journal of Educational Technology_ , _55_ (3), 992-1019. https://doi.org/10.1111/bjet.13409 \n\n- Tseng, J. J., Cheng, Y. S., & Yeh, H. N. (2019). How pre-service English teachers enact TPACK in the context of web-conferencing teaching: A design thinking a pproach. _Computers & Education_ , _128_ , 171-182. <u>https://doi.org/10.1016/j.compedu. 2018.09.022</u> \n\n- Van Aalst, J., & Chan, C. K. K. (2007). Student-directed assessment of knowledge building using electronic portfolios. _The Journal of the Learning Sciences, 16_ , 175–220. https://doi.org/10.1080/10508400701193697 \n\n- Verma, G., Campbell, T., Melville, W., & Park, B. Y. (2023). Navigating opportunities and challenges of artificial intelligence: ChatGPT and generative models in science teacher education. _Journal of Science Teacher Education, 34_ (8), 793–798. https://doi.org/10.1080/1046560X.2023.2263251 \n\n- White, B. Y., & Frederiksen, J. R. (1998). Inquiry, modeling, and metacognition: Making science accessible to all students. _Cognition and instruction_ , _16_ (1), 3-118. https://doi.org/10.1207/s1532690xci1601_2 \n\n- Wise, A. F., Knight, S., & Shum, S. B. (2021). Collaborative learning analytics. In Cress, U., Rosé, C., Wise, A.F., Oshima, J. (eds), _International handbook of computer-supported collaborative learning_ (pp. 425-443). Springer. https://doi.org/10.1007/978-3-03065291-3_23 \n\n- Wise, A. F., & Schwarz, B. B. (2017). Visions of CSCL: Eight provocations for the future of the field. _International Journal of Computer-Supported Collaborative Learning_ , _12_ (4), 423-467. https://doi.org/10.1007/s11412-017-9267-5 \n\n- Yüksel, A. O. (2025). Design-based STEM activities in teacher education and its effect on pre-service science teachers’ design thinking skills.', '研究明确了教学设计中需要重点关注的问题域，包括学习者特征分析、课程序列逻辑及教学目标的具体化。', NULL, 'DRAFT', '2026-09-12 19:56:24', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"79e0c609447da073cead7688ac8787eccba0ec9c9f4ed55b4ecceda550bfd009\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015625, \"sourceMessageId\": 190}', 'DRAFT', 65, NULL, NULL, 1029, 34, '79e0c609447da073cead7688ac8787eccba0ec9c9f4ed55b4ecceda550bfd009', 0.015625, 190);
INSERT INTO `evidence_card` VALUES (5028, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '定义了在线知识论坛笔记中分析教学设计问题的编码框架，涉及发现（分析学习者特征）、定义（设定目标）、构思与原型等阶段。', NULL, NULL, NULL, NULL, '提供了分析教学与学习问题的具体工具和维度，反映了研究对设计过程的关注。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '41 \n\nAppendix C. The assessment rubric for grading PSTs’ DT in instructional design of lesson plans. \n\n|**Dimension**<br>**s**|**Operational**<br>**Description**|**Not Met**|**Needs**<br>**Improvement**|**Partially**<br>**Met**|**Satisfactory**|**Excellent**|\n|---|---|---|---|---|---|---|\n|**Discover**|Accurate<br>description of<br>the<br>relationships,<br>status and<br>roles of<br>knowledge<br>points in<br>teaching<br>content, with<br>clear analysis<br>of key and<br>difficult<br>points.|• Topic positioning is unclear or<br>inaccurate; no curriculum-theme<br>alignment.<br>• No meaningful account of<br>inter-unit relations or the unit’s<br>instructional role.<br>|<br>• Partially aligns the<br>unit within the<br>curriculum sequence,<br>but the rationale is<br>fragmented or<br>generic.<br>• Mentions adjacent<br>units with unclear<br>skill/knowledge<br>carryover.<br>al P|<br>• Describes the topic<br>only; provides weak or<br>fragmented<br>justification of<br>status/function.<br>• Connections to<br>adjacent units are<br>vague, partial, or<br>partially misaligned.<br>• Lists information<br>without a coherent<br>explanatory chain.<br>re-proof|<br>• States the topic and<br>practical value; overall<br>sequencing is largely<br>accurate.<br>• Mentions links to adjacent<br>units but with limited<br>specificity (e.g., lacks<br>explicit language/skill<br>carryover).<br>• Mostly accurate but<br>somewhat verbose or<br>unfocused.|• Aligns the unit topic with the<br>curriculum theme cluster and<br>articulates authentic<br>communicative value.<br>• Explicitly maps prerequisite<br>and subsequent units (e.g., Unit<br>7/Unit 9) to show progression<br>of language knowledge and<br>skills, and justifies this unit’s<br>role in the scope-and-sequence.<br>• Concise yet complete<br>rationale (“what/why/how<br>used”), avoiding generic<br>claims.|\n||Learner<br>analysis (e.g.,<br>interests,<br>needs, group<br>characteristics<br>) can be<br>conducted via<br>technical<br>means.|• No learner analysis or<br>evidence; purely anecdotal<br>assumptions.<br>|• Uses a tool but<br>evidence is<br>incomplete (e.g., no<br>raw outputs);<br>findings remain<br>surface-level.<br>• Limited linkage<br>from learner analysis<br>to design decisions.<br>Journ|• Claims tool use but<br>provides no<br>interpretable results;<br>relies mainly on<br>impressions.<br>• Weak linkage from<br>analysis to goals, tasks,<br>or resources.<br>|<br>• Uses one tool (e.g., survey<br>or quiz) with basic evidence<br>recorded.<br>• Produces 1–2 plausible<br>findings and makes some<br>adjustments; limited depth<br>(e.g., no variability<br>analysis).|<br> <br>• Collects evidence with ≥2<br>tools (e.g., online<br>quiz/survey/LMS analytics)<br>and archives raw outputs<br>(screenshots/tables).<br>• Derives a data-based learner<br>profile (≥3 actionable findings:<br>interests, misconceptions,<br>variability) and links each to<br>design decisions (scaffolds,<br>differentiation, pacing).|\n|**Define**|Clear, specific<br>teaching<br>objectives that<br>are easy to|• Objectives are absent or<br>seriously non-standard; cannot<br>guide instruction or assessment.|• Objectives are<br>stated but only partly<br>measurable;|• Vague verbs (e.g.,<br>understand/know)<br>dominate; objectives<br>are hard to assess.|• Objectives are generally<br>clear and observable; some<br>are broad or missing success<br>criteria.|42<br> <br>•Objectives are measurable and<br>performance-based (action verb +<br>condition + product), e.g., role-play|', '研究通过编码框架系统化地考察了职前教师在在线讨论中关于教学设计问题的互动与思维发展。', NULL, 'DRAFT', '2026-09-12 19:56:24', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"78361f6bb5fd4aedea96254b00f890a3524c6775b771bee9aedb51eecd58855b\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015873015873015872, \"sourceMessageId\": 190}', 'DRAFT', 65, NULL, NULL, 1029, 34, '78361f6bb5fd4aedea96254b00f890a3524c6775b771bee9aedb51eecd58855b', 0.015873, 190);
INSERT INTO `evidence_card` VALUES (5029, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '研究摘要明确指出研究对象为110名职前教师（PSTs），旨在检验整合生成式AI和反思评估对职前教师设计思维的影响', NULL, NULL, NULL, NULL, '直接界定了研究取样的目标群体为职前教师', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '# Journal Pre-proof \n\nFostering Preservice Teachers’ Design Thinking by Integrating Generative AI and Analytics-Supported Reflective Assessment in a Collaborative Inquiry Environment \n\nYuqin Yang, Linbaiyu Chen, Daner Sun, Wangda Zhu, Shiyan Pang \n\n\n\nPII: S0360-1315(26)00040-0 DOI: https://doi.org/10.1016/j.compedu.2026.105602 Reference: CAE 105602 \n\nTo appear in: _Computers & Education_ \n\nReceived Date: 26 August 2025 Revised Date: 20 February 2026 Accepted Date: 22 February 2026 \n\nPlease cite this article as: Yang Y., Chen L., Sun D., Zhu W. & Pang S., Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI and Analytics-Supported Reflective Assessment in a Collaborative Inquiry Environment, _Computers & Education_ , https://doi.org/10.1016/ j.compedu.2026.105602. \n\nThis is a PDF of an article that has undergone enhancements after acceptance, such as the addition of a cover page and metadata, and formatting for readability. This version will undergo additional copyediting, typesetting and review before it is published in its final form. As such, this version is no longer the Accepted Manuscript, but it is not yet the definitive Version of Record; we are providing this early version to give early visibility of the article. Please note that Elsevier’s sharing policy for the Published Journal Article applies to this version, see: https://www.elsevier.com/about/policies-and- <u>standards/sharing#4-published-journal-article. Please also note that, during the production process,</u> errors may be discovered which could affect the content, and all legal disclaimers that apply to the journal pertain. \n\n© 2026 Published by Elsevier Ltd. \n\n## **Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI and Analytics-Supported Reflective Assessment in a Collaborative Inquiry Environment** \n\nYuqin Yang & Linbaiyu Chen Central China Normal University, China \n\nDaner Sun \n\nThe Education University of Hong Kong \n\nWangda Zhu \n\nThe Hong Kong Polytechnic University, Hong Kong \n\nShiyan Pang * Central China Normal University, China _Yuqin Yang_ , Faculty of Artificial Intelligence in Education, Central China Normal University, Wuhan, Hubei, China E-mail: yangyuqin@ccnu.edu.cn _Linbaiyu Chen_ , Faculty of Artificial Intelligence in Education, Central China Normal University, Wuhan, Hubei, China E-mail: baiyu_cl_apply@163.com _Daner Sun_ , Department of Mathematics and Information Technology, The Education University of Hong Kong, Hong Kong S.A.R. E-mail: dsun@eduhk.hk dsun@eduhk.hk Wangda Zhu, School of Design The Hong Kong Polytechnic University, Hong Kong S.A.R. E-mail: wangda.zhu@polyu.edu.hk \n\n_Linbaiyu Chen_ , Faculty of Artificial Intelligence in Education, Central China Normal University, Wuhan, Hubei, China \n\n_Daner Sun_ , Department of Mathematics and Information Technology, The Education University of Hong Kong, Hong Kong S.A.R. E-mail: dsun@eduhk.hk dsun@eduhk.hk \n\n_Shiyan Pang_ , Associate Professor* \n\nFaculty of Artificial Intelligence in Education, Central China Normal University, Hubei, China \n\nEmail: <u>pangsy@ccnu.edu.cn</u> \n\n## *** Corresponding author** \n\n_Shiyan Pang_ , Faculty of Artificial Intelligence in Education, Central China Normal University, NO.152 Luoyu Road, Wuhan, Hubei, P. R. China, 430079. E-mail: <u>pangsy@ccnu.edu.cn</u> \n\n## **Note to the Editor** \n\nThe corresponding author is currently on maternity leave following the birth of a baby and may have limited access to email during this period. To ensure timely communication and avoid any delays in the submission- and review-related process, \n\nplease contact the first author first for all manuscript-related correspondence. \n\n_Primary contact: Yuqin Yang, [yangyuqin@ccnu.edu.cn]._ \n\nThe first author is authorized to handle all submission- and review-related matters for this manuscript on behalf of the author team. \n\n## **Declaration** \n\n**Availability of data and materials:** These data will be made available to other researchers on a case-by-case basis. \n\n**Acknowledgments:** The authors are indebted to the participating students.', '进一步确证研究目标群体的身份是职前教师，与当前小学三年级学生及教学情境存在迁移边界，仅为高阶师范教育提供参考。', NULL, 'DRAFT', '2026-09-12 19:57:04', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"0b1164ad6adc7f959244e5e1f9fdb923a80841ef2e74cdbb96f5f62be2445cdd\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015384615384615384, \"sourceMessageId\": 192}', 'DRAFT', 66, NULL, NULL, 1029, 34, '0b1164ad6adc7f959244e5e1f9fdb923a80841ef2e74cdbb96f5f62be2445cdd', 0.0153846, 192);
INSERT INTO `evidence_card` VALUES (5030, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '研究明确探究了职前教师在协作探究知识建构环境中整合生成式AI与分析支持反思评估对设计思维的影响，并关注DT能力的发展轨迹。', NULL, NULL, NULL, NULL, '直接说明了研究对象的能力发展焦点为设计思维及其演进过程。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, 'To ensure timely communication and avoid any delays in the submission- and review-related process, \n\nplease contact the first author first for all manuscript-related correspondence. \n\n_Primary contact: Yuqin Yang, [yangyuqin@ccnu.edu.cn]._ \n\nThe first author is authorized to handle all submission- and review-related matters for this manuscript on behalf of the author team. \n\n## **Declaration** \n\n**Availability of data and materials:** These data will be made available to other researchers on a case-by-case basis. \n\n**Acknowledgments:** The authors are indebted to the participating students. **Funding:** This study is supported by national-level funding to the first author, and removed for blinded review. \n\n**Authors’ biographies** _Yuqin Yang_ is a full professor of the learning sciences at the Faculty of Artificial Intelligence in Education in Central China Normal University. Her research interests include pedagogy and assessment of knowledge building, data science education, learning analytics, and collaborative learning. Her publications have appeared in international journals such as Computers & Education, Internet and Higher Education, American Educational Research Journal, International Journal of Computer-Supported Collaborative Learning, British Journal of Educational Technology, Teaching and Teacher Education, International Journal of Educational Technology in Higher Education, and Journal of Computer Assisted Learning. She also serves as guest editors and board members for some journals, such as British Journal of Educational Technology, Learning and Instruction. She also services as associate editors for journals such as International Journal of Computer-Supported Collaborative Learning, Learning: Research and Practices, and board members for several journals such as Learning & Instruction, Learning and Individual Differences. _Linbaiyu Chen_ is a research assistant at the Faculty of Artificial Intelligence in Education in Central China Normal University. Her research interests include design thinking, GenAI-augmented learning, dialogic pedagogy, knowledge-building pedagogy and learning analytics. _Daner Sun_ is associate professor at the Department of Mathematics and Information Technology, The Education University of Hong Kong. Her research interests are ICT-supported science learning, seamless learning and teacher education. Her publications have appeared in international journals such as Computers & Education, British Journal of Educational Technology, International Journal of Computer-Supported Collaborative Learning, Journal of Research in Science Teaching, and Education Technology and Society. She also services as associate editors for several journals such as Education and Information Technologies, and Educational Technology and Society \n\nWangda Zhu is an Assistant Professor of Interaction Design at The Hong Kong Polytechnic University. His research focuses on creative learning system design and development, with particular interests in design education, learning analytics, and AIpowered educational technologies. His publications have appeared in leading journals \n\nsuch as Computers & Education, British Journal of Educational Technology, and Internet and Higher Education, as well as in major conferences including LAK, ASEE, and AIED, where his work has received multiple best paper nominations. \n\n_Shiyan Pang_ is an associate professor at the Faculty of Artificial Intelligence in Education at Central China Normal University. Her research interests include, application of artificial intelligence in education, data mining, classroom data analysis. Her publications have appeared in international journals such as ISPRS Journal of Photogrammetry and Remote Sensing, Journal of Computing in Higher Education and International Journal of Remote Sensing. \n\n## **Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI and Analytics-Supported Reflective Assessment in a Collaborative Inquiry Environment** \n\nFostering preservice teachers’ (PSTs) design thinking (DT) is essential for addressing complex instructional challenges, yet remains difficult to achieve in teacher education. Although generative artificial intelligence (GenAI) and analytics-supported reflective assessment (ASRA) show promise for supporting DT, how they can be pedagogically integrated within collaborative inquiry remains relatively underexplored. The study aimed to explore the effects of the combined use of GenAI and ASRA within a collaborative inquiry Knowledge Building (KB) environment on PSTs’ DT, and how their DT competencies evolves with this integrative design. Participants were 110 PSTs enrolled in a semester-long instructional design course. We proposed a conceptual framework integrating collaborative inquiry, strategically delayed GenAI use, and ASRA, and operationalized it through a pedagogical model that positions GenAI as a cognitive and reflective design partner rather than a solution provider. Multiple data sources were analyzed, including a DT competency scale, successive instructional design artifacts, and 1,305 online discourse notes. Results showed significant gains in problem discovery and definition, along with a developmental shift from stage-bound engagement toward more integrated and iterative practices, particularly in prototyping and testing. GenAI was most effective when introduced after human-only design efforts, while reflective analytics supported monitoring of collective progress and sustained iteration.', '支持：关注职前教师设计思维能力的发展。', NULL, 'DRAFT', '2026-09-12 19:57:57', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"943409d59865b392ad7f6c51c83c4ecda85d9c0268a0ea2f93fba6b8259c62ae\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.01639344262295082, \"sourceMessageId\": 194}', 'DRAFT', 66, NULL, NULL, 1029, 34, '943409d59865b392ad7f6c51c83c4ecda85d9c0268a0ea2f93fba6b8259c62ae', 0.0163934, 194);
INSERT INTO `evidence_card` VALUES (5031, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '研究结果显示，参与者在构思与测试阶段表现出认知和认识论要求的提升，并在人机共创阶段实现了从阶段性参与向整合性、迭代性实践的明显转变。', NULL, NULL, NULL, NULL, '具体揭示了所关注的能力内涵，包括迭代性实践与认知判断。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, 'Because the analytic sample consisted of 103 matched cases after excluding seven incomplete or inattentive responses, the results reflect stable within-participant change rather than large cohort-level differences. First, ideation and testing impose higher cognitive and epistemic demands, requiring learners to generate multiple alternatives, evaluate trade-offs, and revise solutions iteratively. Prior studies show that novice designers often experience cognitive overload in these phases and may underestimate their progress when design work becomes more complex and uncertain (Ohly et al., 2017). Second, in this study, GenAI use was intentionally delayed until PSTs had exhausted human-only \n\n33 \n\nrevision. This design may have shifted learners’ focus from perceived fluency to critical judgment, which could explain smaller gains on self-report measures but stronger improvements on performance-based outcomes. \n\nEvidence from instructional design artifacts and discourse trajectories provides a complementary perspective. Repeated-measures analyses showed clearer developmental gains in enacted design practices than in self-reported perceptions, suggesting that PSTs’ design capabilities may have evolved earlier than their self-evaluations. From a design-based research perspective, such divergence between perceived and enacted development is theoretically meaningful, as it indicates that pedagogical change may first manifest in practice before becoming visible in learners’ self-assessment. This triangulation of multiple data sources therefore strengthens the interpretation of DT growth beyond reliance on a single measure. In particular, the human–GenAI co-designed phase demonstrated accelerated growth between early and middle design cycles, suggesting that GenAI functioned as a catalyst for idea elaboration and refinement once foundational problem framing was established. These results underscore that the role of GenAI was not simply additive but developmental, supporting iterative refinement within an ongoing inquiry trajectory. The results align with and extend existing research. First, studies on GenAI in teacher education show benefits for brainstorming, drafting, and feedback (An et al., 2025; Nyaaba & Zhai, 2024), yet often report uneven gains across design phases (e.g., stronger idea fluency than systematic testing). Our results replicate these uneven patterns while offering a process-level explanation: ideation and testing benefited most when GenAI was embedded within reflective, analytics-informed inquiry rather than used as an immediate solution generator. Second, compared with prior KB studies that rely primarily on human facilitation (e.g., Lin et al., 2020), our results show that combining GenAI prompts with analytics-supported reflection reduces unproductive cycling and increases higher-order loops across phases, especially in prototyping and testing. This design operationalizes human–AI co-agency by maintaining learner ownership of decisions while using GenAI for generative support and analytics for regulatory guidance. _5.2. PSTs’ DT Evolution Paths with the Combined use of GenAI and ASRA_ This study traced how PSTs’ DT evolved across three phases of collaborative inquiry. Content analysis of 1,305 Knowledge Forum notes revealed a clear developmental shift from early-stage problem framing and ideation toward later-stage prototyping and testing. While ideation was most frequent in Phase 1, Phase 2 and 3 were marked by steady increases in prototyping and testing, accompanied by a small rebound in problem definition—suggesting that learners revisited and refined problem framing as their solutions matured. Transition analysis further revealed that early phases were characterized by persistence within single stages and fragmented links between stages. Over time, however, transitions between definition and ideation became stronger, and iterative loops between prototyping and testing grew more interconnected. Together, these patterns indicate that PSTs gradually moved from stage-bound engagement toward more integrated and iterative design activity, a trajectory that resembles key characteristics of expert-like design practice reported in prior DT research. Importantly, these interpretations reflect the study’s analytic framing. Because Knowledge Forum discourse was examined at an aggregated phase level, frequency shifts and transition patterns are interpreted as indicators of collective inquiry development rather than independent participantlevel effects. Consistent with design-based research, the analyses aim to trace trajectories of practice evolution within an authentic learning context rather than establish causal comparisons across isolated units. \n\nThese results enrich prior research on KB and DT in teacher education. Earlier studies have shown that PSTs often remain at descriptive or early stages of inquiry without sustained \n\n34 \n\nscaffolding (Hong et al., 2025). The study’s results align with these patterns in Phase 1, while further illustrating how the combined use of GenAI and ASRA may help reorganize discourse trajectories toward iterative refinement and cross-phase integration over time.', '支持：关注从阶段性设计转向整合性、迭代性设计实践的能力发展。', NULL, 'DRAFT', '2026-09-12 19:57:57', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"81a6a81e80e5fd8f54ebf8445660fa3d0282ab6058843ff7f318021fb9725c78\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.016129032258064516, \"sourceMessageId\": 194}', 'DRAFT', 66, NULL, NULL, 1029, 34, '81a6a81e80e5fd8f54ebf8445660fa3d0282ab6058843ff7f318021fb9725c78', 0.016129, 194);
INSERT INTO `evidence_card` VALUES (5032, '项目资料证据：2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, NULL, NULL, NULL, '研究探讨了将生成式AI作为一种认知和反思的设计伙伴，以支持迭代式教学设计与反思规范的形成，强调培养协作设计文化和批判性采纳AI建议的能力。', NULL, NULL, NULL, NULL, '明确指出了人机协同及反思评估作为研究关注的核心素养。', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, 'These results enrich prior research on KB and DT in teacher education. Earlier studies have shown that PSTs often remain at descriptive or early stages of inquiry without sustained \n\n34 \n\nscaffolding (Hong et al., 2025). The study’s results align with these patterns in Phase 1, while further illustrating how the combined use of GenAI and ASRA may help reorganize discourse trajectories toward iterative refinement and cross-phase integration over time. This processoriented evidence complements existing work on GenAI in education, which have emphasized its potential for positive learning outcomes such as idea generation and social-emotional learning (Henriksen et al., 2025; Verma et al., 2023), but offered limited empirical evidence of how GenAI shapes the temporal structure of DT processes. process trajectories of DT over time. By examining both frequency distributions and transition patterns, this study demonstrates that the added value of GenAI and ASRA lies not only in increasing activity levels within individual DT phases, but also in strengthening connections across phases and supporting sustained iteration. \n\nRather than probabilistic claims about independent behaviors, transition statistics are interpreted as descriptive signals of evolving discourse organization within collaborative inquiry, consistent with learning sciences approaches that emphasize process trajectories and epistemic development over isolated counts. In this sense, the integrated design contributes to KB research by providing empirical evidence that a GenAI-supported and analytics-informed KB environment can foster more coherent and reflective design trajectories in PSTs. While this study does not examine large-scale implementation or cross-context transfer, its practical contribution lies in transferable pedagogical logics rather than immediate generalizability. The core design principles including cultivating a collaborative design culture, strategically delaying GenAI use, and embedding analytics-supported reflection within KB inquiry are not tied to a specific subject area, technology platform, or class size. Future work should examine how these principles function across institutions, cohorts, and teacher education contexts, and how they can be adapted for scaled or blended implementations. _5.3. Implications for Educational Practices for Supporting PSTs’ DT_ This study’s results offer actionable design implications for supporting PSTs’ DT in AI-rich teacher education contexts. First, a collaborative design culture should be established before intensive GenAI use, with explicit norms for idea improvement, critique, and shared responsibility. Such a foundation enables PSTs to engage with DT as a collective knowledgebuilding activity rather than as individual task completion. Second, GenAI should be introduced strategically rather than continuously. Delayed or conditional access encourages PSTs to engage in independent reasoning and peer-based refinement before turning to AI support. When combined with requirements to justify the adoption or rejection of AI suggestions, this approach positions GenAI as a resource for reflection and comparison, rather than an authoritative solution provider. Third, structured reflective prompts and analytics-based visualizations are essential for supporting sustained DT. These tools help PSTs monitor collective progress, identify gaps in design reasoning, and coordinate inquiry across phases, making complex design processes visible and manageable. Finally, instructional design artifacts should be treated as evolving objects, with planned cycles of revision, reflection, and justification. This practice aligns learning activities with the iterative and non-linear nature of authentic design work and supports DT as a developmental process. Overall, these implications highlight that the educational value of GenAI lies not in automation, but in principled pedagogical integration that foregrounds reflection, judgment, and collaborative inquiry. \n\n## _5.4. Limitations and Future Directions_ \n\nThis study has several limitations that also point to directions for future work. First, the participating PSTs were relatively homogeneous, consisting mainly of female PSTs from an \n\n35 \n\nEnglish education program at a teacher education university. While this reflects the typical composition of the program, it limits the generalizability of the findings to other subject domains, institutional settings, or more gender-balanced cohorts. Future research should examine whether similar DT trajectories emerge in PST programs with different disciplinary focuses and demographic profiles. Second, the intervention was implemented by an instructor with extensive prior experience in KB and ASRA, which may introduce instructor expectancy effects. Although this expertise supported faithful implementation, future studies could involve multiple instructors or use more standardized facilitation protocols to better separate instructional design effects from instructor-related influences. Third, the instructional sequence required PSTs to first produce a human-only instructional design before engaging in GenAIsupported co-design, which introduces a potential order or practice effect. This sequencing was intentionally designed to foreground epistemic agency and reduce premature reliance on AI; however, it limits causal claims about the independent contribution of GenAI. Future work could adopt counterbalanced or parallel-group designs to more rigorously isolate the effects of GenAI at different points in the design process.', '支持：关注反思评估与基于AI的判断和协作设计能力。', NULL, 'DRAFT', '2026-09-12 19:57:57', NULL, NULL, '{\"fileId\": 34, \"chunkId\": \"5a8f95ee391bbf15284f46757e2b57e54546edbbaf47036eb030c4130c742350\", \"filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"projectId\": 1029, \"sourceType\": \"UPLOADED_RESOURCE\", \"retrievalScore\": 0.015384615384615384, \"sourceMessageId\": 194}', 'DRAFT', 66, NULL, NULL, 1029, 34, '5a8f95ee391bbf15284f46757e2b57e54546edbbaf47036eb030c4130c742350', 0.0153846, 194);
INSERT INTO `evidence_card` VALUES (5033, '职前教师设计思维（DT）的培育', NULL, NULL, '职前教师设计思维（DT）的培育', NULL, '110名职前教师（20-22岁）', NULL, NULL, '职前教师在整合生成式AI与分析支持的反思的协作环境中，其设计思维整体上有统计学上显著但幅度较小的提升（前测 M=5.15，SD=0.60；后测 M=5.25，SD=0.58；t(102)=2.151, p=.034, d=0.21）。\n在设计思维各子维度中，发现（Discover）和定义（Define）维度提升显著（发现维度 p=.026；定义维度 p=.019），而构思（Ideate）和测试（Test）维度未达到统计显著性。\n对1305条知识论坛笔记的内容分析表明，职前教师的设计实践从早期的问题界定和构思阶段，逐渐转向后期的原型制作和测试阶段。\n随着设计方案的成熟，职前教师会重新审视并细化问题定义，展现出设计思维的迭代性和自适应特征。\n在人机共创阶段，职前教师在设计和实现过程的中后期展现出加速成长，生成式AI起到了促进构思细化和迭代优化的催化剂作用。', NULL, NULL, '数据可以加入音视频数据', NULL, 'Agent能够促进学生的设计思维发展', '2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-12 21:12:46', '[\"教学设计评估框架、编码框架及职前教师作品评价\"]', '[\"14weeks\"]', '{\"sha256\": \"4134d6da05d2d357cf6aaf2d4bbfaaff27a62062c8310b913f92a3d99dedc96b\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1029, \"size_bytes\": 4058595, \"resource_id\": 34, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"2026-C&E-Yang-Fostering Preservice Teachers’ Design Thinking by Integrating Generative AI.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 73, NULL, NULL, 1029, 34, NULL, NULL, NULL);
INSERT INTO `evidence_card` VALUES (5034, '666', NULL, NULL, '666', NULL, '666', NULL, NULL, '666', NULL, NULL, '666', NULL, '666', '1-s2.0-S036013152500260X-main.pdf', NULL, '', NULL, NULL, 'DRAFT', '2026-09-12 21:30:06', '[\"666\"]', '[\"666\"]', '{\"sha256\": \"5f7a796ea922d3a80bc78f6d36581fcc404972a94ef3e6f684fbbe096efccc53\", \"file_id\": null, \"chunk_id\": null, \"citations\": [], \"media_type\": \"application/pdf\", \"project_id\": 1030, \"size_bytes\": 2249862, \"resource_id\": 35, \"source_type\": \"UPLOADED_RESOURCE\", \"source_label\": \"1-s2.0-S036013152500260X-main.pdf\", \"original_text\": null, \"retrieval_score\": null, \"original_filename\": \"1-s2.0-S036013152500260X-main.pdf\", \"source_message_id\": null, \"verification_note\": null}', 'DRAFT', 76, NULL, NULL, 1030, 35, NULL, NULL, NULL);
INSERT INTO `pedagogy_method` VALUES (4001, 'INQUIRY_BASED', '探究式学习', '围绕问题提出猜想、收集证据、比较解释并形成结论。', '适合需要证据判断、解释和探究的问题。', '信息核验、比较多个来源、形成证据化判断。', 'PRIMARY', '提出问题 → 初步判断 → 搜集证据 → 比较解释 → 形成结论', '组织问题情境、提供支架、追问证据。', '提出观点、搜集证据、比较并修正判断。', '提供待核验的信息、补充观点或提出挑战。', '如果AI过早给出完整答案，可能削弱学生自己的判断过程。', 'ped_demo_4001');
INSERT INTO `pedagogy_method` VALUES (4002, 'PROJECT_BASED', '项目式学习', '围绕真实项目产出组织较长周期的学习活动。', '适合综合性、成果导向目标。', '制作作品、解决真实问题、持续迭代。', 'PRIMARY', '真实问题 → 方案设计 → 制作 → 测试 → 展示', '组织项目、提供资源和反馈。', '协作完成项目并持续迭代。', '辅助资料整理、创意拓展与反馈。', '需避免AI替学生完成核心产出。', 'ped_demo_4002');
INSERT INTO `pedagogy_method` VALUES (4003, 'PROBLEM_BASED', '问题式学习', '以复杂问题作为知识学习和问题解决的组织核心。', '适合问题分析、证据应用与方案提出。', '分析案例、提出方案、解释理由。', 'PRIMARY', '问题呈现 → 知识缺口 → 自主学习 → 方案讨论 → 反思', '提供问题、促进讨论和反思。', '界定问题并共同提出方案。', '补充信息、提出反例。', '可能出现学生直接依赖AI生成解决方案。', 'ped_demo_4003');
INSERT INTO `pedagogy_method` VALUES (4004, 'SITUATED_EXPERIENTIAL', '情境体验式学习', '通过具体情境和体验任务促进理解与应用。', '适合情境判断和实践应用。', '模拟任务、角色体验、实践操作。', 'PRIMARY', '情境进入 → 体验 → 观察 → 解释 → 应用', '创设情境并组织反思。', '参与体验并解释经验。', '模拟情境或提供反馈。', '需要保证体验之后有充分反思。', 'ped_demo_4004');
INSERT INTO `pedagogy_method` VALUES (4005, 'COLLABORATIVE', '协作学习', '通过同伴互动、观点比较和共同产出促进学习。', '适合需要多视角比较与共同判断的目标。', '小组讨论、同伴核验、共同规则建构。', 'PRIMARY', '个人思考 → 小组分享 → 证据比较 → 协商 → 共同产出', '组织分组、促进公平参与。', '分享观点、比较证据、协商结论。', '提供挑战观点或作为额外信息源。', '需要防止少数成员或AI主导小组判断。', 'ped_demo_4005');
INSERT INTO `project_activity` VALUES (8001, 1001, 1, '先判断：这条AI回答可信吗？', 10, '呈现一条包含可疑信息的固定Demo AI回答，不立即给出正确答案。', '个人阅读并标出自己认为需要核验的内容，写下初步判断。', 'TEACHER_DEMO', 'STUDENT', '[6001, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8002, 1001, 2, '向AI追问并记录新信息', 15, '提示学生记录AI补充了什么，而不是直接采纳答案。', '向AI提出澄清问题，并记录AI增加、挑战或改变了哪些信息。', 'STUDENT_QUERY', 'STUDENT', '[6001, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8003, 1001, 3, '多来源核验', 25, '提供两个固定Demo信息来源，并示范如何记录来源差异。', '比较AI回答与两个信息来源，填写“主张—来源—证据—判断”记录。', 'EVIDENCE_SUPPORT', 'STUDENT', '[6002]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8004, 1001, 4, '小组比较与挑战', 20, '追问“你的证据是什么？”并提醒区分观点与证据。', '小组比较各自判断，对分歧点提出证据并修正结论。', 'IDEA_CHALLENGE', 'COLLABORATIVE', '[6002, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8005, 1001, 5, '形成AI信息核验规则', 10, '组织全班汇总，并明确规则仍需结合具体任务使用。', '总结至少三条核验规则，并说明哪些AI建议被接受、修改或拒绝。', 'FEEDBACK', 'COLLABORATIVE', '[6001, 6002, 6003]', 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_activity` VALUES (8010, 1012, 1, '共同界定学习范围与提炼特征', 8, '展示三张代表性“aa”图片，引导全班提问与头脑风暴，板书关键词', '观察、举手发言提出可能特征，记录至少两条关键特征在练习本上', '在平板推送高清图片，自动高亮重复出现的特征词汇', 'STUDENT', '[6006, 6009]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '观察三个明确的“aa”示例并讨论其共有特点，形成初步定义', '口头抽查两名学生说出的两个特征，依据目标6006/6009评价表即时打勾', '[\"句型提示卡“我注意到…因为…”\", \"特征词库（颜色/形状/大小）\"]');
INSERT INTO `project_activity` VALUES (8011, 1012, 2, '正反例分类练习', 8, '分发数字卡片，示范一个正例和一个反例的判断思路', '拖拽卡片完成分类，在表格旁用一句话写出判断依据', '实时检测分类结果，对错误项弹出微提示', 'STUDENT', '[6007]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '将教师提供的六个项目分为“属于aa”和“不属于aa”两类，并写理由', '收集电子表格，检查每类≥2项且理由与特征关联，对应目标6007', '[\"T-Chart模板\", \"连接词“因为它有…所以…”\"]');
INSERT INTO `project_activity` VALUES (8012, 1012, 3, '独立创作“aa”新例子', 12, '巡视指导，提醒学生使用之前归纳的两条以上关键属性', '绘制或口述新例子，录制15秒语音说明其为何属于“aa”', '提供简易轮廓模板和颜色调色板，支持语音转文字字幕', 'STUDENT', '[6008, 6011, 6010]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '利用平板绘图工具或口头描述，设计一个符合“aa”特征的新实例并解释', '根据目标6008/6011/6010，核查作品是否体现主要特征、解释是否含≥2条属性', '[\"创作计划单\", \"词汇银行（名称/颜色/形状）\"]');
INSERT INTO `project_activity` VALUES (8013, 1012, 4, '同伴互评与反馈', 12, '组织快速轮换展示，强调礼貌倾听与积极反馈', '观看同伴作品，使用“我注意到……，因为……”口头或书写反馈并请同伴确认', '计时器管理展示节奏，自动采集反馈句子供教师查看', 'STUDENT', '[6012]', 1, '2026-09-07 17:33:07', '2026-09-07 17:33:07', '运用指定句型给同伴的作品提出一条具体反馈', '随机抽取三条反馈录音，评估句型完整性及指向的具体特征，对应目标6012', '[\"句型提示牌\", \"互评便利贴模板\"]');
INSERT INTO `project_activity` VALUES (8014, 1020, 1, '辨别AI信息真伪：引入与标准共建', 6, '呈现两条关于“校园宠物狗”的简短中文资讯，引导学生区分观点与事实；板书“需核验信息”的标准（如包含具体数字/时间/地点/可验证事件）', '在平板上用“是/否/不确定”标注每条资讯中的事实声明；与同伴讨论并提交自己认为最需要核验的一条', '展示AI生成资讯并提示风险点供学生对照', 'STUDENT', '[6014]', 1, '2026-09-09 19:18:45', '2026-09-09 19:18:45', '观察两条短文本（一条人类撰写、一条AI生成），找出可能的“事实声明”，共同制定“是否需要核验”的判断标准', '快速口头提问：为什么这条信息值得核验？收集学生的标注截图作为即时证据', '[\"标注模板（是/否/不确定）\", \"关键特征提示卡（数字/时间/地点/可核查事件）\"]');
INSERT INTO `project_activity` VALUES (8015, 1020, 2, '同伴互评：标注一致性核对', 7, '组织两人一组互评，提供评价要点：是否明确指出了事实声明、理由是否基于可验证性而非喜好', '对比同伴标注，讨论分歧并用一句话说明理由；修改或确认自己的标注，准备进入下一步核验', '提供“常见不可信信号”提示（如缺少来源、过于完美/夸张描述）辅助讨论', 'STUDENT', '[6014]', 1, '2026-09-09 19:18:45', '2026-09-09 19:18:45', '交换标注结果，比较判断理由，形成更可靠的“待核验清单”', '教师随机抽查2—3组，记录“标注—理由”是否匹配，给出过程性反馈', '[\"同伴互评清单\", \"理由句式支架（因为____，所以需要/不需要核验）\"]');
INSERT INTO `project_activity` VALUES (8016, 1020, 3, '选择两项进行来源核对与判定', 17, '分发统一的“核验工作单”；示范如何在可信平台检索关键词；提醒只使用课堂允许的来源目录；巡视并提供个别指导', '在平板上检索；将找到的来源链接/截图粘贴到工作单；逐条对照事实声明；以口头或文字说明“采信/不采信”并写出依据', '仅提供检索入口与关键词建议，不直接回答对错；自动过滤不在允许目录的网站', 'STUDENT', '[6014]', 1, '2026-09-09 19:18:45', '2026-09-09 19:18:45', '从给定AI资讯中任选两条，各查找至少一个可信来源进行对照，并说明是否采信及理由', '检查工作单：是否选出两条信息；是否为每条提供至少一个可信来源；是否存在“来源—声明”对照；是否给出结论与理由', '[\"核验工作单（含声明列/来源列/对照结果/结论列）\", \"可信来源目录（政府/机构/权威媒体）\", \"关键词策略卡（地名+事件+日期/机构名+公告）\"]');
INSERT INTO `project_activity` VALUES (8017, 1020, 4, '汇报与迁移：列举类似情况', 10, '主持小型发布会：每组用1分钟汇报“如何核对”；引导归纳通用步骤；布置迁移任务：列举相似场景并说明防范做法', '口头或书面展示核对过程与结论；听取他组意见；在平板上列出至少两个类似情况（如AI生成的健康建议/本地新闻/学校通知）并简述核验思路', '汇总各组要点，投影“通用核验流程图”帮助全班迁移', 'STUDENT', '[6014]', 1, '2026-09-09 19:18:45', '2026-09-09 19:18:45', '小组总结核验方法，并在全班分享；独立列举“类似的AI信息风险情境”至少两种', '依据标准打分：正确识别至少两条需核验信息；提供可信来源并对照；明确采信与否及理由；能列举至少两种类似情境', '[\"汇报提纲模板\", \"通用核验流程图\", \"情境列举提示卡（领域/风险点/应对动作）\"]');
INSERT INTO `project_activity` VALUES (8018, 1022, 1, '智能体功能初探', 8, '演示如何向教学智能体提出一个探究性问题，并展示如何根据智能体的回答进行追问，强调先有猜想再求证的交互逻辑。', '观察教师的演示过程，记录智能体的关键功能和提问方法，思考如何向智能体提出自己的问题。', '提供即时、准确的信息反馈，并展示交互式对话的流程。', 'STUDENT', '[6015]', 1, '2026-09-10 23:05:16', '2026-09-10 23:05:16', '通过观察教师演示，初步了解教学智能体的基本功能与交互方式', '通过课堂提问，检查学生是否理解智能体的基本交互方式和提问原则。', '[\"智能体提问流程图\", \"探究性问题示例清单\"]');
INSERT INTO `project_activity` VALUES (8019, 1022, 2, '独立提问与信息获取', 12, '巡视指导，帮助学生明确探究问题，确保提问具有探究性，并提醒学生完整保存与智能体的对话记录。', '独立使用教学智能体，围绕一个具体的学科问题（如“为什么天空是蓝色的？”）进行提问，并完整记录与智能体的互动过程。', '作为互动伙伴，根据学生提问提供相关信息，并引导学生进行更深层次的追问。', 'STUDENT', '[6015]', 1, '2026-09-10 23:05:16', '2026-09-10 23:05:16', '独立选择一个学科问题，向教学智能体提问，并完整记录对话过程以获取信息', '检查学生提交的对话记录截图，评估其提问的清晰度和探究性，确保符合评价任务要求。', '[\"问题设计模板\", \"对话记录截图操作指引\"]');
INSERT INTO `project_activity` VALUES (8020, 1022, 3, '信息核验与证据整合', 12, '提供可靠的外部信息来源（如教材、权威科普网站），指导学生如何进行信息检索、比对和核验，强调证据意识。', '根据智能体的回答，主动利用至少两个外部可靠来源对信息进行核验，记录核验步骤，并整合信息形成自己的初步解释。', '提供信息核验的对比框架，辅助学生梳理不同来源信息的异同点。', 'STUDENT', '[6015]', 1, '2026-09-10 23:05:16', '2026-09-10 23:05:16', '使用至少两个外部可靠来源，对智能体提供的信息进行核验，并整合形成初步解释', '检查学生的核验记录，评估其信息来源的可靠性和核验过程的严谨性。', '[\"信息核验记录表\", \"权威信息来源推荐清单\"]');
INSERT INTO `project_activity` VALUES (8021, 1022, 4, '报告撰写与反思总结', 8, '指导学生按照评价标准撰写简短报告，强调报告的逻辑结构，并组织学生分享交流，总结与智能体互动的经验。', '整合提问过程、核验步骤和最终解释，撰写并提交一份简短报告，反思与智能体互动的全过程，体现先判断后验证的意识。', '提供报告框架建议，帮助学生梳理报告逻辑，并对学生提交的报告给出初步反馈。', 'STUDENT', '[6015]', 1, '2026-09-10 23:05:16', '2026-09-10 23:05:16', '基于提问过程和核验结果，撰写包含探究过程与最终解释的简短报告，并进行反思', '依据评价标准，对学生提交的包含提问过程、核验步骤及最终解释的简短报告进行综合评价。', '[\"报告撰写模板\", \"反思问题清单\"]');
INSERT INTO `project_activity` VALUES (8022, 1023, 1, '认识智慧驾驶的三大环节', 10, '播放智慧驾驶计算机模拟场景片段，引导学生观察传感、决策、执行三环节的出现顺序与配合，用通俗语言解释基础概念', '观察模拟场景，记录观察到的三个核心环节，尝试标注各环节的大致作用', '提供情境化模拟演示与环节功能提示', 'STUDENT', '[6016]', 1, '2026-09-11 12:05:04', '2026-09-11 12:05:04', '借助计算机模拟场景认识智慧驾驶中的传感、决策与执行核心环节，初步感知三环节协同关系', '抽查学生记录的三环节名称与基础作用描述', '[\"环节观察记录表\", \"智慧驾驶基础术语提示卡\"]');
INSERT INTO `project_activity` VALUES (8023, 1023, 2, '绘制系统协同示意图', 15, '发布绘图任务与评分要点，巡视指导基础较弱的学生梳理环节间关联，适时提供思路提示', '独立绘制包含传感、决策、执行三环节的协同示意图，标注各环节连接逻辑', '提供示意图范例与环节连接参考', 'STUDENT', '[6016]', 1, '2026-09-11 12:05:04', '2026-09-11 12:05:04', '独立梳理传感、决策、执行三环节的逻辑关系与协同路径，画出系统协同示意图', '按标准检查示意图是否包含三环节且协同路径清晰，收取示意图', '[\"三环节逻辑关系模板\", \"示意图绘制步骤提示\"]');
INSERT INTO `project_activity` VALUES (8024, 1023, 3, '多源核验AI分析结果', 10, '提供模拟数据包与信息来源清单，指导学生正确使用数字工具调取信息源，提示核验记录的规范格式', '使用数字工具对AI生成的分析结果进行两轮不同信息源核验，记录核验情况并列出两处需人工检查的内容', '生成模拟数据分析结果，提供信息源调取入口', 'STUDENT', '[6017]', 1, '2026-09-11 12:05:04', '2026-09-11 12:05:04', '使用数字工具分析智慧驾驶模拟数据，调用至少两个不同信息来源核验AI生成的分析结果，列出仍需人工检查的两处内容', '检查核验记录是否含两个不同信息来源，确认人工检查内容清单是否完整', '[\"核验记录模板\", \"信息源使用指南\"]');
INSERT INTO `project_activity` VALUES (8025, 1023, 4, '判断AI决策建议可靠性', 5, '给出典型传感数据场景，引导学生结合数据特征分析AI建议合理性，组织学生简洁表达判断与依据', '根据给定传感数据判断AI决策建议的可靠性，用文字或图表说明判断依据', '输出模拟场景的AI决策建议与数据说明', 'STUDENT', '[6018]', 1, '2026-09-11 12:05:04', '2026-09-11 12:05:04', '基于具体传感数据（如障碍物距离）判断AI输出的驾驶决策建议是否可靠，说明至少一个判断依据', '检查是否给出明确可靠性判断并附至少一个合理依据', '[\"判断依据参考表\", \"数据解读提示卡\"]');
INSERT INTO `project_activity` VALUES (8026, 1024, 1, '采摘机器人结构情境导入与结构认知', 6, '创设采摘作业情境，展示采摘机器人结构示意图，引导学生观察结构部件，并围绕结构与功能提出相关问题。', '观察结构示意图，结合采摘情境识别主要结构部件，初步理解结构组成与功能关系。', '情境创设与结构观察引导', 'STUDENT', '[6019]', 1, '2026-09-12 14:26:49', '2026-09-12 14:26:49', '在采摘机器人作业情境中观察教师提供的结构示意图，识别主要结构部件，建立结构与功能的初步认知。', '判断学生能否在情境中准确识别主要结构部件，建立结构与功能的初步认知。', '[\"采摘机器人结构示意图卡\", \"结构部件与功能对应提示表\", \"观察任务单\"]');
INSERT INTO `project_activity` VALUES (8027, 1024, 2, '小组协作绘制采摘机器人零部件草图', 18, '组织小组分工，提供结构设计要求与画图工具使用指导，巡视指导学生选择工具、规范标注，保障小组协作有序进行。', '以小组为单位在计算机上进行零部件草图绘制，标注关键结构名称与位置，确保绘制结果与结构要求一致。', '工具使用指导与协作过程支持', 'STUDENT', '[6019]', 1, '2026-09-12 14:26:49', '2026-09-12 14:26:49', '小组合作使用计算机画图工具，根据结构要求绘制采摘机器人主要零部件草图，并准确标注关键结构名称与位置。', '检查小组绘制成果是否准确体现主要结构，关键零部件名称与位置标注是否清晰、规范，并判断是否根据结构设计要求选择合适画图工具、操作是否规范有条理。', '[\"结构设计要求与草图模板\", \"计算机画图工具使用指南\", \"关键结构标注规范示例\", \"小组分工与协作任务单\"]');
INSERT INTO `project_activity` VALUES (8028, 1024, 3, '绘制说明、交流与反思', 9, '组织小组交流展示，引导学生在说明中结合绘制依据和结构特点，组织同学互评，并对共性问题进行点拨与反馈。', '小组向同学说明绘制依据和结构特点，听取他人评价，反思并修正草图中的不足。', '交流组织与反思引导', 'STUDENT', '[6019]', 1, '2026-09-12 14:26:49', '2026-09-12 14:26:49', '小组向同学说明绘制依据和采摘机器人结构特点，互评草图并反思绘制过程与问题。', '评价学生说明内容是否准确，结构特点与绘制内容是否对应一致，以及反思与修正是否合理。', '[\"结构特点与绘制依据说明要点提示\", \"小组互评量表\", \"常见绘制问题清单\"]');
INSERT INTO `project_activity` VALUES (8029, 1024, 4, '评价完善与采摘机器人结构设计迁移', 7, '组织学生根据评价意见完善草图，总结结构设计绘制要点，提出迁移任务，指导学生在巩固中提升迁移能力。', '根据评价意见完善草图，总结结构设计绘制方法，并在迁移任务中运用已有经验完成相关结构设计绘制。', '评价完善指导与迁移任务引导', 'STUDENT', '[6019]', 1, '2026-09-12 14:26:49', '2026-09-12 14:26:49', '根据评价意见完善草图，总结结构设计绘制方法，并尝试迁移到其他采摘机器人相关结构设计任务中。', '评估学生完善草图后的成果完整性与准确性，以及能否总结方法并完成迁移任务。', '[\"草图修订标准与修订指引\", \"结构设计绘制方法总结提示\", \"迁移任务设计参考\"]');
INSERT INTO `project_assessment` VALUES (9001, 1001, 6001, '给出一段新的固定Demo AI回答，请学生标出至少两处需要进一步核验的信息，并说明原因。', '[\"标记出的可疑信息\", \"需要核验的理由\"]', '{\"criterion1\": \"能识别需要核验的信息\", \"criterion2\": \"能够说明核验理由\"}', '直接测量学生能否识别需要核验的信息。', 'ACCEPT', 1, 1, '2026-08-25 15:00:35');
INSERT INTO `project_assessment` VALUES (9002, 1001, 6002, '学生使用至少两个固定Demo来源核验AI回答，提交来源、关键证据和最终可信度判断。', '[\"至少两个信息来源\", \"关键证据记录\", \"可信度判断及理由\"]', '{\"criterion1\": \"使用多个来源\", \"criterion2\": \"证据与判断之间存在对应关系\", \"criterion3\": \"能够解释最终判断\"}', '避免只用定义记忆题评价信息核验能力。', 'REVISE', 1, 1, '2026-08-25 15:00:35');
INSERT INTO `project_assessment` VALUES (9003, 1001, 6003, '比较“自己的初步观点—同伴意见—AI建议”，说明最终接受、修改或拒绝哪些内容及其理由。', '[\"初步观点\", \"同伴意见\", \"AI建议\", \"最终决定及理由\"]', '{\"criterion1\": \"能比较不同观点\", \"criterion2\": \"最终决定有证据或理由支撑\"}', '用于评价学生是否保留对最终判断的责任。', 'ACCEPT', 1, 1, '2026-08-25 15:00:35');
INSERT INTO `project_assessment` VALUES (9004, 1010, 6004, '围绕“111”完成一项信息判断与证据说明任务。', '[\"完成的任务记录\", \"所用信息来源或证据\", \"基于证据的判断说明\"]', '[\"目标要求的行为能够被观察\", \"证据与判断具有明确对应关系\", \"能够说明判断或修正理由\"]', '任务直接要求学生展示目标所要求的行为与证据。', NULL, 1, 1, '2026-09-06 12:00:01');
INSERT INTO `project_assessment` VALUES (9005, 1012, 6006, '在教师引导的课堂讨论中，学生口头用自己的话说明“aa”的学习范围，并明确说出至少两个“aa”的关键特征。', '[\"课堂录音或教师记录的学生发言文本，包含对“aa”范围的界定与两个关键特征的表述。\"]', '[\"能清晰界定“aa”的学习范围。\", \"能准确说出至少两个“aa”的关键特征。\", \"语言表达为学生自己的话，而非复述教师原句。\"]', '主题“aa”模糊且学生零基础，采用探究式讨论可直接观察学生是否建立基本共识，并为后续概念建构奠定语言基础。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9006, 1012, 6009, '观察教师提供的3个明确的“aa”示例后，学生独立列出至少2条共同特征，并用自己的话给出一个简单定义。', '[\"学生书面或口头回答：列出的共同特征与简单定义。\"]', '[\"从给定3例中正确提取至少2条共同特征。\", \"给出的简单定义与所列特征一致、无矛盾。\", \"使用学生自己的话表达，避免机械背诵。\"]', '有限且清晰的实例有助于二年级学生形成概念框架；通过可观察的特征列举与定义，直接评估其归纳能力。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9007, 1012, 6007, '在教师提供的结构化示例集中，学生判断并记录属于“aa”和不属于“aa”的实例各至少两个，并写出简短理由。', '[\"学生完成的分类表或答题纸，含每个判断及理由。\"]', '[\"正确识别属于“aa”的实例≥2。\", \"正确识别不属于“aa”的实例≥2。\", \"每条判断附简短理由，逻辑与“aa”特征相关。\"]', '正反例对比是澄清模糊概念的有效方式；结构化任务便于在大班额下快速收集每位学生的判断证据。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9008, 1012, 6010, '在教师提示下，学生说出或写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状等）。', '[\"学生口头清单或书写词汇列表。\"]', '[\"提供≥3个与“aa”相关的描述性基本词汇。\", \"词汇类别可包括名称/颜色/形状等，并与“aa”相符。\", \"表达清晰，能在需要时用中文解释词义。\"]', '零基础情况下，聚焦核心词汇可统一表达基础；口头或书面产出均为可直接观察的证据。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9009, 1012, 6008, '学生用平板绘制或口头描述创作一个新例子，使其符合“aa”的特征，并向同伴解释其关键属性。', '[\"平板绘图文件或口头描述录音。\", \"同伴记录的互动反馈便签/表格。\"]', '[\"创作的例子与“aa”特征一致。\", \"解释至少包含两条关键属性。\", \"表达清楚，能让同伴理解其例子为何属于“aa”。\"]', '大班额条件下，利用平板进行个别化表达提升参与度；创作与解释活动直接检验学生对“aa”的创造性理解。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9010, 1012, 6012, '当同伴展示作品时，学生使用指定句型“我注意到……，因为……”向同伴提出一条具体反馈。', '[\"同伴互评记录表，含该句型的完整使用。\"]', '[\"完整使用句型“我注意到……，因为……”。\", \"反馈内容指向作品的具体细节（如特征/颜色/形状/结构）。\", \"理由与“aa”特征或作品表现相关。\"]', '结构化句型支持二年级学生在缺乏示例和表达机会受限的情况下，进行有效同伴反馈，提高课堂互动质量。', NULL, 1, 1, '2026-09-07 17:31:18');
INSERT INTO `project_assessment` VALUES (9011, 1012, 6006, '在教师引导的课堂讨论后，每位学生用自己的话写下至少两个“aa”的关键特征，并说明为什么这些特征属于“aa”。', '[\"学生书面写出的两个关键特征\", \"对每个特征归属理由的简短解释\"]', '[\"至少写出两个与“aa”相关的关键特征\", \"用自己话表述，非照搬教师原句\", \"为每个特征提供一条简要理由\"]', '通过即时书面输出，直接检验学生是否从讨论中提炼出“aa”的范围与核心特征，符合建立基本共识的认知起点。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9012, 1012, 6009, '观察教师展示的3个明确“aa”示例，学生独立列出至少2条这些示例的共同特征，并用一句话给出“aa”的简单定义。', '[\"列出的共同特征清单\", \"一句简单定义\"]', '[\"至少列出2条跨示例的共同特征\", \"定义中包含“aa”且与所列特征一致\", \"语言简洁、二年级可理解\"]', '以有限清晰实例为基础，考察学生归纳共性并形成初步概念框架的能力，降低因主题模糊导致的理解偏差。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9013, 1012, 6007, '在教师提供的结构化示例集中，学生识别并记录至少两个属于“aa”的实例和至少两个不属于“aa”的实例，并为每个判断写出一条简单理由。', '[\"正例清单（≥2）\", \"反例清单（≥2）\", \"每条判断的简短理由\"]', '[\"正确分类：正例确实符合“aa”特征，反例不符合\", \"每条理由指向具体特征或标准\", \"书写清楚、逻辑简单连贯\"]', '通过正反例对比，评价学生初步判断与分类能力，解决因缺少清晰边界导致的混淆，巩固对“aa”的理解。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9014, 1012, 6010, '在教师引导下，学生说出或写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状等），并标注每个词汇对应的特征类别。', '[\"至少3个描述性词汇列表\", \"每个词汇对应的特征类别标注（如“颜色”“形状”）\"]', '[\"数量不少于3个\", \"词汇与“aa”的主要特征相关\", \"能正确标注每个词汇所属的特征类别\"]', '聚焦核心词汇产出，直接衡量学生是否能建立共同描述语言，为后续表达与评估奠定基础。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9015, 1012, 6008, '学生利用平板绘制一个新例子，使其符合“aa”的关键属性，并向同伴口头解释该例子为何属于“aa”（至少说明两条关键属性）。', '[\"平板绘制作品\", \"口头解释录音要点摘录\", \"同伴确认记录\"]', '[\"新例子明显体现“aa”的关键属性\", \"口头解释包含至少两条关键属性\", \"解释与图画一致，逻辑清晰\"]', '在大班额条件下，通过个别化创作与口头说明，确保每位学生的创造性理解被可视化并得到检验。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9016, 1012, 6011, '每位学生独立使用平板简易绘图工具完成一幅草图，呈现“aa”的主要特征；在全班展示时，口头说明至少1条所画特征与“aa”的关系。', '[\"完成的草图文件名或截图\", \"展示时口头说明的要点记录\"]', '[\"草图包含“aa”主要特征\", \"口头说明至少1条特征及其与“aa”的联系\", \"表达清晰、时间控制在规定范围内\"]', '在时间受限与大班额情境下，个体产出与简短分享便于教师快速评价每生的理解程度，保证全员参与。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9017, 1012, 6012, '当同伴展示作品时，学生运用指定句型“我注意到……，因为……”对其作品提出一条具体反馈，指出一个可见特征及相应的依据。', '[\"使用指定句型的完整句子\", \"被指出的具体特征与依据\"]', '[\"完整使用给定句型，结构正确\", \"反馈指向作品中的具体可见特征\", \"依据与特征之间有合理关联\"]', '通过结构化句型支持二年级学生进行有效同伴反馈，提升互动质量，并使评价过程可观察、可量化。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9018, 1012, 6006, '在教师引导的全班讨论中，围绕话题“aa”共同确定本节课的学习范围，并用自己的话列出至少两个“aa”的关键特征。', '[\"学生口头发言记录或姓名牌展示的特征清单\", \"教师记录的学生定义要点\"]', '[\"明确写出至少两条关键特征\", \"使用学生自己的语言而非照搬教师原话\", \"特征与课堂共同确定的学习范围一致\"]', '在主题模糊且零基础的情况下，通过讨论澄清范围并让学生用自己的话提炼特征，可直接观察其是否建立基本共识，避免仅记忆定义。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9019, 1012, 6009, '观察教师呈现的3个与“aa”相关的明确示例，独立列出至少2条这些示例的共同特征，并用一句简单的话给出“aa”的操作性定义。', '[\"学生写下的特征列表和一句话定义\", \"教师用红笔标注的符合/不符合特征的依据\"]', '[\"从给定3个示例中提取至少2条共同特征\", \"一句话定义能涵盖这些共同特征\", \"表述清晰、二年级可读（简短词汇与句式）\"]', '提供有限且清晰的实例有助于二年级学生建立概念框架；直接基于示例提取特征并形成简单定义，可观察其归纳能力而非记忆。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9020, 1012, 6007, '在教师提供的结构化表格中，将给定项目分成“属于aa”和“不属于aa”两类，每类至少包含两个项目，并为每个选择写一句简单理由。', '[\"分类完成的工作表照片或扫描件\", \"每项旁边的一句理由（可用口述由教师代记）\"]', '[\"“属于aa”至少2项，“不属于aa”至少2项\", \"每项都附有一句理由\", \"至少一条理由涉及核心特征或规则的运用\"]', '正例与反例对比能训练初步判断与分类能力；要求写理由可观察其是否理解边界条件，而不仅是凭直觉。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9021, 1012, 6010, '在教师给出的提示下，说出或写出至少3个用于描述“aa”的基本词汇（例如名称、颜色、形状等），并与同学交流这些词分别描述了什么。', '[\"词汇清单（手写或电子输入）\", \"同伴互评的小贴纸或简易核对表\"]', '[\"至少写出/说出3个相关词汇\", \"每个词汇能指向“aa”的某个可观察属性\", \"拼写或发音在二年级可接受范围内\"]', '在零基础与话题未界定的情况下，聚焦核心词汇可快速建立共同语言基础；通过说或写进行表达，可直接测量其词汇掌握而非辨认。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9022, 1012, 6008, '用平板绘制一幅图或用口头描述创作一个新的“aa”例子，并向同伴解释它为什么符合“aa”的关键属性。', '[\"平板绘图文件或口头描述录音\", \"同伴反馈便签：记录其解释中的关键点\"]', '[\"新作品/描述明显体现至少一条“aa”的关键属性\", \"解释中能点出“因为它具有……特征”这类理由\", \"表达清晰，能让同伴听懂/看懂\"]', '在大班额条件下，利用平板支持个别化表达，提高参与度；创作并解释能巩固对概念的理解，评估其创造性应用。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9023, 1012, 6012, '当同伴展示其创作的“aa”例子时，使用指定句型“我注意到……，因为……”提出一条具体反馈，并说明理由。', '[\"录音或教师观察记录：完整使用句型的一次反馈\", \"同伴确认收到反馈的示意（如点头或勾选）\"]', '[\"完整使用“我注意到……，因为……”句型\", \"反馈内容针对同伴作品的具体特征\", \"理由与特征相吻合，逻辑简单清晰\"]', '缺乏清晰示例及表达机会受限时，结构化句型能降低表达难度；观察其在真实互动中使用句型，可直接测量同伴反馈能力。', NULL, 1, 1, '2026-09-07 17:31:40');
INSERT INTO `project_assessment` VALUES (9024, 1012, 6006, '课堂讨论结束后，学生独立用文字或图画形式写下至少两个关于“aa”的关键特征。', '[\"学生的文字记录/图画\"]', '[\"能列出至少两个与课堂共识一致的“aa”关键特征\"]', '通过独立输出检验学生是否参与课堂讨论并形成对“aa”学习范围的共同认知，落实目标中“明确话题范围”的要求。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9025, 1012, 6009, '教师提供3个“aa”相关明确示例后，学生列出至少两条共同特征并给出一个简单定义。', '[\"学生的分析记录/书面定义\"]', '[\"能准确识别至少两个示例的共同特征\", \"定义符合“aa”基本内涵\"]', '通过实例分析检验学生是否能从有限清晰实例中提取共同特征，验证目标中“建立基本概念框架”的达成度。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9026, 1012, 6007, '教师提供5个实例（含“aa”与非“aa”各至少2个），学生分类并写出简单理由。', '[\"学生的分类结果及理由记录\"]', '[\"能正确区分至少2个“aa”实例和2个非“aa”实例\", \"理由基于“aa”关键特征\"]', '通过正反例分类检验学生初步判断与分类能力，解决因缺少清晰示例导致的理解困难，匹配目标要求。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9027, 1012, 6010, '学生口头或书面说出/写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状）。', '[\"学生的词汇列表/口头录音\"]', '[\"能列出至少3个符合“aa”核心特征的描述性词汇\"]', '聚焦核心词汇的输出，检验学生是否掌握“aa”的基础表达，为后续活动奠定共同语言基础。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9028, 1012, 6008, '学生利用平板绘制或口头描述一个符合“aa”特征的新例子，并向同伴解释其关键属性。', '[\"学生的作品/口头解释录音\"]', '[\"作品/描述符合“aa”至少一个关键特征\", \"能口头说明1条关键属性\"]', '通过创造性产出与解释，检验学生对“aa”概念的创造性理解，同时在大班额中保证个体参与。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9029, 1012, 6011, '学生独立用平板绘制一幅包含“aa”主要特征的草图，全班展示时口头说明1条所画特征。', '[\"学生的草图/口头说明录音\"]', '[\"草图包含“aa”至少一个主要特征\", \"能准确说出1条所画特征\"]', '通过个体草图与简短分享，检验每位学生对“aa”主要特征的掌握，便于教师快速评价理解程度。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9030, 1012, 6012, '当同伴展示“aa”作品时，学生运用给定句型“我注意到……，因为……”提出一条具体反馈。', '[\"学生的反馈语句记录/录音\"]', '[\"使用指定句型\", \"反馈内容具体指向同伴作品的特征\"]', '通过结构化句型的使用，检验学生是否能进行有效同伴反馈，提升课堂互动质量，匹配目标要求。', NULL, 0, 1, '2026-09-07 17:32:02');
INSERT INTO `project_assessment` VALUES (9031, 1012, 6006, '教师在白板上写下话题“aa”，学生以小组为单位进行讨论，每个小组向全班分享一个他们认为属于“aa”的关键特征，并说明理由。', '[\"课堂讨论录音记录下的学生发言片段。\", \"学生提交的关于“aa”关键特征的文字或图画定义。\"]', '[\"能够提出至少两个与“aa”相关的、合理的特征。\", \"能用自己的话清晰地解释为什么这些是“aa”的特征。\", \"理由是基于对“aa”范围的共同理解，而非个人臆测。\"]', '此评估直接测量学生参与课堂讨论并用自己的话定义“aa”特征的能力，这与目标6006的要求一致，通过协作澄清学习范围。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9032, 1012, 6009, '教师展示3个明确属于“aa”的示例（如图片或实物）。学生独立完成一份工作表，列出他们观察到的这3个示例的共同点，并根据这些共同点给出一个简单的定义。', '[\"学生填写的工作表，其中列出了至少2条共同特征。\", \"学生给出的简单定义。\"]', '[\"能够准确地从3个示例中识别出至少2条共同特征。\", \"给出的简单定义能够概括所观察到的共同特征。\", \"定义使用自己的语言，而不是简单地复述教师的讲解。\"]', '该任务要求学生基于给定的具体实例进行分析和归纳，直接评估其建立“aa”概念框架的能力，符合目标6009的要求。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9033, 1012, 6007, '教师提供一个包含多个项目的列表，其中一些属于“aa”，另一些则不属于。学生需要将它们分类，并对每一个分类选择至少一项说明理由。', '[\"学生的分类结果，其中至少有2个“是”的例子和2个“否”的例子。\", \"学生为每个例子提供的简短理由。\"]', '[\"能够正确识别至少2个“aa”的实例和2个非“aa”的实例。\", \"提供的理由是基于项目是否符合“aa”的特征，逻辑清晰。\", \"理由表述清楚，即使是简单的词语也能表达判断依据。\"]', '通过正反例对比来判断和分类，可以直接检验学生对“aa”概念的理解深度，训练其初步的判断能力，支持目标6007。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9034, 1012, 6010, '教师口头描述或展示“aa”的一个具体例子，然后提问：“我们可以用哪些词来描述它？”学生轮流回答，说出描述“aa”的基本词汇。', '[\"教师记录的学生口述词汇列表。\", \"学生在单词墙上指出或圈出的相应词汇。\"]', '[\"能够说出至少3个用于描述“aa”的基本词汇。\", \"所提词汇与“aa”相关且具有描述性（如颜色、形状、名称等）。\"]', '这个形成性评估直接衡量学生是否能聚焦于核心词汇，为他们后续的表达和评估建立共同的语言基础，这正是目标6010的核心。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9035, 1012, 6008, '学生利用平板绘画工具创作一个新的“aa”的例子，完成后，录制一段简短的音频，向同伴解释他/她的作品为什么是一个“aa”的例子。', '[\"学生在平板上创作的“aa”作品。\", \"学生解释其作品关键属性的音频文件。\"]', '[\"创作的例子在视觉上符合“aa”的主要特征。\", \"口头解释能够阐明至少一个关键属性。\", \"解释清晰，能让听众理解其创作思路。\"]', '此任务让学生创造性地应用他们对“aa”的理解，并通过个人化的表达方式（绘画+口头解释）来巩固概念，有效评估目标6008。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9036, 1012, 6012, '当一名同学展示其为“aa”创作的画作时，其他学生需要在练习本上写下一句反馈，必须使用句型“我注意到……，因为……”。', '[\"学生在练习本上写下的完整反馈句子。\", \"学生口头向同伴反馈时的录音。\"]', '[\"反馈必须是一个完整的句子，并严格遵循“我注意到……，因为……”的句型。\", \"“我注意到”部分是对同伴作品的具体观察。\", \"“因为”部分提供了支持该观察的理由或证据。\"]', '通过结构化的句型，评估学生是否能够为同伴提供具体的、有建设性的反馈，从而提升课堂互动质量，直接对应目标6012。', NULL, 0, 1, '2026-09-07 17:32:30');
INSERT INTO `project_assessment` VALUES (9037, 1013, 6013, '在计算机环境中完成一次“AI是什么”的探究：(1)提出2个可检验的猜想（例如“AI能/不能做什么”）；(2)使用教师提供的资源或课堂允许的工具收集至少2条证据（如截图、文字摘录或观察记录）；(3)用一句话给出自己的临时结论；(4)说明如果证据发生变化，结论会怎样调整。', '[\"学生提出的2个猜想文本\", \"收集到的2条证据（截图/摘录/观察记录）\", \"一句临时结论\", \"对结论可能变化的简短说明\"]', '[\"猜想明确且可被证据检验\", \"证据来源可追溯并与猜想相关\", \"结论与所给证据一致或能解释不一致\", \"能指出证据变化对结论的影响\"]', '采用探究式评价而非记忆题：让学生在设备环境下围绕核心问题自主生成猜想、寻找证据并形成结论，既符合课堂条件，也避免AI直接给出答案，从而保护学生的判断与推理过程。', 'REVISE', 1, 2, '2026-09-08 14:58:49');
INSERT INTO `project_assessment` VALUES (9038, 1020, 6014, '给定一条由AI生成的中文资讯（含2—3个事实要点），学生需：1) 用“是/否/不确定”标注每条信息是否需要外部核验；2) 任选其中两条，分别查找至少一个可信来源进行核对；3) 以口头或书面形式说明是否采信该信息，并给出理由。3)学生需要列举类似情况', '[\"学生完成的“是/否/不确定”标注记录\", \"用于核对的两则来源链接或截图\", \"学生口头或书面的判定与理由（录音/文字）\"]', '[\"正确识别出至少两条需要核验的信息\", \"为所选信息提供至少一个可信来源并进行对照\", \"明确表达是否采信，并基于证据给出合理解释\"]', '任务要求学生主动辨别AI生成内容的真伪，并通过多源核验作出判断，直接测量目标“掌握AI的使用，能够辨别AI真伪信息，合理使用AI”中的可观察行为，符合同伴互动与共同产出的教学策略。', 'REVISE', 1, 2, '2026-09-09 19:06:28');
INSERT INTO `project_assessment` VALUES (9039, 1022, 6015, '学生需独立使用教学智能体，针对一个具体的学科问题（如“为什么天空是蓝色的？”）进行提问，并根据智能体的回答，结合至少两个外部可靠来源（如教材、权威科普网站）对信息进行核验与整合，最终提交一份包含提问过程、核验步骤及最终解释的简短报告。', '[\"提交的包含提问过程、核验步骤及最终解释的简短报告\", \"与智能体互动的原始对话记录截图\"]', '[\"能够准确、清晰地向智能体提出探究性问题，引导智能体提供相关信息\", \"能够主动使用至少两个外部来源对智能体提供的信息进行核验，并记录核验过程\", \"能够基于核验结果，对智能体的回答进行修正或补充，形成逻辑清晰的最终解释\", \"在与智能体互动的全过程中，体现出先有初步判断、后有验证修正的交互意识\"]', '该任务直接测量学生“掌握智能体的使用”的可观察行为，要求学生在真实情境中与智能体互动，并结合AI素养中的信息核验与交互策略，完成从提问、核验到整合的全过程，避免仅停留在概念记忆层面，直接支撑目标达成。', NULL, 1, 1, '2026-09-10 23:03:55');
INSERT INTO `project_assessment` VALUES (9040, 1023, 6016, '在40分钟内，借助计算机模拟智慧驾驶场景，独立梳理传感、决策与执行三个核心环节，画出系统协同示意图。', '[\"系统协同示意图\"]', '[\"独立绘制出包含传感、决策、执行三环节的示意图\", \"三环节的逻辑关系与协同路径清晰可辨\"]', '直接测量目标要求的可视化产出，评估学生将抽象的系统协同原理转化为可观察产出的能力。', NULL, 1, 1, '2026-09-11 12:04:27');
INSERT INTO `project_assessment` VALUES (9041, 1023, 6017, '使用数字工具分析智慧驾驶的模拟数据，至少调用两个不同信息来源核验AI生成的分析结果，并列出仍需人工检查的两处内容。', '[\"包含两个不同信息来源的核验记录\", \"仍需人工检查的两处内容清单\"]', '[\"实际使用了至少两个不同信息来源进行核验\", \"准确列出两处需要人工检查的内容\"]', '直接测量目标要求的信息核验实践行为，评估学生使用多源核验及识别AI局限的能力。', NULL, 1, 1, '2026-09-11 12:04:27');
INSERT INTO `project_assessment` VALUES (9042, 1023, 6018, '在模拟智慧驾驶场景中，基于具体的传感数据（如障碍物距离）判断AI输出的驾驶决策建议是否可靠，并用文字或图表说明至少一个判断依据。', '[\"对AI决策建议可靠性的判断结论\", \"至少一个判断依据的说明\"]', '[\"针对给定的传感数据给出明确的可靠性判断\", \"至少提供一个合理的判断依据\"]', '直接测量目标要求的基于证据进行判断的行为，评估学生关联传感数据与AI决策输出的能力。', NULL, 1, 1, '2026-09-11 12:04:27');
INSERT INTO `project_assessment` VALUES (9043, 1024, 6019, '在教师提供的采摘机器人结构示意图基础上，小组合作使用计算机画图工具，根据给定结构要求绘制采摘机器人零部件草图，并在图纸旁标注关键结构名称与位置，最后向同学说明绘制依据和结构特点。', '[\"学生在绘制过程中提交的草图与标注完整，能够清晰呈现采摘机器人主要结构特征。\", \"学生在小组说明时准确陈述结构组成、关键结构与绘制依据，且说明内容与绘图结果一致。\"]', '[\"绘制成果能正确体现采摘机器人主要结构，关键零部件名称与位置标注准确、清晰。\", \"能根据结构设计要求选择合适工具完成绘制，操作规范、有条理。\", \"能结合观察与已有计算机操作经验，解释绘制内容与采摘机器人实际结构的关系。\"]', '该评价任务结合5年级学生已掌握计算机基本操作、以情境体验和任务实践组织学习，直接观察学生在采摘机器人结构设计与绘制中的可操作行为，符合目标要求，并支持学生在体验与反思中掌握结构设计与绘制方法。', NULL, 1, 1, '2026-09-12 14:25:10');
INSERT INTO `project_objective` VALUES (6001, 1001, '学生能够识别生成式AI回答中需要进一步核验的信息，并说明为什么需要核验。', 1, '[2001, 2002]', '[3001, 3002]', '与信息真实性判断和AI能力边界相关。', 'AI', 'ACCEPT', 1, 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35');
INSERT INTO `project_objective` VALUES (6002, 1001, '学生能够使用至少两个信息来源核验AI生成内容，并依据证据形成可信度判断。', 2, '[2001]', '[3002]', '目标要求学生真正执行信息核验，而非只记忆AI概念。', 'AI', 'REVISE', 1, 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35');
INSERT INTO `project_objective` VALUES (6003, 1001, '学生能够比较自己、同伴与AI的观点，并解释最终接受、修改或拒绝AI建议的理由。', 3, '[2002]', '[3003]', '强调学生保留最终判断责任。', 'AI', 'ACCEPT', 1, 1, '2026-08-25 15:00:35', '2026-08-25 15:00:35');
INSERT INTO `project_objective` VALUES (6004, 1010, '111', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-06 11:59:49', '2026-09-06 11:59:57');
INSERT INTO `project_objective` VALUES (6005, 1011, '123', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-06 17:02:15', '2026-09-06 17:02:17');
INSERT INTO `project_objective` VALUES (6006, 1012, '通过课堂讨论与教师引导，明确话题“aa”的学习范围，并用自己的话定义至少两个“aa”的关键特征。', 1, '[]', '[]', '在主题模糊且学生零基础的情况下，首先帮助学生共同澄清学习对象，建立对“aa”的基本共识，为后续活动奠定语言与认知基础。', 'AI', 'ACCEPT', 1, 1, '2026-09-07 17:23:20', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6007, 1012, '在教师提供的结构化示例中，识别并记录属于“aa”和不属于“aa”的实例各至少两个，用简单理由进行说明。', 2, '[]', '[]', '通过正例与反例对比，训练学生初步判断与分类能力，解决因缺少清晰示例而导致的理解困难。', 'AI', NULL, 1, 1, '2026-09-07 17:23:20', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6008, 1012, '利用平板绘制或口头描述，创作一个符合“aa”特征的新例子，并向同伴解释其关键属性。', 3, '[]', '[]', '在大班额条件下，借助平板进行个别表达，提高每位学生的参与度，同时巩固对“aa”概念的创造性理解。', 'AI', NULL, 1, 1, '2026-09-07 17:23:20', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6009, 1012, '通过观察教师提供的3个与“aa”相关的明确示例，学生能够列出至少2条共同特征，并用自己的话给出一个简单定义。', 1, '[]', '[]', '主题“aa”过于模糊，先提供有限且清晰的实例有助于二年级学生建立基本概念框架，降低因不明确导致的注意力分散。', 'AI', NULL, 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6010, 1012, '在教师引导下，学生能够说出或写出至少3个用于描述“aa”的基本词汇（如名称、颜色、形状）。', 2, '[]', '[]', '零基础且话题未界定，聚焦核心词汇可为后续表达与评估奠定共同语言基础。', 'AI', NULL, 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6011, 1012, '使用平板中的简易绘图工具，每位学生独立完成一幅包含“aa”主要特征的草图，并在全班展示时口头说明1条所画特征。', 3, '[]', '[]', '在大班额和时间受限条件下，个体产出与简短分享能保证每生参与并便于教师快速评价理解程度。', 'AI', 'ACCEPT', 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:49');
INSERT INTO `project_objective` VALUES (6012, 1012, '当同伴展示作品时，学生能够运用给定句型“我注意到……，因为……”提出一条具体反馈。', 4, '[]', '[]', '缺乏清晰示例及表达机会受限，结构化句型支持二年级学生进行有效同伴反馈，提升课堂互动质量。', 'AI', NULL, 1, 1, '2026-09-07 17:23:28', '2026-09-07 17:30:01');
INSERT INTO `project_objective` VALUES (6013, 1013, '暂无', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-08 14:53:23', '2026-09-08 14:53:24');
INSERT INTO `project_objective` VALUES (6014, 1020, '掌握AI的使用，能够辨别AI真伪信息，合理使用AI', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-09 19:04:00', '2026-09-09 19:04:03');
INSERT INTO `project_objective` VALUES (6015, 1022, '掌握智能体的使用', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-10 23:02:05', '2026-09-10 23:02:06');
INSERT INTO `project_objective` VALUES (6016, 1023, '在40分钟内，借助计算机模拟场景梳理智慧驾驶的传感、决策与执行三个核心环节，独立画出系统协同示意图', 1, '[2002]', '[]', '针对学生对智慧驾驶多系统协同原理理解困难及课堂时间有限的约束，通过可视化示意图将抽象逻辑转化为可观察的产出', 'AI', 'ACCEPT', 1, 1, '2026-09-11 12:01:41', '2026-09-11 12:01:56');
INSERT INTO `project_objective` VALUES (6017, 1023, '在使用数字工具分析智慧驾驶的模拟数据时，至少使用两个不同信息来源核验AI生成结果，并列出仍需人工检查的两处内容', 2, '[2001, 2002]', '[3002, 3003]', '基于学生基础较弱且需依赖计算机设备的约束，结合数字工具使用与信息核验能力的培养要求', 'AI', 'ACCEPT', 1, 1, '2026-09-11 12:01:41', '2026-09-11 12:01:56');
INSERT INTO `project_objective` VALUES (6018, 1023, '在模拟智慧驾驶场景中，针对具体传感数据（如障碍物距离），判断AI输出的决策建议是否可靠，并说明至少一个判断依据', 3, '[2001]', '[3001, 3002]', '针对学生难以关联智能决策算法与传感数据、难以提取关键信息的难点，结合证据判断与AI认知素养进行训练', 'AI', 'ACCEPT', 1, 1, '2026-09-11 12:01:41', '2026-09-11 12:01:56');
INSERT INTO `project_objective` VALUES (6019, 1024, '掌握采摘机器人的结构设计和绘制', 1, '[]', '[]', NULL, 'TEACHER', 'ACCEPT', 1, 1, '2026-09-12 14:19:20', '2026-09-12 14:19:25');
INSERT INTO `project_pedagogy` VALUES (7001, 1001, 4001, 4005, '以探究式学习组织信息核验过程，以协作学习支持不同证据和判断的比较。', '[6001, 6002, 6003]', '需避免学生在形成初步判断前直接复制AI答案。', '{\"note\": \"DEMO备选：问题式学习 + 协作学习\", \"primaryMethodId\": 4003, \"secondaryMethodId\": 4005}', 'ACCEPT', 1, 1, '2026-08-25 15:00:35', NULL, NULL, NULL);
INSERT INTO `project_pedagogy` VALUES (7002, 1010, 4001, NULL, '围绕问题提出猜想、收集证据、比较解释并形成结论。', '[6004]', NULL, '{\"recommended\": {\"name\": \"证据驱动的问题探究\", \"methodId\": 4001, \"rationale\": \"围绕真实信息判断任务组织学生搜集、比较并解释证据，支持已确认目标。\", \"components\": [\"真实问题情境\", \"小组协作\", \"多来源核验\", \"证据比较\", \"反思修订\"]}, \"alternatives\": [{\"name\": \"项目式学习\", \"methodId\": 4002, \"rationale\": \"围绕真实项目产出组织较长周期的学习活动。\", \"components\": [\"问题任务\", \"同伴讨论\", \"反思总结\"]}, {\"name\": \"问题式学习\", \"methodId\": 4003, \"rationale\": \"以复杂问题作为知识学习和问题解决的组织核心。\", \"components\": [\"问题任务\", \"同伴讨论\", \"反思总结\"]}]}', 'ACCEPT', 1, 2, '2026-09-06 11:59:57', NULL, NULL, 'AI');
INSERT INTO `project_pedagogy` VALUES (7003, 1012, NULL, NULL, '针对主题“aa”模糊且学生零基础的情境，采用探究式学习能有效引导学生通过提出问题、观察示例、比较解释来共同构建对“aa”的基本共识和定义，符合目标中澄清概念、识别特征和分类判断的需求。', '[6006, 6009, 6007, 6010, 6008, 6011, 6012]', NULL, '{\"recommended\": {\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"针对主题“aa”模糊且学生零基础的情境，采用探究式学习能有效引导学生通过提出问题、观察示例、比较解释来共同构建对“aa”的基本共识和定义，符合目标中澄清概念、识别特征和分类判断的需求。\", \"components\": [\"提出关于“aa”的核心问题以激发思考\", \"提供3个明确正例与2个反例作为探究证据\", \"小组讨论并比较实例间的共同特征与差异\", \"归纳“aa”的关键属性并形成初步定义\"]}, \"alternatives\": [{\"name\": \"协作学习\", \"methodId\": 4005, \"rationale\": \"在大班额（42人）条件下，利用协作学习促进同伴互动，可高效实现目标中的课堂讨论、共同产出词汇表及结构化反馈练习，确保每位学生的参与度。\", \"components\": [\"个人独立构思“aa”的特征或例子\", \"小组内分享观点并进行证据比较\", \"协商整合出小组的“aa”定义或词汇列表\", \"运用给定句型进行同伴作品反馈\"]}]}', NULL, 0, 3, '2026-09-07 17:30:23', '暂无', '111', 'TEACHER');
INSERT INTO `project_pedagogy` VALUES (7004, 1013, 4001, NULL, '三年级学生首次接触“认识AI”主题，探究式学习允许学生在计算机环境下围绕“AI是什么”这一核心问题自主提出猜想、收集证据并形成结论，既契合设备条件，又避免AI过早提供完整答案，保护学生判断过程。', '[6013]', NULL, '{\"recommended\": {\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"三年级学生首次接触“认识AI”主题，探究式学习允许学生在计算机环境下围绕“AI是什么”这一核心问题自主提出猜想、收集证据并形成结论，既契合设备条件，又避免AI过早提供完整答案，保护学生判断过程。\", \"components\": [\"提出问题：AI能做什么、如何判断机器是否智能？\", \"初步判断：学生写下自己对AI能力的猜想\", \"搜集证据：使用给定示例或在线演示观察AI行为\", \"比较解释：小组讨论观察到的现象与最初猜想的差异\", \"形成结论：全班汇总对AI基本特征的理解\"]}, \"alternatives\": [{\"name\": \"情境体验式学习\", \"methodId\": 4004, \"rationale\": \"通过情境进入和即时体验让学生直观感受AI应用，适合缺乏先备知识的三年级学生，并能在后续反思环节巩固概念。\", \"components\": [\"情境进入：教师展示一段AI语音助手日常对话视频\", \"体验：学生分组与简易聊天机器人交互并记录反应\", \"观察：比较人机对话差异，关注语气、准确度等\", \"解释：教师引导学生归纳AI工作方式的简化模型\", \"应用：设计一个“如果我有AI助手”的小场景\"]}, {\"name\": \"协作学习\", \"methodId\": 4005, \"rationale\": \"利用同伴互动促进观点比较，帮助三年级学生在探索AI时相互启发，防止个别学生或AI工具主导讨论。\", \"components\": [\"个人思考：每名学生列出自己知道或猜测的AI例子\", \"小组分享：轮流介绍并合并重复项\", \"证据比较：小组决定哪些例子最可能属于AI应用\", \"协商：就争议点（如游戏NPC是否算AI）达成组内共识\", \"共同产出：制作“我们的AI列表”海报\"]}]}', 'ACCEPT', 1, 1, '2026-09-08 14:54:31', NULL, NULL, 'AI');
INSERT INTO `project_pedagogy` VALUES (7005, 1020, 4005, NULL, '通过同伴互动、观点比较和共同产出促进学习。', '[6014]', NULL, '{\"recommended\": {\"name\": \"项目式学习\", \"methodId\": 4002, \"rationale\": \"围绕真实任务组织较长周期活动，便于在持续产出中练习“辨别AI真伪信息、合理使用AI”，并通过设计—制作—测试—展示环节强化责任与伦理反思。\", \"components\": [\"真实问题 → 方案设计 → 制作 → 测试 → 展示\"]}, \"alternatives\": [{\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"通过提出问题—收集证据—比较解释—形成结论的链条，训练学生对AI生成内容进行证据核查与判断，直接支持“辨别真伪信息”。\", \"components\": [\"提出问题 → 初步判断 → 搜集证据 → 比较解释 → 形成结论\"]}, {\"name\": \"协作学习\", \"methodId\": 4005, \"rationale\": \"以同伴分享与协商共同产出，促进对AI信息的多角度比对与集体把关，帮助形成“合理使用AI”的规范与共识。\", \"components\": [\"个人思考 → 小组分享 → 证据比较 → 协商 → 共同产出\"]}]}', 'ACCEPT', 1, 2, '2026-09-09 19:04:35', NULL, NULL, 'AI');
INSERT INTO `project_pedagogy` VALUES (7006, 1022, 4001, NULL, '围绕智能体的使用提出探究问题，引导学生在与智能体互动中经历猜想、证据收集与解释，直接支撑目标“掌握智能体的使用”，并避免AI直接给出结论。', '[6015]', NULL, '{\"recommended\": {\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"围绕智能体的使用提出探究问题，引导学生在与智能体互动中经历猜想、证据收集与解释，直接支撑目标“掌握智能体的使用”，并避免AI直接给出结论。\", \"components\": [\"提出问题：明确智能体要解决的学习任务\", \"初步判断：学生独立构思使用智能体的思路\", \"搜集证据：在智能体支持下检索与验证信息\", \"比较解释：对比不同智能体输出并说明理由\", \"形成结论：总结智能体使用策略与适用边界\"]}, \"alternatives\": [{\"name\": \"项目式学习\", \"methodId\": 4002, \"rationale\": \"以真实项目产出为载体，在较长周期内持续应用智能体，帮助学生在完成项目的过程中掌握智能体的使用。\", \"components\": [\"真实问题：确定需要借助智能体解决的项目主题\", \"方案设计：规划智能体在项目中的角色与流程\", \"制作：利用智能体生成与迭代项目成果\", \"测试：评估智能体输出的有效性与可靠性\", \"展示：呈现项目成果并总结智能体使用经验\"]}, {\"name\": \"问题式学习\", \"methodId\": 4003, \"rationale\": \"以复杂问题驱动，引导学生识别知识缺口并借助智能体开展自主学习，从而掌握智能体的使用。\", \"components\": [\"问题呈现：提出需要借助智能体解决的复杂问题\", \"知识缺口：分析解决问题所需知识与现有能力差距\", \"自主学习：使用智能体获取与整合所需信息\", \"方案讨论：在智能体辅助下比较与完善解决方案\", \"反思：总结智能体在学习过程中的作用与局限\"]}]}', 'ACCEPT', 1, 1, '2026-09-10 23:02:40', NULL, NULL, 'AI');
INSERT INTO `project_pedagogy` VALUES (7007, 1023, 4001, NULL, '围绕问题提出猜想、收集证据、比较解释并形成结论。', '[6016, 6017, 6018]', NULL, '{\"recommended\": {\"name\": \"探究式学习\", \"methodId\": 4001, \"rationale\": \"紧扣目标1梳理传感-决策-执行三环节，目标2以两个来源核验AI结果，目标3从具体传感数据判断AI输出，符合问题导向、证据驱动的探究流程。\", \"components\": [\"提出智慧驾驶“传感如何影响决策”问题\", \"对AI输出先做初步判断\", \"用两个信息来源核验AI生成结果\", \"比较证据并解释可靠性依据\", \"形成结论并提交系统协同示意图\"]}, \"alternatives\": [{\"name\": \"情境体验式学习\", \"methodId\": 4004, \"rationale\": \"以计算机模拟场景进入智慧驾驶情境，使学生在体验中观察传感数据与决策建议的关联，为系统示意图与可靠性判断提供直观证据。\", \"components\": [\"进入模拟驾驶情境\", \"执行体验任务并观察数据\", \"解释AI建议与传感数据关系\", \"应用结论完善示意图\"]}, {\"name\": \"协作学习\", \"methodId\": 4005, \"rationale\": \"通过同伴分享与证据比较，促进多个信息来源核验AI结果，在协作中相互校正判断依据，降低个体被AI主导的风险。\", \"components\": [\"个人先独立判断AI可靠性\", \"小组分享核验证据\", \"比较不同来源结果\", \"协商形成一致结论并提交产出\"]}]}', 'ACCEPT', 1, 2, '2026-09-11 12:02:10', NULL, NULL, 'AI');
INSERT INTO `project_pedagogy` VALUES (7008, 1024, 4004, NULL, '结合5年级学生已掌握计算机基本操作、设备条件为计算机以及采摘机器人结构设计与绘制的教学目标，以具体情境和体验任务组织学习，学生可经历情境进入、体验、观察、解释和应用，并在体验后充分反思，从而掌握结构设计与绘制方法。', '[6019]', NULL, '{\"recommended\": {\"name\": \"情境体验式学习\", \"methodId\": 4004, \"rationale\": \"结合5年级学生已掌握计算机基本操作、设备条件为计算机以及采摘机器人结构设计与绘制的教学目标，以具体情境和体验任务组织学习，学生可经历情境进入、体验、观察、解释和应用，并在体验后充分反思，从而掌握结构设计与绘制方法。\", \"components\": [\"情境进入：进入采摘机器人应用场景，明确结构设计与绘制任务\", \"体验：使用计算机操作进行采摘机器人相关体验\", \"观察：观察采摘机器人结构，识别关键部件\", \"解释：解释结构与设计的对应关系及绘制方法\", \"应用：完成采摘机器人结构设计与绘制作品\"]}, \"alternatives\": [{\"name\": \"项目式学习\", \"methodId\": 4002, \"rationale\": \"项目式学习围绕真实项目产出组织学习，结合采摘机器人结构设计与绘制目标，学生可经历方案设计、制作、测试与展示，在较完整的学习周期中系统掌握结构设计绘制能力，并遵循避免替代学生核心产出的要求。\", \"components\": [\"真实问题呈现：呈现采摘机器人结构设计与绘制项目问题\", \"方案设计：根据计算机操作基础设计结构方案\", \"制作与绘制：完成采摘机器人结构设计与绘制\", \"测试验证：对设计与绘制成果进行测试与优化\", \"展示交流：展示项目成果并交流经验\"]}]}', 'ACCEPT', 1, 1, '2026-09-12 14:24:24', NULL, NULL, 'AI');
INSERT INTO `quality_check` VALUES (12001, 1001, 'STANDARD_ALIGNMENT', 'PASS', NULL, 'DEMO检查：学习目标与当前固定Demo课程标准条目在信息判断方向上保持一致。', NULL, '{\"standardIds\": [2001, 2002], \"objectiveIds\": [6001, 6002, 6003]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12002, 1001, 'OBJECTIVE_ACTIVITY', 'PASS', NULL, 'DEMO检查：目标要求的识别、核验和比较行为均在活动链中出现。', NULL, '{\"activityIds\": [8001, 8002, 8003, 8004, 8005]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12003, 1001, 'OBJECTIVE_ASSESSMENT', 'PASS', NULL, 'DEMO检查：三个核心学习目标均至少有一个对应评价任务。', NULL, '{\"assessmentIds\": [9001, 9002, 9003]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12004, 1001, 'EVIDENCE_FIDELITY', 'ATTENTION', '部分证据为固定Demo数据，不可作为正式研究证据。', '当前数据库中的Evidence Card仅用于开发联调，不代表真实文献。', '正式上线前必须替换为经过人工审核的真实研究证据及原始支持文本。', '{\"demoOnly\": true, \"evidenceIds\": [5001, 5002, 5003]}', '2026-08-25 15:00:35');
INSERT INTO `quality_check` VALUES (12005, 1020, 'CONTEXT_COMPLETE', 'WARNING', '教学情境字段不完整', '确定性完整性与对齐规则检查。', '补充年级、主题、课时、班级规模、学习经验和设备条件。', '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12006, 1020, 'OBJECTIVE_CONFIRMED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12007, 1020, 'PEDAGOGY_CONFIRMED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12008, 1020, 'OBJECTIVE_ASSESSMENT_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12009, 1020, 'OBJECTIVE_ACTIVITY_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12010, 1020, 'ACTIVITY_DURATION', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12011, 1020, 'AI_ROLE_DEFINED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12012, 1020, 'cognitiveLoad', 'PASS', NULL, '活动分段清晰（引入/互评/核对/汇报），核心任务聚焦于信息核验的单一认知负荷驱动；平板条件支持检索与展示，降低物理操作负担。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12013, 1020, 'activityComplexity', 'PASS', NULL, '四环节形成从识别标准→一致性校准→来源核对→迁移列举的递进复杂度；在40分钟内通过明确时长分配维持可执行性。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12014, 1020, 'scaffoldAdequacy', 'PASS', NULL, '提供标注模板、特征提示卡、互评清单、理由句式支架、核验工作单、可信来源目录、关键词策略卡、汇报提纲、流程图与情境提示卡，覆盖任务全流程。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12015, 1020, 'formativeAssessment', 'WARNING', '过程性证据收集点不明确：学生产出（标注记录/来源链接或截图/判定与理由录音或文字）未对应到具体活动节点与采集方式。', 'assessments定义了期望的学生证据类型，但activities与prompt中的evidence数组为空，缺少何时、如何收集与如何使用反馈的安排。', 'ADD_PROCESS_EVIDENCE: type=collectionPoint, id=8016-collect, content={\"when\":\"在第3个活动（选择两项进行来源核对与判定）结束前\",\"what\":[\"学生完成的标注记录\",\"两则来源链接或截图\",\"口头或书面判定与理由\"],\"how\":\"教师在学习管理系统或表格中统一收取；对理由按‘因为____所以需要/不需要核验’进行快速编码并给出是否采信的反馈\"}', '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12016, 1020, 'objectiveActivityAlignment', 'PASS', NULL, '目标“掌握AI使用并能辨别真伪信息、合理使用AI”由四项活动共同支撑：引入共建标准、同伴互评校准、来源核对判定、汇报迁移列举类似风险情境。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12017, 1020, 'objectiveAssessmentAlignment', 'PASS', NULL, '评价任务要求标注是否需要核验、选择两条进行来源核对并说明是否采信及理由，且列举类似情况；与目标“辨别真伪信息、合理使用AI”一致。', NULL, '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12018, 1020, 'evidenceFidelity', 'WARNING', '证据保真度不足：缺少用于判断学生达标的具体评分规则/示例样例，以及证据如何被一致收集与使用的说明。', '当前设计只列出期望证据类型，未规定采集时机、最低质量标准与使用方法，可能影响评价一致性与后续教学决策。', 'ADD_PROCESS_EVIDENCE: type=rubric, id=9038-rubric, content={\"name\":\"AI资讯核验表现评分规则\",\"dimensions\":[{\"维度\":\"标注准确性\",\"指标\":[\"能正确区分‘是/否/不确定’\"]},{\"维度\":\"来源可信度\",\"指标\":[\"至少一个可信来源\",\"来源与声明匹配\"]},{\"维度\":\"判定与理由\",\"指标\":[\"明确是否采信\",\"理由基于证据或逻辑\"]},{\"维度\":\"迁移列举\",\"指标\":[\"至少两种类似风险情境\"]}],\"performanceLevels\":{\"优秀\":\"全部指标达到且理由充分、表述清晰\",\"合格\":\"核心指标达到但部分理由不够充分\",\"待改进\":\"存在关键指标未达到或缺失\"}}', '{}', '2026-09-09 19:23:01');
INSERT INTO `quality_check` VALUES (12019, 1022, 'CONTEXT_COMPLETE', 'WARNING', '教学情境字段不完整', '确定性完整性与对齐规则检查。', '补充年级、主题、课时、班级规模、学习经验和设备条件。', '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12020, 1022, 'OBJECTIVE_CONFIRMED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12021, 1022, 'PEDAGOGY_CONFIRMED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12022, 1022, 'OBJECTIVE_ASSESSMENT_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12023, 1022, 'OBJECTIVE_ACTIVITY_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12024, 1022, 'ACTIVITY_DURATION', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12025, 1022, 'AI_ROLE_DEFINED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12026, 1022, '认知负荷', 'PASS', NULL, '40分钟课时内安排4项递进活动，单活动时长控制在8-12分钟，符合六年级学生注意力分配特征，未出现信息过载或任务堆叠。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12027, 1022, '活动复杂度', 'PASS', NULL, '活动链从观察演示、独立提问、信息核验到报告撰写，步骤逻辑递进，每步核心任务聚焦单一能力点，复杂度与“掌握智能体使用”目标匹配。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12028, 1022, '支架充分性', 'PASS', NULL, '各活动均配备针对性支架，如提问流程图、问题设计模板、信息核验记录表等，覆盖智能体使用的全流程，能有效支撑学生完成核心任务。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12029, 1022, '过程性评价', 'WARNING', '过程性评价未嵌入活动流程，缺乏对学生探究过程的即时反馈与调整机制。', '评价仅聚焦最终提交的报告和对话截图，未针对独立提问、信息核验等关键过程环节设置评价节点，无法及时捕捉学生操作中的偏差。', '在独立提问与信息核验环节增加过程性评价节点，通过简易评价量表或教师即时反馈，跟踪学生探究进展。', '{\"ADD_SCAFFOLD\": {\"id\": \"SCAFFOLD_PROCESS_EVAL_001\", \"type\": \"processEvaluation\", \"content\": \"设计分环节过程性评价量表，包含独立提问的完整性、信息核验的准确性两个维度，每个维度设置3级评价标准，供教师在对应活动环节快速评估并反馈。\"}}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12030, 1022, '目标—活动一致性', 'PASS', NULL, '4项活动均明确关联目标6015“掌握智能体的使用”，活动核心任务与目标能力要求完全对应，形成从认知到实践的完整支撑链。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12031, 1022, '目标—评价一致性', 'PASS', NULL, '评价任务要求学生独立使用智能体、核验信息并提交报告，直接对应目标中“掌握智能体使用”的核心要求，评价内容与目标能力点完全匹配。', NULL, '{}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12032, 1022, 'Evidence Fidelity', 'WARNING', '现有证据清单为空，与评价任务所需的过程性证据要求不匹配，证据收集存在缺失。', '评价任务明确要求提交提问过程、核验步骤相关的报告和对话截图，但输入的evidence列表为空，无法支撑评价落地，证据完整性不足。', '补充与评价任务对应的过程性证据收集要求，明确证据类型及收集节点，确保证据能覆盖评价任务的核心环节。', '{\"ADD_PROCESS_EVIDENCE\": {\"id\": \"PROCESS_EVIDENCE_001\", \"type\": \"processTracking\", \"content\": \"在evidence中补充两条过程性证据：1. 学生独立提问的完整对话记录（含追问过程）；2. 信息核验的对比记录表（标注来源及核验结论），确保覆盖评价任务的提问过程与核验步骤。\"}}', '2026-09-10 23:06:35');
INSERT INTO `quality_check` VALUES (12033, 1023, 'CONTEXT_COMPLETE', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12034, 1023, 'OBJECTIVE_CONFIRMED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12035, 1023, 'PEDAGOGY_CONFIRMED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12036, 1023, 'OBJECTIVE_ASSESSMENT_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12037, 1023, 'OBJECTIVE_ACTIVITY_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12038, 1023, 'ACTIVITY_DURATION', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12039, 1023, 'AI_ROLE_DEFINED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12040, 1023, 'Cognitive Load Review', 'WARNING', '绘制系统协同示意图与多源核验在同一课时内紧接开展，对仅具备基础AI交互经验的学生可能造成认知超载。', '40分钟内安排四个活动，后三项总时长30分钟，其中绘制、核验与可靠性判断任务均要求独立产出，复杂度叠加。', 'ADD_SCAFFOLD: id:8022, type:scaffold, content:在示意图绘制中提供分步脚手架，将三环节逻辑模板拆为\'感知输入—数据处理—动作输出\'三栏，并配1个示例；同时为多源核验提供结构化核验记录表，降低同时管理多源的认知消耗。', '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12041, 1023, 'Activity Complexity Mapping', 'PASS', NULL, '活动从感知三环节→独立绘制→多源核验→可靠性判断，分布为10分钟、15分钟、10分钟、5分钟，复杂度逐层递进且可执行。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12042, 1023, 'Scaffold Adequacy', 'WARNING', '多源核验与AI可靠性判断环节的支架偏少，核验记录模板未给出证据来源与结论的对照字段。', '证据记录仅提供模板，未明确需要填入标准、证据等级或差异修正；判断依据参考表与数据解读提示卡存在但未说明如何选择依据。', 'ADD_SCAFFOLD: id:8024, type:scaffold, content:在核验记录模板中增加\'来源标识、差异点、采纳结论\'三栏，并附样本记录；在判断依据参考表中补充\'数据来源可靠性与场景范围\'两个判断维度示例。', '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12043, 1023, 'Formative Assessment Integration', 'WARNING', '过程性评价与课堂活动衔接不足，缺少去理解学生具体卡点的评价证据。', '课堂内呈现的评估证据为最终产出（示意图、核验记录、判断结论），未出现课堂观察或即时纠错导致的过程性评价环节。', 'ADD_PROCESS_EVIDENCE: id:8022, type:observation, content:在认识三环节后即时收集学生提问或错误理解，作为下阶段的隐性评价信号，允许教师及时调整支架。', '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12044, 1023, 'Objective-Activity Alignment', 'PASS', NULL, '三项目标分别与活动8022/8023、8024、8025一一对应，任务内容与目标内容一致。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12045, 1023, 'Objective-Assessment Alignment', 'PASS', NULL, '每项评估的studentEvidence与对应objectiveId的目标关键词一致，任务内容可映射到评价证据。', NULL, '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12046, 1023, 'Evidence Fidelity', 'WARNING', '核心证据声明的课堂增强作用尚缺明确衔接，未将KBDeX可视化的元认知调节流程在当前活动中具体化。', '仅有反思性评估结合KBDeX可视化的一般证据，未指定在绘制、核验或判断环节加入可操作步骤以实现元认知提示。', 'ADD_PROCESS_EVIDENCE: id:5019, type:rationale, content:将KBDeX可视化用于学生反思，设置\'我用了哪些证据\'与\'我还需检查什么\'两个引语，关联活动8025的判断依据生成，保持证据应用的连贯性。', '{}', '2026-09-11 12:06:37');
INSERT INTO `quality_check` VALUES (12047, 1024, 'CONTEXT_COMPLETE', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-12 14:30:07');
