INSERT INTO `quality_check` VALUES (12050, 1024, 'OBJECTIVE_ASSESSMENT_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12051, 1024, 'OBJECTIVE_ACTIVITY_ALIGNMENT', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12052, 1024, 'ACTIVITY_DURATION', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12053, 1024, 'AI_ROLE_DEFINED', 'PASS', NULL, '确定性完整性与对齐规则检查。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12054, 1024, 'cognitive-load-check', 'PASS', NULL, '课程以具体情境和体验任务组织学习，并通过结构示意图卡、提示表、观察任务单等支架降低认知负荷，结构认知与绘制任务对五年级学生的挑战得到适当支持。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12055, 1024, 'activity-complexity-check', 'PASS', NULL, '活动由结构观察识别逐步过渡到小组协作绘制、说明交流与迁移反思，复杂度递进合理，小组绘制任务通过工具指南、模板和分工任务单得到支持。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12056, 1024, 'scaffold-sufficiency-check', 'PASS', NULL, '各活动均配备针对性支架，覆盖结构观察、草图绘制、标注、说明、反思与迁移，支架与任务目标匹配，支撑充分。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12057, 1024, 'formative-assessment-check', 'PASS', NULL, '评估任务包含草图绘制与标注、结构说明及小组互评与反思，具备过程性评价特征，互评量表和问题清单提供评价依据。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12058, 1024, 'goal-activity-consistency-check', 'PASS', NULL, '四个活动均围绕采摘机器人结构认知、绘制、说明与迁移，与掌握结构设计绘制的目标一致，目标与活动对应匹配。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12059, 1024, 'goal-evaluation-consistency-check', 'PASS', NULL, '评估任务要求绘制标注并说明依据与结构特点，内容与结构设计绘制的目标一致，评价内容与目标匹配。', NULL, '{}', '2026-09-12 14:30:07');
INSERT INTO `quality_check` VALUES (12060, 1024, 'evidence-fidelity-check', 'PASS', NULL, '评估任务与目标对应，学生证据与评估任务及目标一致，能够支撑目标达成，未编造额外证据。', NULL, '{\"id\": 9043, \"type\": \"assessment\", \"studentEvidence\": [\"学生在绘制过程中提交的草图与标注完整，能够清晰呈现采摘机器人主要结构特征。\", \"学生在小组说明时准确陈述结构组成、关键结构与绘制依据，且说明内容与绘图结果一致。\"]}', '2026-09-12 14:30:07');
INSERT INTO `research_analysis` VALUES (2, 2, 1001, '{\"grade\": \"五、六年级\", \"sampleSize\": 84, \"description\": \"小学高年级学生，DEMO样本84人\", \"educationStage\": \"PRIMARY\"}', '生成式AI回答的信息核验与证据判断', '[\"INFORMATION_VERIFICATION\", \"AI_COGNITION\", \"HUMAN_AI_INTERACTION\"]', '[{\"name\": \"先判断后咨询\", \"description\": \"学生在查看AI建议前先形成个人初步判断\"}, {\"name\": \"多来源核验\", \"description\": \"至少使用两个独立信息来源核验AI生成内容\"}, {\"name\": \"同伴证据比较\", \"description\": \"在小组中比较证据并解释观点差异\"}, {\"name\": \"基于证据修订判断\", \"description\": \"根据核验结果接受、修改或拒绝AI建议\"}]', '{\"duration\": \"4周\", \"sessions\": 8, \"description\": \"每周2课时，共8课时的DEMO课堂干预\"}', '[\"信息核验表现任务\", \"证据记录单\", \"课堂观察\", \"学生反思\"]', '[\"学生在多来源信息核验与证据说明方面表现出较明显改善。\", \"先形成个人判断再接触AI建议，有助于学生识别AI回答与已有证据之间的不一致。\", \"要求学生说明“依据什么证据做出判断”，比只要求回答“可信/不可信”更能呈现其核验过程。\"]', '[\"DEMO样本来自单一学校，外部推广需谨慎。\", \"干预仅持续4周，尚不能说明长期保持与迁移效果。\", \"不同AI工具和信息来源质量可能影响学习表现。\"]', '当前DEMO研究与项目“AI的答案可信吗？”高度匹配。可将核心研究启示概括为：先判断、再咨询AI；要求多来源核验；让学生公开证据并修订判断。教学中需要提供可理解的信息来源、证据记录支架和充分的同伴讨论时间。', '{\"note\": \"Synthetic demo data. Not a real publication.\", \"version\": \"v2\", \"provider\": \"DEMO_SEED\"}', '{\"limitations\": \"TEACHER_CONFIRMED\", \"intervention\": \"TEACHER_CONFIRMED\", \"mainFindings\": \"TEACHER_CONFIRMED\", \"participants\": \"TEACHER_CONFIRMED\", \"researchTopic\": \"TEACHER_CONFIRMED\", \"assessmentTools\": \"TEACHER_CONFIRMED\", \"teachingStrategies\": \"TEACHER_CONFIRMED\", \"aiLiteracyDimensions\": \"TEACHER_CONFIRMED\"}', 100, 'READY', 1, 2, '2026-09-03 19:26:37', '2026-09-03 19:26:37', '{\"limitations\": [\"单一学校样本\", \"干预周期较短\", \"工具与来源质量可能影响结果\"], \"mainFindings\": [\"多来源核验促进学生关注信息依据\", \"先形成观点后咨询AI有助于识别信息不一致\", \"公开说明证据有助于呈现和修订判断过程\"], \"evidenceReady\": true, \"sourceExcerpt\": \"学生先形成初步判断，再通过至少两个信息来源核验AI回答，并在小组中依据证据修订结论。\", \"researchTopics\": [\"生成式AI信息核验\", \"证据判断\"], \"assessmentTools\": [\"信息核验表现任务\", \"证据记录单\", \"课堂观察\", \"学生反思\"], \"researchSubjects\": [\"小学五、六年级学生\", \"DEMO样本84人\"], \"teachingStrategies\": [\"先判断后咨询\", \"多来源核验\", \"同伴证据比较\", \"基于证据修订判断\"], \"aiLiteracyDimensions\": [\"信息核验\", \"AI认知\", \"人机有效交互\"], \"interventionDuration\": \"4周，共8课时\", \"teachingImplications\": \"在五年级AI信息核验课程中，可设计“初步判断—AI比较—多来源核验—小组证据讨论—修订结论”的学习链，并要求学生记录证据与最终判断之间的关系。\"}', 'VALIDATED', '2026-09-03 19:30:00', NULL, 'READY');
INSERT INTO `research_analysis` VALUES (3, 3, 1001, '{\"grade\": \"小学高年级\", \"sampleSize\": 56, \"description\": \"DEMO样本56人\", \"educationStage\": \"PRIMARY\"}', '同伴讨论与生成式AI批判性判断', '[\"INFORMATION_VERIFICATION\", \"HUMAN_AI_INTERACTION\"]', '[{\"name\": \"对比AI解释\", \"description\": \"比较不同AI生成解释中的共同点与冲突\"}, {\"name\": \"同伴证据讨论\", \"description\": \"小组成员依据证据解释判断差异\"}]', NULL, '[\"课堂讨论记录\", \"判断理由评分量表\"]', '[\"同伴讨论能够使部分学生更主动地说明自己的证据来源。\", \"当不同AI回答出现冲突时，学生更可能提出进一步核验需求。\"]', '[]', '当前资料已识别研究对象、主题、AI素养、两项教学策略和部分结果；干预时间及研究局限仍未确认，暂不生成正式证据卡。', '{\"note\": \"Incomplete synthetic demo record.\", \"version\": \"v2\", \"provider\": \"DEMO_SEED\"}', '{\"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 75, 'INCOMPLETE', 0, 1, '2026-09-03 19:26:37', '2026-09-09 16:21:36', '{\"limitations\": [], \"mainFindings\": [\"同伴讨论促进证据说明\", \"AI回答冲突促进进一步核验\"], \"evidenceReady\": false, \"researchTopics\": [\"同伴讨论\", \"生成式AI批判性判断\"], \"assessmentTools\": [\"课堂讨论记录\", \"判断理由评分量表\"], \"researchSubjects\": [\"小学高年级学生\", \"DEMO样本56人\"], \"teachingStrategies\": [\"对比AI解释\", \"同伴证据讨论\"], \"aiLiteracyDimensions\": [\"信息核验\", \"人机有效交互\"], \"interventionDuration\": null}', 'VALIDATED', NULL, NULL, 'FAILED');
INSERT INTO `research_analysis` VALUES (4, NULL, 1013, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:54:55', '2026-09-08 12:54:55', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 7, 'READY');
INSERT INTO `research_analysis` VALUES (6, NULL, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:56:50', '2026-09-08 12:56:50', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 3, 'READY');
INSERT INTO `research_analysis` VALUES (7, NULL, 1001, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 12:56:50', '2026-09-08 12:56:50', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 8, 'READY');
INSERT INTO `research_analysis` VALUES (8, 7, 1012, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-08 18:53:24', '2026-09-08 18:53:24', '{\"limitations\": [\"The study is limited to one-time cross-sectional survey data.\"], \"main_findings\": [\"Students in higher academic years are more inclined to use GAI and prefer it over traditional resources.\", \"Non-native English speakers use and adopt GAI more readily than native speakers.\", \"Compared to White students, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it.\", \"Black students report a more positive impact of GAI on their academic performance.\", \"Students with higher conscientiousness use GAI less.\", \"Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work.\", \"Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use.\", \"Students with higher extraversion show a stronger preference for GAI over traditional resources.\", \"Students with higher intellect/imagination tend to prefer traditional resources.\"], \"evidence_ready\": false, \"source_excerpt\": \"Our findings reveal: (a) Students in higher academic years are more inclined to use GAI and prefer it over traditional resources. (b) Non-native English speakers use and adopt GAI more readily than native speakers. (c) Compared to White, Asian students report higher GAI usage, perceive greater academic benefits, and express a stronger preference for it. Similarly, Black students report a more positive impact of GAI on their academic performance. Personality traits also play a significant role in shaping perceptions and usage of GAI. After controlling demographic factors, we found that personality still significantly predicts GAI use and attitudes: (a) Students with higher conscientiousnes s use GAI less . (b) Students who are higher in agreeableness perceive a less positive impact of GAI on academic performance and express more ethical concerns about using it for academic work. (c) Students with higher emotional stability report a more positive impact of GAI on learning and fewer concerns about its academic use. (d) Students with higher extraversion show a stronger preference for GAI over traditional resources. (e) Students with higher intellect/imagination tend to prefer traditional resources.\", \"research_topics\": [\"University students\' use of generative AI (GAI)\", \"The relationship between GAI use and student demographics\", \"The relationship between GAI use and personality traits (Big Five)\"], \"assessment_tools\": [\"50-item International Personality Item Pool (IPIP)\"], \"research_subjects\": [\"undergraduate and graduate students in the United States\"], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL, 'READY');
