INSERT INTO `research_analysis` VALUES (32, NULL, 1022, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-10 16:26:33', '2026-09-10 16:26:33', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 29, 'READY');
INSERT INTO `research_analysis` VALUES (33, 20, 1022, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-10 16:27:45', '2026-09-10 16:27:45', '{\"limitations\": [], \"main_findings\": [\"基于多模态大语言模型的协作论证支架引发了最丰富的协作论证话语转移行为和更高阶的知识建构观点\", \"总结升华的话语转移行为与关键观点密切相关，是促进知识建构从低阶向高阶转变的主导因素\", \"关键观点显著正向促进知识建构（路径系数为+3.25，p<0.01）\", \"若关键观点的末位前置观点为“创新观点”，则对知识建构具有显著负向影响（路径系数为-1.61，p<0.05）\", \"“反对观点”“提出疑问”“创新观点”“权威证据”正向影响“总结升华”，其中，“提出疑问”“权威证据”影响最为显著（p值均小于0.001）\", \"“总结升华”话语转移行为显著正向促进知识建构（路径系数为+4.20，p<0.001）\", \"“消极情感”促进知识建构的可能性较低，而“积极情感”对知识建构不存在显著影响\"], \"evidence_ready\": false, \"source_excerpt\": \"Results indicate that the collaborative\\nargumentation scaffolding based on multimodal large language models has triggered the richest collaborative\\nargumentation discourse transfer behaviors and higher-order knowledge building viewpoints. The summary\\nof sublimated discourse transfer behaviors is closely related to key viewpoints, which emerges as the\\ndominant factor facilitating the transition of knowledge building from lower levels to higher levels.\", \"research_topics\": [\"基于多模态大模型的协作论证支架\", \"知识建构\", \"协作论证\", \"人机协同学习\"], \"assessment_tools\": [\"AI素养量表\"], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": \"5周\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"AI技术理解\", \"AI评估\", \"AI应用\"]}', 'VALIDATED', NULL, NULL, 'READY');
