INSERT INTO `research_analysis` VALUES (57, 31, 1026, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 2, '2026-09-12 16:53:16', '2026-09-12 16:53:16', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [\"how GenAI tools influence students’ engagement and motivation towards reflective writing, as well as the depth and quality of the writing itself\", \"cognitive demands of reflection\", \"contextual and environmental influences\"], \"assessment_tools\": [], \"research_subjects\": [\"five secondary school students from an English-medium local secondary school in Hong Kong, aged between 14 and 17\"], \"teaching_strategies\": [], \"intervention_duration\": \"three-week summer internship programme related to GenAI in education\", \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL, 'READY');
INSERT INTO `research_analysis` VALUES (58, NULL, 1027, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-12 16:56:02', '2026-09-12 16:56:02', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [], \"assessment_tools\": [], \"research_subjects\": [], \"teaching_strategies\": [], \"intervention_duration\": null, \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, 45, 'READY');
INSERT INTO `research_analysis` VALUES (59, 32, 1027, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"MOCK\", \"intervention\": \"MOCK\", \"mainFindings\": \"MOCK\", \"participants\": \"MOCK\", \"researchTopic\": \"MOCK\", \"assessmentTools\": \"MOCK\", \"teachingStrategies\": \"MOCK\", \"aiLiteracyDimensions\": \"MOCK\"}', 0, 'INCOMPLETE', 0, 1, '2026-09-12 16:59:24', '2026-09-12 16:59:24', '{\"limitations\": [\"Without teacher guidance and proper training, the integration of GenAI in reflective writing may deter rather than promote higher order thinking.\", \"Effective reflection often requires a higher level of metacognitive knowledge that many secondary students may not fully develop.\", \"Students may experience AI guilt due to concerns about authenticity, perceived laziness, and over-reliance on AI.\", \"Educators need to help students strike a balance between using AI as a writing support and engaging in authentic, independent reflection.\", \"Educators should create assignments or prompts that encourage deeper reflection beyond surface-level improvements.\", \"Educators must emphasise that reflective writing should remain a deeply personal process.\", \"Rubrics should be adjusted to reward depth, originality, and personal insight in reflective writing.\"], \"main_findings\": [\"GenAI tools, such as ChatGPT and Bing, have emerged as innovative supports for enhancing students’ reflective capabilities.\", \"These tools can stimulate critical thinking, creativity, and problem-solving skills in educational contexts.\", \"Cognitive or metacognitive prompts while journaling led to improved learning outcomes.\", \"Writing alone may not yield significant learning benefits unless coupled with metacognitive prompts that encourage students to reflect on their knowledge and learning processes.\", \"Research on GenAI’s impact on students’ writing remains limited because the tool has been released relatively recently to the wider public.\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"how GenAI tools influence students’ engagement and motivation towards reflective writing, as well as the depth and quality of the writing itself\"], \"assessment_tools\": [], \"research_subjects\": [\"five secondary school students from an English-medium local secondary school in Hong Kong, aged between 14 and 17, who participated in a three-week summer internship programme related to GenAI in education\"], \"teaching_strategies\": [], \"intervention_duration\": \"three-week\", \"teaching_implications\": null, \"ai_literacy_dimensions\": []}', 'VALIDATED', NULL, NULL, 'READY');
