INSERT INTO `research_analysis` VALUES (71, 34, 1029, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"TEACHER\", \"participants\": \"TEACHER\", \"researchTopics\": \"TEACHER\", \"assessmentTools\": \"AI_CHAT\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\", \"teachingImplications\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 8, '2026-09-12 20:59:16', '2026-09-12 20:59:16', '{\"limitations\": [], \"main_findings\": [], \"evidence_ready\": false, \"source_excerpt\": null, \"research_topics\": [\"职前教师设计思维（DT）的培育\", \"整合生成式AI（GenAI）与知识建构（KB）的教学设计学习环境设计\", \"通过AI与人机共创支持迭代教学设计与反思规范的形成\", \"基于设计思维的教学设计评估与反思能力发展\"], \"assessment_tools\": [\"教学设计评价框架\", \"编码框架\", \"量规评分\"], \"research_subjects\": [\"110名职前教师（20-22岁）\"], \"teaching_strategies\": [\"教学设计评估框架、编码框架及职前教师作品评价\"], \"intervention_duration\": \"14weeks\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"职前教师（PSTs）设计思维（DT）\"]}', 'VALIDATED', NULL, NULL, 'READY');
INSERT INTO `research_analysis` VALUES (72, 34, 1029, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"limitations\": \"TEACHER\", \"intervention\": \"TEACHER\", \"mainFindings\": \"AI_CHAT\", \"participants\": \"TEACHER\", \"researchTopics\": \"TEACHER\", \"assessmentTools\": \"AI_CHAT\", \"teachingStrategies\": \"TEACHER\", \"aiLiteracyDimensions\": \"TEACHER\", \"teachingImplications\": \"TEACHER\"}', 0, 'INCOMPLETE', 0, 9, '2026-09-12 21:01:04', '2026-09-12 21:01:04', '{\"limitations\": [], \"main_findings\": [\"职前教师在整合生成式AI与分析支持的反思的协作环境中，其设计思维整体上有统计学上显著但幅度较小的提升（前测 M=5.15，SD=0.60；后测 M=5.25，SD=0.58；t(102)=2.151, p=.034, d=0.21）。\", \"在设计思维各子维度中，发现（Discover）和定义（Define）维度提升显著（发现维度 p=.026；定义维度 p=.019），而构思（Ideate）和测试（Test）维度未达到统计显著性。\", \"对1305条知识论坛笔记的内容分析表明，职前教师的设计实践从早期的问题界定和构思阶段，逐渐转向后期的原型制作和测试阶段。\", \"随着设计方案的成熟，职前教师会重新审视并细化问题定义，展现出设计思维的迭代性和自适应特征。\", \"在人机共创阶段，职前教师在设计和实现过程的中后期展现出加速成长，生成式AI起到了促进构思细化和迭代优化的催化剂作用。\"], \"evidence_ready\": true, \"source_excerpt\": null, \"research_topics\": [\"职前教师设计思维（DT）的培育\", \"整合生成式AI（GenAI）与知识建构（KB）的教学设计学习环境设计\", \"通过AI与人机共创支持迭代教学设计与反思规范的形成\", \"基于设计思维的教学设计评估与反思能力发展\"], \"assessment_tools\": [\"教学设计评价框架\", \"编码框架\", \"量规评分\"], \"research_subjects\": [\"110名职前教师（20-22岁）\"], \"teaching_strategies\": [\"教学设计评估框架、编码框架及职前教师作品评价\"], \"intervention_duration\": \"14weeks\", \"teaching_implications\": null, \"ai_literacy_dimensions\": [\"职前教师（PSTs）设计思维（DT）\"]}', 'VALIDATED', NULL, NULL, 'READY');
