INSERT INTO `teaching_resource_version` VALUES (1, 1, 1, '{\"title\": \"教师上课快速查看指南\", \"blocks\": [{\"key\": \"overview_1\", \"title\": \"课程概览\", \"content\": {\"duration\": \"40分钟\", \"objectives\": [\"掌握AI的使用，能够辨别AI真伪信息，合理使用AI\"], \"activities_order\": [\"引入与标准共建\", \"同伴互评\", \"来源核对与判定\", \"汇报与迁移\"]}}, {\"key\": \"activity_8014_1\", \"title\": \"辨别AI信息真伪：引入与标准共建\", \"content\": {\"time\": \"6分钟\", \"ai_role\": \"展示AI生成资讯并提示风险点供学生对照\", \"scaffolds\": [\"标注模板（是/否/不确定）\", \"关键特征提示卡（数字/时间/地点/可核查事件）\"], \"student_action\": \"在平板上用“是/否/不确定”标注每条资讯中的事实声明；与同伴讨论并提交自己认为最需要核验的一条\", \"teacher_action\": \"呈现两条关于“校园宠物狗”的简短中文资讯，引导学生区分观点与事实；板书“需核验信息”的标准（如包含具体数字/时间/地点/可验证事件）\", \"observation_focus\": \"快速口头提问：为什么这条信息值得核验？收集学生的标注截图作为即时证据\"}}, {\"key\": \"activity_8015_2\", \"title\": \"同伴互评：标注一致性核对\", \"content\": {\"time\": \"7分钟\", \"ai_role\": \"提供“常见不可信信号”提示（如缺少来源、过于完美/夸张描述）辅助讨论\", \"scaffolds\": [\"同伴互评清单\", \"理由句式支架（因为____，所以需要/不需要核验）\"], \"student_action\": \"对比同伴标注，讨论分歧并用一句话说明理由；修改或确认自己的标注，准备进入下一步核验\", \"teacher_action\": \"组织两人一组互评，提供评价要点：是否明确指出了事实声明、理由是否基于可验证性而非喜好\", \"observation_focus\": \"教师随机抽查2—3组，记录“标注—理由”是否匹配，给出过程性反馈\"}}, {\"key\": \"activity_8016_3\", \"title\": \"选择两项进行来源核对与判定\", \"content\": {\"time\": \"17分钟\", \"ai_role\": \"仅提供检索入口与关键词建议，不直接回答对错；自动过滤不在允许目录的网站\", \"scaffolds\": [\"核验工作单（含声明列/来源列/对照结果/结论列）\", \"可信来源目录（政府/机构/权威媒体）\", \"关键词策略卡（地名+事件+日期/机构名+公告）\"], \"student_action\": \"在平板上检索；将找到的来源链接/截图粘贴到工作单；逐条对照事实声明；以口头或文字说明“采信/不采信”并写出依据\", \"teacher_action\": \"分发统一的“核验工作单”；示范如何在可信平台检索关键词；提醒只使用课堂允许的来源目录；巡视并提供个别指导\", \"observation_focus\": \"检查工作单：是否选出两条信息；是否为每条提供至少一个可信来源；是否存在“来源—声明”对照；是否给出结论与理由\"}}, {\"key\": \"activity_8017_4\", \"title\": \"汇报与迁移：列举类似情况\", \"content\": {\"time\": \"10分钟\", \"ai_role\": \"汇总各组要点，投影“通用核验流程图”帮助全班迁移\", \"scaffolds\": [\"汇报提纲模板\", \"通用核验流程图\", \"情境列举提示卡（领域/风险点/应对动作）\"], \"student_action\": \"口头或书面展示核对过程与结论；听取他组意见；在平板上列出至少两个类似情况（如AI生成的健康建议/本地新闻/学校通知）并简述核验思路\", \"teacher_action\": \"主持小型发布会：每组用1分钟汇报“如何核对”；引导归纳通用步骤；布置迁移任务：列举相似场景并说明防范做法\", \"observation_focus\": \"依据标准打分：正确识别至少两条需核验信息；提供可信来源并对照；明确采信与否及理由；能列举至少两种类似情境\"}}, {\"key\": \"assessment_reminder_9038\", \"title\": \"评估提醒\", \"content\": {\"task\": \"给定一条由AI生成的中文资讯（含2—3个事实要点），学生需完成标注、来源核对及判定，并列举类似情况\", \"criteria\": [\"正确识别出至少两条需要核验的信息\", \"为所选信息提供至少一个可信来源并进行对照\", \"明确表达是否采信，并基于证据给出合理解释\"], \"evidence_required\": [\"学生完成的“是/否/不确定”标注记录\", \"用于核对的两则来源链接或截图\", \"学生口头或书面的判定与理由（录音/文字）\"]}}, {\"key\": \"closing_summary_5\", \"title\": \"总结与收尾\", \"content\": {\"teacher_prompt\": \"回顾本节课核心技能：如何通过多源核验判断AI信息真伪，强调日常应用中的谨慎态度\", \"student_reflection\": \"独立填写学习日志：“今天我学会了……，下次遇到类似情况我会……”\"}}], \"metadata\": {\"provider\": \"spark\", \"projectId\": 1020, \"generatedAt\": \"2026-09-09T15:59:00.594009+00:00\", \"resourceType\": \"TEACHER_GUIDE\", \"courseDesignBased\": true, \"researchEvidenceCount\": 0}}', NULL, 'AI', 'Generated by Mock AI', 1, '2026-09-09 23:59:00');
INSERT INTO `teaching_resource_version` VALUES (2, 2, 1, '{\"title\": \"辨别AI信息真伪：引入与标准共建＋同伴互评＋来源核对＋迁移汇报\", \"blocks\": [{\"key\": \"learning_goal\", \"title\": \"学习目标\", \"content\": \"掌握AI的使用，能够辨别AI真伪信息，合理使用AI。\"}, {\"key\": \"before_thinking\", \"title\": \"课前准备\", \"content\": \"带好平板；准备好记录工具；保持好奇与谨慎，不轻易相信未核实的信息。\"}, {\"key\": \"task_8014\", \"title\": \"活动一（6分钟）：辨别AI信息真伪——引入与标准共建\", \"content\": \"核心任务：观察两条关于“校园宠物狗”的短资讯（一条人类撰写，一条AI生成），找出可能的“事实声明”，共同制定“是否需要核验”的标准。\\n学生行动：\\n1) 在平板上用“是/否/不确定”标注每条资讯中的事实声明。\\n2) 与同伴讨论，并提交你认为最需要核验的一条。\\nAI角色：展示AI生成资讯，并提示风险点供对照。\\n记录要求：\\n- 我的标注结果（截图或编号）：\\n- 我选择“最需要核验”的那条编号及理由（一句话）：\\n- 我们小组提出的“需核验”标准要点（至少2条，如包含具体数字/时间/地点/可验证事件等）：\"}, {\"key\": \"scaffold_8014\", \"title\": \"支架资源（活动一）\", \"content\": \"- 标注模板：是/否/不确定\\n- 关键特征提示卡：数字、时间、地点、可核查事件\"}, {\"key\": \"task_8015\", \"title\": \"活动二（7分钟）：同伴互评——标注一致性核对\", \"content\": \"核心任务：交换标注结果，比较判断理由，形成更可靠的“待核验清单”。\\n学生行动：\\n1) 两人一组对比标注，讨论分歧。\\n2) 用一句话说明理由，修改或确认自己的标注，准备进入下一步核验。\\nAI角色：提供“常见不可信信号”提示（如缺少来源、过于完美/夸张描述）。\\n记录要求：\\n- 同伴与我不一致的地方（列出条目或编号）：\\n- 我的修改决定：____（修改/维持）\\n- 修改后的理由（一句话，使用“因为____，所以需要/不需要核验”）：\\n- 本组最终“待核验清单”（勾选或写出标题/编号）：\"}, {\"key\": \"scaffold_8015\", \"title\": \"支架资源（活动二）\", \"content\": \"- 同伴互评清单\\n- 理由句式支架：因为____，所以需要/不需要核验\"}, {\"key\": \"task_8016\", \"title\": \"活动三（17分钟）：选择两项进行来源核对与判定\", \"content\": \"核心任务：从给定AI资讯中任选两条，各查找至少一个可信来源进行对照，并说明是否采信及理由。\\n学生行动：\\n1) 在平板上检索，只使用课堂允许的来源目录。\\n2) 将找到的来源链接/截图粘贴到工作单，逐条对照事实声明。\\n3) 以口头或文字说明“采信/不采信”并写出依据。\\nAI角色：仅提供检索入口与关键词建议；自动过滤不在允许目录的网站。\\n记录要求（每条信息分别填写）：\\n- 所选信息标题/编号：\\n- 我认为需要核验的事实声明（摘录1—2条）：\\n- 检索关键词：\\n- 可信来源（至少1个）：名称/链接/截图\\n- 对照结果（来源与声明如何一致/不一致）：\\n- 结论：____（采信/不采信）\\n- 依据与理由（简明写出证据来源和逻辑）：\\n- 遇到的困难与解决办法：\"}, {\"key\": \"scaffold_8016\", \"title\": \"支架资源（活动三）\", \"content\": \"- 核验工作单：声明列/来源列/对照结果/结论列\\n- 可信来源目录：政府/机构/权威媒体\\n- 关键词策略卡：地名+事件+日期/机构名+公告\"}, {\"key\": \"ai_interaction_record\", \"title\": \"AI互动记录\", \"content\": \"- 初始观点（对这条AI资讯的第一印象/预测）：\\n- AI贡献了什么（例如：展示AI文本、提示风险点、给出关键词建议；请圈出实际用到的内容）：\\n- 我对AI输出的处理：____（接受/修改/拒绝）\\n- 接受/修改/拒绝的理由（一句话）：\\n- 我的观点变化（从“先入为主”到“基于证据”的变化描述）：\"}, {\"key\": \"evidence_record\", \"title\": \"学习证据汇总\", \"content\": \"- 标注记录截图/编号：\\n- 同伴互评讨论要点（1—2句）：\\n- 两个核验项目的来源链接/截图：\\n- 我的判定与理由（可附简短录音/文字摘要）：\"}, {\"key\": \"task_8017\", \"title\": \"活动四（10分钟）：汇报与迁移——列举类似情况\", \"content\": \"核心任务：小组总结核验方法并在全班分享；独立列举“类似的AI信息风险情境”至少两种，并简述核验思路。\\n学生行动：\\n1) 小组用1分钟汇报“如何核对”。\\n2) 听取他组意见，归纳通用步骤。\\n3) 在平板上列出至少两个类似情况，并简述核验思路。\\n记录要求：\\n- 小组汇报要点（三步法/关键动作）：\\n- 我听到的其他组好做法（至少1条）：\\n- 类似情境列举（至少2种，如AI健康建议/本地新闻/学校通知等）：\\n  情境A：____；核验思路：____\\n  情境B：____；核验思路：____\\n- 今后遇到类似信息，我会首先做的三件事：\"}, {\"key\": \"scaffold_8017\", \"title\": \"支架资源（活动四）\", \"content\": \"- 汇报提纲模板\\n- 通用核验流程图\\n- 情境列举提示卡：领域/风险点/应对动作\"}, {\"key\": \"reflection\", \"title\": \"反思与总结\", \"content\": \"- 今天我学到的最有用的核验技巧是：\\n- 下次我还需要改进的是：\\n- 我想提醒同学注意的一句话（关于AI信息与核验）：\"}, {\"key\": \"final_output\", \"title\": \"最终成果提交清单\", \"content\": \"- 已完成的标注记录（是/否/不确定）\\n- 同伴互评后的“待核验清单”\\n- 两条信息的核验工作单（含可信来源与对照）\\n- 明确的结论与理由\\n- 至少两种类似情境及其核验思路\"}], \"metadata\": {\"grade\": 4, \"format\": \"4人小组\", \"devices\": [\"TABLET\"], \"subject\": \"AI伦理\", \"provider\": \"spark\", \"projectId\": 1020, \"classHours\": 4, \"difficulty\": \"适中\", \"generatedAt\": \"2026-09-09T16:05:03.056061+00:00\", \"resourceType\": \"WORKSHEET\", \"studentLevel\": \"ADVANCED\", \"activityOrder\": [\"8014\", \"8015\", \"8016\", \"8017\"], \"languageStyle\": \"适合儿童\", \"lessonMinutes\": 40, \"courseDesignBased\": true, \"lowDeviceAlternative\": true, \"researchEvidenceCount\": 0}}', NULL, 'AI', 'Generated by Mock AI', 1, '2026-09-10 00:05:03');
INSERT INTO `teaching_resource_version` VALUES (3, 2, 2, '{\"title\": \"AI伦理-辨别AI信息真伪学生学习单（四年级·进阶）\", \"blocks\": [{\"key\": \"learning_goal\", \"title\": \"学习目标\", \"content\": \"掌握AI的使用，能够辨别AI真伪信息，合理使用AI。\"}, {\"key\": \"before_thinking\", \"title\": \"课前准备与启动思考\", \"content\": \"1. 快速回想：当你看到一条有趣的“校园宠物狗”消息时，你会先检查什么？\\n2. 词语联想：看到“AI生成的信息”，你想到哪些词？（如：快/准/假/有趣/要核实等）\\n3. 设备自检：请打开平板，确保可以正常浏览老师提供的资讯与“可信来源目录”。\"}, {\"key\": \"task_8014\", \"title\": \"任务1：辨别AI信息真伪——引入与标准共建（6分钟）\", \"content\": \"核心任务：观察两条短文本（一条人类撰写、一条AI生成），找出可能的“事实声明”，共同制定“是否需要核验”的判断标准。\\n\\n步骤：\\n1. 阅读两条关于“校园宠物狗”的简短中文资讯。\\n2. 在“标注模板”上，对每条资讯中的每个句子选择“是/否/不确定”：这个句子是否包含需要外部核验的事实声明？\\n3. 与同伴讨论：哪一条最需要核验？为什么？\\n4. 提交你的标注截图，并在下方写下你们组认为“最需要核验”的一条及其理由。\\n\\n记录处：\\n- 我最需要核验的一条：________\\n- 理由（一句话）：________\\n\\n可用工具：\\n- 标注模板（是/否/不确定）\\n- 关键特征提示卡（数字/时间/地点/可核查事件）\"}, {\"key\": \"evidence_record_8014\", \"title\": \"证据记录1：标注与理由\", \"content\": \"- 我的标注截图已提交：□\\n- 我们组选定“最需核验”的一条及理由：________\"}, {\"key\": \"task_8015\", \"title\": \"任务2：同伴互评——标注一致性核对（7分钟）\", \"content\": \"核心任务：交换标注结果，比较判断理由，形成更可靠的“待核验清单”。\\n\\n步骤：\\n1. 两人一组，互相查看对方的“是/否/不确定”标注。\\n2. 使用“同伴互评清单”检查：\\n   - 是否明确指出了事实声明？\\n   - 理由是否基于“可验证性”（而非个人喜好）？\\n3. 用“理由句式支架”讨论分歧：因为____，所以需要/不需要核验。\\n4. 修改或确认自己的标注，并准备进入下一步核验。\\n\\n记录处：\\n- 我们的一致点：________\\n- 仍有分歧的地方：________\\n- 最终确定的“待核验清单”（最多2条）：________\"}, {\"key\": \"scaffold_8015\", \"title\": \"支架支持：同伴互评清单与理由句式\", \"content\": \"- 同伴互评清单：\\n  ① 是否清晰标出事实声明？\\n  ② 理由是否围绕“能否被外部证据验证”？\\n  ③ 是否避免以“喜欢/不喜欢”作为判断依据？\\n- 理由句式支架：\\n  因为这条信息包含（数字/时间/地点/可核查事件），所以需要核验。\\n  因为这只是一个观点/感受，没有可核查的细节，所以不需要核验。\"}, {\"key\": \"task_8016\", \"title\": \"任务3：选择两项进行来源核对与判定（17分钟）\", \"content\": \"核心任务：从给定AI资讯中任选两条，各查找至少一个可信来源进行对照，并说明是否采信及理由。\\n\\n步骤：\\n1. 打开“核验工作单”，填写你要核验的两条信息标题或关键句。\\n2. 仅使用“可信来源目录”内的平台进行检索；可用“关键词策略卡”优化搜索。\\n3. 将找到的来源链接/截图粘贴到工作单，并逐条对照事实声明。\\n4. 写出“采信/不采信”的结论，并用证据解释原因。\\n\\n要求：\\n- 必须选择两条信息进行核验。\\n- 每条信息至少提供一个可信来源。\\n- 必须存在“来源—声明”的对照过程。\\n- 结论需配有理由。\\n\\n记录处（建议直接在工作单完成后摘录要点）：\\n- 信息A：标题/关键句________；来源链接/截图________；对照结果________；结论与理由________\\n- 信息B：标题/关键句________；来源链接/截图________；对照结果________；结论与理由________\"}, {\"key\": \"scaffold_8016\", \"title\": \"支架支持：核验工作单与来源/关键词指南\", \"content\": \"- 核验工作单列项：\\n  ① 事实声明摘录\\n  ② 可信来源名称与链接/截图\\n  ③ 对照结果（相同/不同/无法确定）\\n  ④ 结论（采信/不采信）\\n  ⑤ 理由（基于对照的证据）\\n- 可信来源目录类型：政府/机构/权威媒体\\n- 关键词策略卡：\\n  - 地名+事件+日期\\n  - 机构名+公告/通报\\n  - 学校名+通知/新闻\"}, {\"key\": \"ai_interaction_record_8016\", \"title\": \"AI互动记录（仅当课堂启用AI功能时填写）\", \"content\": \"- 初始观点（我看到这条信息时的第一反应）：________\\n- AI提供的贡献（如：提示风险点/给出关键词建议/展示流程图）：________\\n- 我的选择：接受/修改/拒绝，理由是：________\\n- 观点变化（我的想法如何改变，或为何保持不变）：________\"}, {\"key\": \"task_8017\", \"title\": \"任务4：汇报与迁移——列举类似情况（10分钟）\", \"content\": \"核心任务：小组总结核验方法并进行全班分享；独立列举“类似的AI信息风险情境”至少两种。\\n\\n步骤：\\n1. 小组合作，用“汇报提纲模板”组织1分钟发言：我们如何核对这两条信息？\\n2. 听取他组意见，完善你们的核验步骤。\\n3. 独立在平板上完成“情境列举提示卡”：至少列出两种相似场景，并简述核验思路。\\n\\n记录处：\\n- 我们组的核验步骤（用序号列出1-3步）：\\n  1) ________\\n  2) ________\\n  3) ________\\n- 类似情境与核验思路：\\n  情境1：________；核验思路：________\\n  情境2：________；核验思路：________\"}, {\"key\": \"scaffold_8017\", \"title\": \"支架支持：汇报提纲与通用流程图\", \"content\": \"- 汇报提纲模板：\\n  ① 我们要核对什么？\\n  ② 我们用了哪些来源？\\n  ③ 我们如何对照并得出结论？\\n- 通用核验流程图（供迁移使用）：\\n  读信息→标事实→找来源→做对照→下结论→说理由\"}, {\"key\": \"final_output\", \"title\": \"最终产出提交清单\", \"content\": \"请按顺序确认以下内容已提交：\\n1. 任务1：标注截图与“最需核验”的理由。\\n2. 任务2：同伴互评后的“待核验清单”（最多2条）。\\n3. 任务3：两条信息的“核验工作单”完整页面（含来源链接/截图、对照、结论与理由）。\\n4. 任务4：小组核验步骤与至少两种类似情境的列举。\"}, {\"key\": \"reflection\", \"title\": \"反思与迁移\", \"content\": \"- 今天我学到的核验关键点：________\\n- 下次遇到AI生成的信息，我会首先做三件事：\\n  1) ________\\n  2) ________\\n  3) ________\\n- 我还想向老师/同学请教的问题：________\"}], \"metadata\": {\"grade\": 4, \"format\": \"4人小组\", \"devices\": [\"TABLET\"], \"duration\": \"15分钟\", \"provider\": \"spark\", \"projectId\": 1020, \"difficulty\": \"适中\", \"generatedAt\": \"2026-09-09T16:18:26.328030+00:00\", \"resourceType\": \"WORKSHEET\", \"studentLevel\": \"ADVANCED\", \"languageStyle\": \"适合儿童\", \"lessonMinutes\": 40, \"resourceStyle\": \"CLASSROOM_READY\", \"courseDesignBased\": true, \"lowDeviceAlternative\": true, \"researchEvidenceCount\": 0}}', NULL, 'AI', '严格遵循已确认课程设计，未更改教学目标、活动顺序与评估逻辑；将四段活动转化为可直接填写的学习单模块，新增必要的记录区与支架，保留平板环境下的AI互动记录入口，并提供低设备替代可行性。', 1, '2026-09-10 00:18:26');
INSERT INTO `teaching_resource_version` VALUES (4, 2, 3, '{\"title\": \"学生用学习单（4人小组｜平板完成｜约15分钟填写）\", \"blocks\": [{\"key\": \"learning_goal\", \"title\": \"学习目标\", \"content\": \"掌握AI的使用，能够辨别AI真伪信息，合理使用AI。本节课重点练习：区分观点与事实、制定“需要核验”的标准、用可信来源核对信息并说明理由。\"}, {\"key\": \"before_thinking\", \"title\": \"学习准备与初始观点\", \"content\": \"1) 想一想：当你看到一条关于“校园宠物狗”的中文资讯，你会先问什么问题？\\n2) 你认为“AI生成的信息”和“人类写的信息”，哪一个更容易有错误事实？为什么？\\n3) 今天你将阅读两条短资讯，并用“是/否/不确定”标注哪些事实声明需要核验。\"}, {\"key\": \"task_1\", \"title\": \"任务1：引入与标准共建（6分钟）\", \"content\": \"核心任务：观察两条短文本（一条人类撰写、一条AI生成），找出可能的“事实声明”，共同制定“是否需要核验”的判断标准。\\n\\n请完成：\\n1) 在平板上打开两条关于“校园宠物狗”的简短中文资讯。\\n2) 逐条阅读，遇到“可以被验证的事实性句子”时，用“是/否/不确定”标注它是否“需要外部核验”。\\n3) 从两条资讯中，选出你认为“最需要核验”的一条，并写出理由（提示：是否包含具体数字/时间/地点/可核查事件）。\\n\\n记录要求：\\n- 我选的最需核验的一条是：____________________\\n- 理由是（勾选或补充）：包含数字/时间/地点/可核查事件；缺少来源；描述过于完美/夸张；其他：________\"}, {\"key\": \"task_2\", \"title\": \"任务2：同伴互评——标注一致性核对（7分钟）\", \"content\": \"核心任务：交换标注结果，比较判断理由，形成更可靠的“待核验清单”。\\n\\n请完成：\\n1) 与同伴交换标注截图或记录，对比“需要核验”的选择是否一致。\\n2) 讨论分歧：各自用一句话说明理由（句式支架：因为____，所以需要/不需要核验）。\\n3) 修改或确认自己的标注，准备进入下一步核验。\\n\\n记录要求：\\n- 我和同伴达成一致的“待核验清单”（列出1—3条）：____________________\\n- 最重要的一条理由是：____________________\"}, {\"key\": \"task_3\", \"title\": \"任务3：选择两项进行来源核对与判定（课堂分段完成，合计17分钟）\", \"content\": \"核心任务：从给定AI资讯中任选两条，各查找至少一个可信来源进行对照，并说明是否采信及理由；最后列举两种类似风险情境。\\n\\nA. 选择与检索\\n1) 我选择核对的第1条信息是：____________________\\n2) 我在“可信来源目录”中选择的来源是（政府/机构/权威媒体）：____________________\\n3) 关键词检索策略（地名+事件+日期/机构名+公告）：____________________\\n\\nB. 对照与判定（重复以下格式，完成两条）\\n【第1条】\\n- 事实声明摘录：____________________\\n- 找到的来源链接/截图：____________________\\n- 对照结果（一致/不一致/无法确定）：____________________\\n- 结论：我（采信/不采信）这条信息。\\n- 理由（基于证据）：____________________\\n\\n【第2条】\\n- 事实声明摘录：____________________\\n- 找到的来源链接/截图：____________________\\n- 对照结果（一致/不一致/无法确定）：____________________\\n- 结论：我（采信/不采信）这条信息。\\n- 理由（基于证据）：____________________\\n\\nC. 迁移应用\\n- 我还想到两个“类似的AI信息风险情境”（如AI生成的健康建议/本地新闻/学校通知等）：\\n1) ____________________；核验思路：____________________\\n2) ____________________；核验思路：____________________\"}, {\"key\": \"evidence_record\", \"title\": \"证据留存\", \"content\": \"为便于评估，请确保提交/保存以下内容：\\n1) 你在平板上的“是/否/不确定”标注截图或记录；\\n2) 用于核对的两则可信来源链接或截图；\\n3) 你口头或文字的判定与理由（可在平板笔记中录音/打字）。\"}, {\"key\": \"ai_interaction_record\", \"title\": \"AI互动记录（仅记录本次使用的AI相关内容）\", \"content\": \"1) 我的初始观点/担心：____________________\\n2) AI提供的贡献（例如展示AI生成资讯、提示风险点、投影通用流程图等）：____________________\\n3) 我的决定：接受/修改/拒绝 哪一部分，理由是：____________________\\n4) 我的观点变化（简要总结）：____________________\"}, {\"key\": \"reflection\", \"title\": \"反思与改进\", \"content\": \"1) 今天我做对的一件事是：____________________\\n2) 下次我会改进的一点是：____________________\\n3) 如果再遇到“AI生成的本地新闻/健康建议/学校通知”，我将首先检查：____________________\"}, {\"key\": \"final_output\", \"title\": \"最终输出汇总\", \"content\": \"请按顺序检查并提交：\\n- 标注记录（含“最需核验”的理由）\\n- 同伴互评后的“待核验清单”\\n- 两条信息的“来源—声明—对照—结论—理由”\\n- 两个类似风险情境及核验思路\\n- AI互动记录（如有）\"}], \"metadata\": {\"grade\": 4, \"format\": \"4人小组\", \"devices\": [\"TABLET\"], \"duration\": \"15分钟（填写）\", \"provider\": \"spark\", \"projectId\": 1020, \"difficulty\": \"适中\", \"generatedAt\": \"2026-09-09T16:28:16.549740+00:00\", \"resourceType\": \"WORKSHEET\", \"studentLevel\": \"ADVANCED\", \"languageStyle\": \"适合儿童\", \"resourceStyle\": \"CLASSROOM_READY\", \"courseDesignBased\": true, \"researchEvidenceCount\": 0}}', NULL, 'AI', 'Generated by Mock AI', 1, '2026-09-10 00:28:16');
INSERT INTO `teaching_resource_version` VALUES (5, 2, 4, '{\"title\": \"学生用学习单（4人小组｜平板完成｜约15分钟填写）\", \"blocks\": [{\"key\": \"learning_goal\", \"title\": \"学习目标\", \"content\": \"掌握AI的使用，能够辨别AI真伪信息，合理使用AI。本节课重点练习：区分观点与事实、制定“需要核验”的标准、用可信来源核对信息并说明理由。\"}, {\"key\": \"before_thinking\", \"title\": \"学习准备与初始观点\", \"content\": \"1) 想一想：当你看到一条关于“校园宠物狗”的中文资讯，你会先问什么问题？\\n2) 你认为“AI生成的信息”和“人类写的信息”，哪一个更容易有错误事实？为什么？\\n3) 今天你将阅读两条短资讯，并用“是/否/不确定”标注哪些事实声明需要核验。\"}, {\"key\": \"task_1\", \"title\": \"任务1：引入与标准共建（6分钟）\", \"content\": \"核心任务：观察两条短文本（一条人类撰写、一条AI生成），找出可能的“事实声明”，共同制定“是否需要核验”的判断标准。\\n\\n请完成：\\n1) 在平板上打开两条关于“校园宠物狗”的简短中文资讯。\\n2) 逐条阅读，遇到“可以被验证的事实性句子”时，用“是/否/不确定”标注它是否“需要外部核验”。\\n3) 从两条资讯中，选出你认为“最需要核验”的一条，并写出理由（提示：是否包含具体数字/时间/地点/可核查事件）。\\n\\n记录要求：\\n- 我选的最需核验的一条是：____________________\\n- 理由是（勾选或补充）：包含数字/时间/地点/可核查事件；缺少来源；描述过于完美/夸张；其他：________\"}, {\"key\": \"task_2\", \"title\": \"任务2：同伴互评——标注一致性核对（7分钟）\", \"content\": \"核心任务：交换标注结果，比较判断理由，形成更可靠的“待核验清单”。\\n\\n请完成：\\n1) 与同伴交换标注截图或记录，对比“需要核验”的选择是否一致。\\n2) 讨论分歧：各自用一句话说明理由（句式支架：因为____，所以需要/不需要核验）。\\n3) 修改或确认自己的标注，准备进入下一步核验。\\n\\n记录要求：\\n- 我和同伴达成一致的“待核验清单”（列出1—3条）：____________________\\n- 最重要的一条理由是：____________________\"}, {\"key\": \"task_3\", \"title\": \"任务3：选择两项进行来源核对与判定（课堂分段完成，合计17分钟）\", \"content\": \"核心任务：从给定AI资讯中任选两条，各查找至少一个可信来源进行对照，并说明是否采信及理由；最后列举两种类似风险情境。\\n\\nA. 选择与检索\\n1) 我选择核对的第1条信息是：____________________\\n2) 我在“可信来源目录”中选择的来源是（政府/机构/权威媒体）：____________________\\n3) 关键词检索策略（地名+事件+日期/机构名+公告）：____________________\\n\\nB. 对照与判定（重复以下格式，完成两条）\\n【第1条】\\n- 事实声明摘录：____________________\\n- 找到的来源链接/截图：____________________\\n- 对照结果（一致/不一致/无法确定）：____________________\\n- 结论：我（采信/不采信）这条信息。\\n- 理由（基于证据）：____________________\\n\\n【第2条】\\n- 事实声明摘录：____________________\\n- 找到的来源链接/截图：____________________\\n- 对照结果（一致/不一致/无法确定）：____________________\\n- 结论：我（采信/不采信）这条信息。\\n- 理由（基于证据）：____________________\\n\\nC. 迁移应用\\n- 我还想到两个“类似的AI信息风险情境”（如AI生成的健康建议/本地新闻/学校通知等）：\\n1) ____________________；核验思路：____________________\\n2) ____________________；核验思路：____________________\"}, {\"key\": \"evidence_record\", \"title\": \"证据留存\", \"content\": \"为便于评估，请确保提交/保存以下内容：\\n1) 你在平板上的“是/否/不确定”标注截图或记录；\\n2) 用于核对的两则可信来源链接或截图；\\n3) 你口头或文字的判定与理由（可在平板笔记中录音/打字）。\"}, {\"key\": \"ai_interaction_record\", \"title\": \"AI互动记录（仅记录本次使用的AI相关内容）\", \"content\": \"1) 我的初始观点/担心：____________________\\n2) AI提供的贡献（例如展示AI生成资讯、提示风险点、投影通用流程图等）：____________________\\n3) 我的决定：接受/修改/拒绝 哪一部分，理由是：____________________\\n4) 我的观点变化（简要总结）：____________________\"}, {\"key\": \"reflection\", \"title\": \"反思与改进\", \"content\": \"1) 今天我做对的一件事是：____________________\\n2) 下次我会改进的一点是：____________________\\n3) 如果再遇到“AI生成的本地新闻/健康建议/学校通知”，我将首先检查：____________________\"}, {\"key\": \"final_output\", \"title\": \"最终输出汇总\", \"content\": \"请按顺序检查并提交：\\n- 标注记录（含“最需核验”的理由）\\n- 同伴互评后的“待核验清单”\\n- 两条信息的“来源—声明—对照—结论—理由”\\n- 两个类似风险情境及核验思路\\n- AI互动记录（如有）\"}], \"metadata\": {}}', NULL, 'TEACHER', 'Edited by teacher', 1, '2026-09-10 00:41:06');
INSERT INTO `teaching_resource_version` VALUES (6, 3, 1, '{\"title\": \"4人小组课堂任务卡（共4张，每活动1张）\", \"blocks\": [{\"key\": \"card8014\", \"title\": \"任务卡1：引入与标准共建——辨别AI信息真伪\", \"content\": \"【目标】掌握AI的使用，能够辨别AI真伪信息，合理使用AI。\\n【情境/问题】老师会发来两条关于“校园宠物狗”的简短中文资讯，其中一条是人类写的，另一条是AI生成的。哪一条更需要查证？为什么？\\n【步骤】\\n1.拿到两条资讯后，在平板上用“是/否/不确定”标注每条里出现的“事实声明”（包含数字/时间/地点/可核查事件的句子）。\\n2.和同伴讨论：哪一条最需要外部核验？把理由写下来。\\n3.一起制定“是否需要核验”的班级标准，并交给老师汇总。\\n【时间】最多6分钟（含讨论与提交）\\n【个人/小组方式】4人小组内两人结对完成标注与讨论；全组形成1份“标准建议”。\\n【材料或AI】平板；“标注模板（是/否/不确定）”；“关键特征提示卡（数字/时间/地点/可核查事件）”；AI将展示AI生成资讯并提示风险点供对照。\\n【最终产出】(1)个人标注截图；(2)小组提出1—2条“需核验信息”的判断标准。\\n【完成标准】(1)明确指出了资讯中的事实声明；(2)标注理由围绕“是否可验证”而不是喜好；(3)小组标准至少包含“包含具体数字/时间/地点/可核查事件”中的两项。\"}, {\"key\": \"card8015\", \"title\": \"任务卡2：同伴互评——标注一致性核对\", \"content\": \"【目标】通过比较与解释，形成更可靠的“待核验清单”，提升判断一致性。\\n【情境/问题】你和同伴的标注不一样时，谁的理由更可靠？如何让全班更快达成一致？\\n【步骤】\\n1.在小组内交换上一环节的标注结果。\\n2.对照“同伴互评清单”，检查对方是否：(a)明确圈出了事实声明；(b)理由基于可验证性。\\n3.用“理由句式支架”说明分歧：因为____，所以需要/不需要核验。\\n4.修改或确认自己的标注，准备进入下一步“实际核验”。\\n【时间】最多7分钟\\n【个人/小组方式】4人小组两两互评；每人至少被评价一次。\\n【材料或AI】“同伴互评清单”；“理由句式支架”卡片；AI提供“常见不可信信号”提示（如缺少来源、过于完美/夸张描述）。\\n【最终产出】(1)更新后的标注记录；(2)一句统一后的“待核验”理由。\\n【完成标准】(1)标注—理由匹配；(2)对分歧能说出“依据什么特征”来决定；(3)小组形成1条明确的“待核验清单”条目。\"}, {\"key\": \"card8016\", \"title\": \"任务卡3：选择两项进行来源核对与判定\", \"content\": \"【目标】学会用可信来源对照事实声明，做出“采信/不采信”的判断。\\n【情境/问题】当你看到AI生成的资讯时，怎样用权威来源快速核对关键信息？\\n【步骤】\\n1.从老师提供的AI资讯中任选两条。\\n2.各查找至少一个可信来源（政府/机构/权威媒体），把链接或截图粘贴到“核验工作单”。\\n3.逐条对照“事实声明”：来源是否支持/反驳？是否存在不一致？\\n4.写出结论：“采信”或“不采信”，并用一句话给出依据。\\n【时间】最多17分钟\\n【个人/小组方式】4人小组协作：A检索员、B来源审核员、C记录员、D核对员；完成后轮换角色。\\n【材料或AI】平板；“核验工作单（声明列/来源列/对照结果/结论列）”；“可信来源目录”；“关键词策略卡（地名+事件+日期/机构名+公告）”；AI仅提供检索入口与关键词建议，并自动过滤不在允许目录的网站。\\n【最终产出】(1)两份来源链接/截图；(2)“声明—来源”对照结果；(3)每条的结论与依据。\\n【完成标准】(1)为所选两条信息各提供至少一个可信来源；(2)存在“来源—声明”的逐项对照；(3)明确表达“采信/不采信”并给出证据化理由。\"}, {\"key\": \"card8017\", \"title\": \"任务卡4：汇报与迁移——列举类似情况\", \"content\": \"【目标】总结核验方法，并能迁移到其他AI信息风险情境。\\n【情境/问题】除了“校园宠物狗”，还有哪些场景容易被AI信息影响？你会怎么核验？\\n【步骤】\\n1.小组用1分钟在全班分享：我们是如何核对这两条信息的（关键步骤）。\\n2.观看他组分享，共同归纳“通用核验流程图”的补充意见。\\n3.独立在平板上列出至少两种“类似的AI信息风险情境”（例如：AI生成的健康建议/本地新闻/学校通知）。\\n4.为每个情境写出简要“核验思路”（要查什么、去哪里查）。\\n【时间】最多10分钟\\n【个人/小组方式】先小组合作准备1分钟汇报，再个人独立完成迁移列举。\\n【材料或AI】“汇报提纲模板”；“通用核验流程图”（由AI汇总投影）；“情境列举提示卡（领域/风险点/应对动作）”。\\n【最终产出】(1)小组口头/书面汇报要点；(2)个人至少2个相似情境及核验思路。\\n【完成标准】(1)正确识别出至少两条需核验的信息；(2)能说出完整核验步骤；(3)能列举至少两种类似情境并写出可行的核验做法。\"}], \"metadata\": {\"grade\": 4, \"format\": \"4人小组\", \"devices\": [\"TABLET\"], \"criteria\": true, \"provider\": \"spark\", \"quantity\": 4, \"timeHint\": true, \"projectId\": 1020, \"difficulty\": \"适中\", \"generatedAt\": \"2026-09-10T07:37:12.645955+00:00\", \"resourceType\": \"TASK_CARD\", \"studentLevel\": \"ADVANCED\", \"languageStyle\": \"适合儿童\", \"lessonMinutes\": 40, \"resourceStyle\": \"CLASSROOM_READY\", \"courseDesignBased\": true, \"researchEvidenceCount\": 0}}', NULL, 'AI', 'Generated by Mock AI', 1, '2026-09-10 15:37:12');
